// src/viewer/IfcViewer.tsx
//
// 3D viewer for Free Field. Owns the OBC world (scene/camera/renderer)
// and the @thatopen/fragments FragmentsModels instance. Subscribes to
// useIfcFiles for the active building, mirrors "latest version" rows
// into the live viewer, and disposes the world on unmount.
//
// Task 20 §1.8.1: this component is decoupled from useViewerStore
// (which lives in apps/settings). The store is passed in via the
// `viewerSlice` prop. If no slice is provided, the viewer runs in
// no-op mode (level plan state is local-only). This is the seam
// that lets the viewer live in a shared package without importing
// a Settings-local store.
//
// Task 16 replaces OBC.Views cut-plane level views with a true 2D
// plan-drawing generated by OBC.TechnicalDrawings + OBC.EdgeProjector.
// The LevelPlanController wraps that logic; the IfcViewer only knows
// `controller.open(storeyName) / .close() / .dispose()`.
//
// Pattern follows the ground-truth example in
// engine_fragment/packages/fragments/src/Importers/IfcImporter/examples/HelloWorldSchema/example.ts
// (adapted for the v3.0 FragmentsModels API where the worker URL is
// passed directly to the constructor, not fetched via getWorker()).
//
// No raw three.js — everything via OBC / OBF wrappers, per the TOE
// API Resolution Hierarchy (drift-checked by ESLint).

