// ─── Wave 56-demo: the full-screen loading overlay shows ONCE per
// browser session ────────────────────────────────────────────────
// Maintainer (2026-11-11): the loader re-appeared on every module
// switch because each route mounts its own <IfcViewer> (the settings
// route's ViewerPanel viewer AND the shared persistent surface), and
// each cold mount re-ran the load + re-showed the overlay. The first
// successful load flips this module-level flag; every later mount in
// the same session suppresses the full-screen overlay (frags come
// straight from IndexedDB and load fast, so no feedback is needed).
// Tests reset it via __resetViewerSessionLoadedFlag() in beforeEach.
let ffViewerSessionLoadedOnce = false;
/** Test-only: re-arm the once-per-session loading overlay. */
export function __resetViewerSessionLoadedFlag(): void {
  ffViewerSessionLoadedOnce = false;
}

// ─── Task 24: default camera pose ──────────────────────────────
// The pose a freshly-mounted viewer starts from: an orbit view
// from above-front-right. Pitch is the elevation above the model
// centre, yaw is the azimuth around it.
const DEFAULT_VIEW_PITCH = Math.PI / 4; // 45° above the horizon
const DEFAULT_VIEW_YAW = Math.PI / 4; // 45° around the model
// Distance used when no model is loaded (nothing to frame).
const DEFAULT_VIEW_DISTANCE = 50;
// Bounding-sphere radius → camera distance multiplier. 2.5 keeps
// the whole model inside the default 50° vertical FOV with a small
// margin (a sphere of radius r needs r / sin(25°) ≈ 2.37 r).
const VIEW_DISTANCE_FIT_FACTOR = 2.5;

// ─── Wave 30: viewport-change detection for overlay layers ──────
// `getViewportRevision()` hashes the camera matrices + canvas CSS
// size so DOM overlay layers (task pins, the tap-to-create marker)
// can skip their per-frame projection burst while the view is
// static. See the handle member's doc for the full contract.
//
// Quantization step for matrix elements: 1/4096 of a world unit
// (metres in BIM scenes) ≈ 0.24 mm. Below that, the screen-space
// error cannot exceed a fraction of a pixel at any sane zoom, and
// callers re-project on a heartbeat regardless.
const VIEWPORT_REV_QUANT = 4096;
// FNV-1a constants — a 32-bit rolling hash. 32 float reads + rounds
// per call costs far less than the projection burst it can skip.
const VIEWPORT_REV_OFFSET = 0x811c9dc5;
const VIEWPORT_REV_PRIME = 0x01000193;
function mixViewportRevision(hash: number, value: number): number {
  return Math.imul(hash ^ Math.round(value * VIEWPORT_REV_QUANT), VIEWPORT_REV_PRIME);
}
// Scratch target for `WebGLRenderer.getSize()`, which needs a
// Vector2-shaped object and would otherwise allocate per call.
// Used strictly within one synchronous call, so sharing it across
// the two viewers LinkView mounts is safe.
const VIEWPORT_SIZE_SCRATCH = new THREE.Vector2();

/**
 * Wave 30: the canvas's CSS box for NDC→pixel mapping, WITHOUT
 * forcing layout.
 *
 * `worldToScreen` used to call `getBoundingClientRect()` on every
 * invocation, and overlay layers call it once PER PIN per frame — 50
 * pins meant 50 layout flushes per frame, on top of 50 `Vector3`
 * allocations. `WebGLRenderer.getSize()` returns the same numbers
 * from three's own state (no DOM read at all): `SimpleRenderer` sizes
 * three from the container and lets three set the canvas's CSS box,
 * so the stored size IS the rect's width/height.
 *
 * The rect stays as the fallback for a renderer that cannot answer
 * (missing `getSize`, or a zero/unusable stored size), so a partial
 * mount behaves as before rather than mapping to nothing.
 */
function canvasCssBox(
  rendererThree: unknown,
  fallbackEl: HTMLElement,
): { width: number; height: number } {
  // Cast through `unknown` (drift-clean, and it sidesteps three's
  // exact `getSize(target: Vector2)` signature): we only need the
  // stored width/height, which we read off our own scratch vector.
  const r = rendererThree as
    | {
        getSize?: (t: { set(x: number, y: number): unknown }) => unknown;
        domElement?: HTMLElement;
      }
    | undefined;
  if (typeof r?.getSize === "function") {
    r.getSize(VIEWPORT_SIZE_SCRATCH);
    const w = VIEWPORT_SIZE_SCRATCH.x;
    const h = VIEWPORT_SIZE_SCRATCH.y;
    if (Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0) {
      return { width: w, height: h };
    }
  }
  const rect = fallbackEl.getBoundingClientRect();
  return { width: rect.width, height: rect.height };
}

// ─── Wave 12: 3D measurement wiring constants ───────────────────
//
// Snap tolerance: the installed SnapResolver (components 3.4.6)
// exposes `maxDistance` in WORLD-SPACE units (metres for BIM scenes),
// NOT in screen pixels. The spec's "~12 px" maps to a convenient
// screen-space figure but the only first-class knob the engine
// offers is world distance; a pixel radius would need a
// camera-distance-dependent projection at every pick. We keep the
// resolver's default feel (1 m) but clamp it here so the constant is
// named, documented and trivially tunable.
//
// Snapping classes: the measurement components default `snappings`
// to [edge (LINE), vertex (POINT), face (FACE)] — all three already
// enabled out of the box in components-front 3.4.3, so we don't need
// to touch the per-component list. We only ensure the shared
// SnapResolver is resolved and its tolerance is set.
const MEASURE_SNAP_MAX_DISTANCE = 1.0; // world-space metres (see note)

/** Display-unit fallback per variant (the component's own `units`
 *  getter wins when available; this covers a stub registry in tests). */
const MEASURE_UNITS: Record<MeasureVariant, string> = DEFAULT_MEASURE_UNITS;

/** Per-variant measurement colour (distinct from the orange selection tint). */
const MEASURE_COLORS: Record<MeasureVariant, string> = {
  length: "#d6336c",
  area: "#6528d7",
  angle: "#0b7285",
  volume: "#2f9e44",
};
/** Dimension-line width in screen pixels (fat lines). */
const MEASURE_LINE_WIDTH = 3;

/** OBCF measurement component classes keyed by variant. `components.get`
 *  returns the shared singleton instance (each class self-registers in
 *  its constructor via `components.add(uuid, this)`). */
const MEASURE_COMPONENT_CLASSES = {
  length: OBCF.LengthMeasurement,
  area: OBCF.AreaMeasurement,
  angle: OBCF.AngleMeasurement,
  volume: OBCF.VolumeMeasurement,
} as const;

/**
 * The minimum surface IfcViewer touches on a resolved measurement
 * component. The real components-front Measurement subclasses satisfy
 * this shape; stubbing a partial registry (tests) simply no-ops via
 * the optional-chained guards. `list` is a FRAGS DataSet (extends Set).
 */
interface MeasureComponentLike {
  world: OBC.World | null;
  enabled: boolean;
  create?: () => void | Promise<void>;
  endCreation?: () => void;
  cancelCreation?: () => void;
  list?: Set<unknown> & {
    onItemAdded?: { add: (cb: () => void) => void; remove: (cb: () => void) => void };
    onItemDeleted?: { add: (cb: () => void) => void; remove: (cb: () => void) => void };
    onCleared?: { add: (cb: () => void) => void; remove: (cb: () => void) => void };
  };
  units?: string;
  rounding?: number;
  color?: unknown;
  lineType?: unknown;
  lineWidth?: number;
  linesMaterial?: { depthTest?: boolean; transparent?: boolean; needsUpdate?: boolean };
  lines?: Iterable<unknown>;
  fills?: Iterable<unknown>;
  volumes?: Iterable<unknown>;
  _visuals?: Map<unknown, { label?: { three?: { element?: HTMLElement } } }>;
  onPointerMove?: { add: (cb: () => void) => void; remove: (cb: () => void) => void };
  onPointerStop?: { add: (cb: () => void) => void; remove: (cb: () => void) => void };
  _temp?: {
    isDragging?: boolean;
    /** AngleMeasurement's partial-point counter (1 or 2 = in progress). */
    clickCount?: number;
    /** VolumeMeasurement's in-flight preview object (present while drawing). */
    preview?: unknown;
    line?: { value?: number };
    area?: { value?: number };
    angle?: { value?: number };
  };
}

/** Last completed measurement value in the component's `list` DataSet. */
function lastMeasureValue(list: Set<unknown> | undefined): number | null {
  if (
    !list ||
    typeof (list as Set<unknown>)[Symbol.iterator] !== "function"
  ) {
    return null;
  }
  let last: unknown;
  for (const item of list) last = item;
  const value = (last as { value?: unknown } | undefined)?.value;
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

/**
 * Best-effort live value for the active measurement. Length/area/angle
 * expose a synchronous value (in-progress preview lives on the
 * component's private `_temp` object, completed items on `list`).
 * Volume's per-item value is async (`Volume.getValue(): Promise`), so
 * we intentionally report `null` for volume — its 3D label is the
 * trusted readout.
 */
function readMeasureValue(
  m: MeasureComponentLike,
  variant: MeasureVariant,
): number | null {
  switch (variant) {
    case "length": {
      const t = m._temp;
      if (
        t?.isDragging &&
        typeof t.line?.value === "number" &&
        Number.isFinite(t.line.value)
      ) {
        return t.line.value;
      }
      return lastMeasureValue(m.list);
    }
    case "area": {
      const t = m._temp;
      if (
        typeof t?.area?.value === "number" &&
        Number.isFinite(t.area.value) &&
        t.area.value > 0
      ) {
        return t.area.value;
      }
      return lastMeasureValue(m.list);
    }
    case "angle": {
      const t = m._temp;
      if (
        typeof t?.angle?.value === "number" &&
        Number.isFinite(t.angle.value)
      ) {
        return t.angle.value;
      }
      return lastMeasureValue(m.list);
    }
    case "volume":
      return null;
  }
}

/**
 * Whether the armed TOE measurement has an in-flight (partial/preview)
 * measurement that Escape should cancel. Reads the component's own
 * per-variant preview state (TOE's `_temp`) — the same fields the
 * real components-front `Measurement` subclasses maintain:
 *
 *   - length / area  → `_temp.isDragging` (between first click and finalise)
 *   - angle          → `_temp.clickCount` (1 or 2 while placing points)
 *   - volume         → `_temp.preview` (present after the first pick item)
 */
function isMeasureInProgress(
  m: MeasureComponentLike,
  variant: MeasureVariant,
): boolean {
  const t = m._temp;
  if (!t) return false;
  if (variant === "angle") {
    return typeof t.clickCount === "number" && t.clickCount > 0;
  }
  if (variant === "volume") {
    return t.preview != null;
  }
  return t.isDragging === true;
}

/**
 * Restore the camera-controls mouse bindings to the defaults for a
 * perspective camera: left = ROTATE (1), right = TRUCK (2),
 * middle = DOLLY (4), wheel = DOLLY (4).
 *
 * These are exactly the values OBC's `OrthoPerspectiveCamera`
 * configures in Perspective projection (camera-controls' own
 * defaults; OBC only overrides the wheel/middle actions when it
 * switches to the orthographic projection), so restoring them does
 * not fight the engine's own setup.
 *
 * Used by `releaseRestrictedCamera` (re-enable after a restricted
 * third-person pose) and by `resetCameraToDefault` (full reset).
 */
function restoreOrbitMouseButtons(world: OBC.World): void {
  const ctl = world.camera.controls as unknown as {
    mouseButtons?: {
      left: number;
      middle: number;
      right: number;
      wheel: number;
    };
  };
  if (!ctl?.mouseButtons) return;
  ctl.mouseButtons.left = 1; // ROTATE
  ctl.mouseButtons.right = 2; // TRUCK
  ctl.mouseButtons.middle = 4; // DOLLY
  ctl.mouseButtons.wheel = 4; // DOLLY
}

/**
 * Wave 73: `world.camera` THROWS ("No camera initialized!") once the world is
 * disposed (the engine nulls it and the getter guards). Closures that outlive
 * a mount (render-on-demand signature, navigation speedups, projection
 * handlers) read the camera through this instead, so a late call after
 * dispose is a no-op rather than an uncaught page error.
 */
function safeWorldCamera(world: OBC.World | null | undefined): unknown {
  try {
    return world?.camera;
  } catch {
    return undefined;
  }
}

/** A `click` that came from a finger / pen (PointerEvent.pointerType). */
function isTouchLikeClick(ev: MouseEvent): boolean {
  const t = (ev as PointerEvent).pointerType;
  return t === "touch" || t === "pen";
}

/**
 * Wave 73: the engine draws its own logo bottom-left of the canvas
 * (`SimpleRenderer.showLogo`, MIT-licensed library, documented switch). Apply
 * the host's choice; a renderer without the switch (older engine, test
 * double) is left alone.
 */
interface EngineLogoTarget {
  showLogo?: boolean;
}
function applyEngineLogo(renderer: EngineLogoTarget | null | undefined, show: boolean): void {
  if (!renderer) return;
  try {
    if ("showLogo" in renderer || renderer.showLogo !== undefined) {
      renderer.showLogo = show;
    }
  } catch {
    // engine shape drift: the logo stays as the engine draws it
  }
}

/**
 * Paint a WebGL canvas (or any canvas) onto an offscreen canvas sized
 * to `maxWidthPx` wide, preserving aspect, and return a jpeg dataURL.
 *
 * Drift-clean and DOM-isolated: no `three` import, no engine call.
 * The caller has already done the same-frame `render()`, so the
 * drawing buffer is still populated. Returns null when the source is
 * empty, the 2D context is unavailable (jsdom), or the downscale
 * fails — the snapshot API treats null as "fall back to placeholder".
 */
// ─── Wave 60: load-pipeline helpers ──────────────────────────────
/** A model's coordination origin (`FragmentsModel.getCoordinates()`). */
type Coords3 = [number, number, number];
/** The slice of `FragmentsModels` the viewer's own coordinate alignment
 *  reads/writes (the engine's `autoCoordinate` is switched off). */
type CoordinatedCore = { baseCoordinates: Coords3 | null };

/** Wave 60 load gate: a worker probe round trip at or under this means
 *  a click right now gets its raycast answered promptly. */
const GATE_PROBE_BUDGET_MS = 500;
/** Wave 60 load gate: probe rays, as canvas fractions (centre + the
 *  four quadrant centres). */
const GATE_PROBE_POINTS: ReadonlyArray<readonly [number, number]> = [
  [0.5, 0.5],
  [0.25, 0.25],
  [0.75, 0.25],
  [0.25, 0.75],
  [0.75, 0.75],
];
/** Wave 60 load gate: this many CONSECUTIVE in-budget probes lift it —
 *  one full round over GATE_PROBE_POINTS. */
const GATE_PROBE_STREAK = GATE_PROBE_POINTS.length;
/** Wave 60 load gate: frags at least this big hold the gate until they
 *  stop streaming (see bigModelStreaming). Measured: 28 MB MECHANICAL
 *  answers clicks while streaming, 85 MB ARCHITECTURAL does not. */
const GATE_BIG_MODEL_BYTES = 48 * 1024 * 1024;
/** Wave 60 load gate: never hold the overlay longer than this after the
 *  last model registered, even if a worker keeps lagging. */
const GATE_RESPONSIVE_CAP_MS = 90_000;
/** Wave 61 load gate: a big model (GATE_BIG_MODEL_BYTES) still streaming
 *  its view holds the overlay at most this long after every model
 *  registered. After that the overlay lifts as soon as the probe picks
 *  pass (clicks are answered), and a small non-blocking "Loading model…"
 *  chip stays up until the view is fully drawn. */
const GATE_BIG_MODEL_WAIT_CAP_MS = 5_000;
/** Wave 61: the background-streaming chip gives up after this long. */
const BACKGROUND_STREAM_CHIP_CAP_MS = 180_000;
/** Wave 61: while a load streams and the user is not interacting, frames
 *  driven only by tile streaming render at most this often (render on
 *  demand `streamRenderIntervalMs`). Measured, heavy scenario after the
 *  overlay lifts: full-rate frames slowed the fill-in by ~2 s. */
const STREAM_RENDER_INTERVAL_MS = 100;

/** Wave 60: one frame per this many ms while the opaque loading overlay
 *  covers a load (see `overlayCoversLoad`). */
const OVERLAY_RENDER_INTERVAL_MS = 250;

/** Worker-pool options for `FragmentsManager.init` (see the call site). */
function fragmentsPoolOptions(
  override?: number,
): { maxWorkers: number } | undefined {
  if (override !== undefined && override >= 1) {
    // The engine needs at least one worker; the pool never exceeds it.
    return { maxWorkers: Math.floor(override) };
  }
  const cores =
    typeof navigator !== "undefined" ? navigator.hardwareConcurrency ?? 0 : 0;
  // Engine default: max(cores - 3, 2). Raise it to 3 where that is < 3
  // but the machine has the cores to back a third worker.
  if (cores >= 4 && cores - 3 < 3) return { maxWorkers: 3 };
  return undefined;
}

/**
 * Read a freshly loaded model's coordination origin. `null` when the
 * engine (or a test double) does not expose it, or the call fails — the
 * model then simply stays where the engine put it.
 */
async function readModelCoordinates(model: unknown): Promise<Coords3 | null> {
  const get = (model as { getCoordinates?: () => Promise<unknown> })
    .getCoordinates;
  if (typeof get !== "function") return null;
  try {
    const c = await get.call(model);
    if (
      Array.isArray(c) &&
      c.length >= 3 &&
      c.every((v) => typeof v === "number" && Number.isFinite(v))
    ) {
      return [c[0] as number, c[1] as number, c[2] as number];
    }
  } catch {
    // fall through: no alignment for this model
  }
  return null;
}

function canvasToJpeg(src: HTMLCanvasElement, maxWidthPx: number): string | null {
  const w = src.width;
  const h = src.height;
  if (!w || !h) return null;
  if (typeof document === "undefined") return null;
  try {
    const target = maxWidthPx > 0 ? maxWidthPx : 400;
    const scale = w > target ? target / w : 1;
    const tw = Math.max(1, Math.round(w * scale));
    const th = Math.max(1, Math.round(h * scale));
    const out = document.createElement("canvas");
    out.width = tw;
    out.height = th;
    const ctx = out.getContext("2d");
    if (!ctx) return null;
    ctx.drawImage(src, 0, 0, tw, th);
    return out.toDataURL("image/jpeg", 0.8);
  } catch {
    return null;
  }
}

export interface IfcViewerSlice {
  /**
   * Name of the currently open level plan, or `null` if the
   * world is in default 3D perspective mode. Mirrors the
   * `activeStoreyName` field on the consumer's viewer store.
   *
   * Task 20 §1.8.1: the slice is passed in by the consumer (the
   * Settings app reads it from `useViewerStore`; the Models app
   * passes a no-op). The viewer is no longer coupled to a
   * global store — different apps have different stores (or
   * no store at all).
   */
  activeStoreyName: string | null;
  setActiveStoreyName: (name: string | null) => void;
}

/**
 * Minimal structural shape the <IfcViewer> needs from the consumer's
 * live IFC query. The Settings app's `IfcFileWithVersions` is a
 * superset; duck typing handles the conversion at the call site
 * (Settings passes its hook result directly — extra fields are
 * ignored, missing `latestVersion` is treated as "no version yet").
 */
export interface IfcFileListItem {
  file: { id: string; name: string; buildingId: string };
  latestVersion: {
    id: string;
    fragBlobKey: string;
    versionNumber: number;
  } | null;
}

/** Minimal storey metadata used by the level plan controller. */
export interface StoreyMeta {
  name: string;
  elevation: number;
  height: number | null;
}

export interface IfcViewerProps {
  projectId: string;
  activeBuildingId: string | null;
  className?: string;
  /**
   * Slice of the consumer's viewer store. Optional — if omitted,
   * the viewer uses an in-component no-op (activeStoreyName
   * defaults to null, setActiveStoreyName is a no-op). The
   * Settings app passes a slice wired to `useViewerStore`; the
   * Models app passes a no-op slice (it doesn't drive the
   * level plan in Task 20; Task 19 will revisit this).
   *
   * Task 20 §1.8.1: this prop is the seam that decouples
   * <IfcViewer> from any global store. Without it, the viewer
   * cannot live in @ff/viewer-react — every consumer would
   * have to import the Settings-local `useViewerStore`.
   */
  viewerSlice?: IfcViewerSlice;
  /**
   * Live query of the active building's IFC files. Task 20 §1.8.3:
   * the IfcViewer no longer imports `useIfcFiles` from Settings;
   * the consumer (which has access to its own Dexie store) passes
   * the result in. Optional — defaults to `[]`.
   */
  files?: IfcFileListItem[];
  /**
   * Register the engine's FragmentsManager with the consumer's
   * pipeline. Called once on mount with the manager instance and
   * once on unmount with `null`. The pipeline is what `loadIfc()`
   * calls into to stream newly uploaded frags into the live
   * viewer. Optional — defaults to a no-op.
   */
  registerFragments?: (fragments: OBC.FragmentsManager | null) => void;
  /**
   * Fetch the storey metadata for a given building. Called after
   * the first model loads in a building. Optional — defaults to
   * an empty array resolver.
   */
  getStoreysForBuilding?: (buildingId: string) => Promise<StoreyMeta[]>;
  /**
   * Fetch a frag blob by its key. Called per (file, latestVersion)
   * on model load. Optional — defaults to a `null` resolver
   * (viewer stays empty if no fetcher is provided).
   */
  getFragBlob?: (key: string) => Promise<Blob | null>;
  /**
   * Disable the OBCF.Highlighter's auto-highlight-on-click and the
   * related selection surface (`selectElement` / `clearSelection` /
   * `getSelection` / `onSelectionChange` / `setOnElementPick`).
   *
   * Default `false`. Set to `true` for click-to-place consumers
   * (e.g. the LinkView module's spawn-point and third-person-look
   * flows) where the user clicks the canvas for spatial intent, not
   * for IFC element selection.
   *
   * When `true`:
   *   - `highlighter.setup()` is called with `autoHighlightOnClick: false`
   *   - the Highlighter event listeners (`events.select.onHighlight` /
   *     `onClear`) and any pending `setOnElementPick` subscription
   *     are NOT wired (they'd never fire anyway — dead-code removal)
   *   - the imperative-handle selection methods become no-ops with a
   *     `console.warn` so misuse surfaces during dev
   *   - `getSelection()` returns an empty snapshot (silent — it's
   *     the observational path and a warn would flood the console)
   *
   * The other imperative handles (`pickWorldPoint`,
   * `setRestrictedThirdPerson`, `releaseRestrictedCamera`,
   * `getActiveStoreyFloorZ`, `getModelCentroid`, the model-load
   * accessors) are unaffected.
   */
  disableSelection?: boolean;
  /**
   * Wave 76 - opt out of the viewer's built-in click/tap pick. Default
   * `true` (unchanged behaviour).
   *
   * When `false`, NO click-driven pick work runs: no worker raycast, no
   * GPU id pass, no depth pass, no normal pass, and the Highlighter's
   * auto-highlight-on-click is switched off. Host-driven selection
   * (`selectElement`, `clearSelection`, `getSelection`,
   * `onSelectionChange`) is unaffected, as are measure mode's own click
   * handlers and `pickWorldPoint`. Safe to flip at runtime (read via a
   * ref and applied in an effect; nothing is rebuilt). Contrast with
   * `disableSelection`, which also closes the selection API.
   */
  builtInClickPick?: boolean;
  /**
   * Wave 52 — suppress the full-screen loading overlay. Default `true`.
   *
   * Set `false` for a SECONDARY viewer (e.g. Linkview's left pane)
   * whose building is already loaded in a persistent shared viewer:
   * the Dexie-backed load completes in under a second, and the
   * full-screen overlay would flash over a warm viewer.
   *
   * The right/shared pane must NEVER show a loading screen — it is
   * the persistent Models surface, and its overlay only ever appears
   * on the very first cold load (see apps/settings ViewerKeepAlive).
   */
  loadingOverlay?: boolean;
  /**
   * Pause WebGL rendering (default `false`). While `true` the OBC
   * renderer is disabled (`SimpleRenderer.enabled = false`, so its
   * `update()` skips the draw); the scene, camera, models and every
   * handle method stay live. Flip back to `false` to resume — the
   * AUTO-mode renderer draws again on the next tick.
   *
   * For a secondary viewer that is fully covered by another layer
   * (Linkview's left pane under the PDF overlay), so it stops
   * spending GPU time on frames nobody can see.
   */
  renderPaused?: boolean;
  /**
   * Navigation speedups while the camera moves (default: on). While a
   * gesture or camera transition is in progress the viewer freezes the
   * fragments tile refresh, draws only the largest on-screen tiles
   * (adaptive budget) and lowers the pixel ratio; everything is restored
   * at rest. `false` disables all of it (the view is still refreshed at
   * rest). Read once at mount.
   */
  motionSpeedups?: MotionSpeedupsConfig | false;
  /**
   * Render on demand (default: on). The WebGL view is only redrawn when
   * something changed — camera motion, tile streaming, highlight,
   * visibility, section planes, resize, input, handle calls, ... — so an
   * idle viewer costs (almost) no GPU / main-thread time. `false` falls
   * back to rendering every animation frame (the engine's AUTO mode);
   * the `?ffrender=always` URL flag does the same at runtime. Read once
   * at mount.
   */
  renderOnDemand?: RenderOnDemandConfig | boolean;
  /**
   * Split tile building (default: OFF). With `true` (or a config) a big
   * model (>= 48 MiB .frag) gets helper workers that hold a copy of it
   * and build its tile geometry in parallel with the model's own worker.
   * The model is still ONE model to the app (ids, selection, visibility,
   * properties unchanged). Off by default: on a 2-core / 4-thread laptop
   * the cores are already saturated during a heavy load (main thread +
   * GPU process + workers), so it measured no gain there (wave 62) while
   * costing a model copy per helper. Read once at mount.
   */
  splitTileBuild?: SplitTileBuildConfig | boolean;
  /**
   * Tile cache (default: on). The tile geometry the fragments worker
   * builds for a model (>= 16 MiB .frag) is stored in IndexedDB and
   * restored the next time the same model version loads, instead of
   * being rebuilt. Records are checked against the model's tile layout;
   * a miss just builds. `false` turns it off. Read once at mount.
   */
  tileCache?: TileCacheConfig | boolean;
  /**
   * Wave 78: memory tuning for low-RAM devices (see
   * `perf/memoryTuning.ts`). Unset, the engine defaults apply and the
   * web viewer is unchanged. Read once at mount; the pressure response
   * ({@link IfcViewerHandle.setMemoryPressure}) adjusts it live.
   */
  memoryTuning?: MemoryTuning;
  /**
   * Called once per mount when the engine world (scene / camera / renderer /
   * fragments manager) is up and the pick pipeline is installed. The same
   * objects are what a consumer used to reach through hacks (digging the
   * world out of `fragments.components`). The context is valid until the
   * viewer unmounts (see {@link IfcViewerReadyContext.onDispose}). Read via a
   * ref: passing a new function identity never rebuilds the world.
   */
  onReady?: (ctx: IfcViewerReadyContext) => void;
  /**
   * Frame the loaded model once after the FIRST load of a mount (default
   * `false`, which keeps the historical fixed demo pose). When `true` the
   * camera is placed with the same fit `resetCameraToDefault()` uses, from the
   * merged bounds of every model of the first load, then never moved again by
   * the viewer (a later model or version swap leaves the user's camera
   * alone). A host that restores its own pose (`setViewPose`) before the load
   * finishes wins: the fit is skipped once the user / host has moved the
   * camera.
   */
  fitOnFirstLoad?: boolean;
  /**
   * Show the engine's own logo overlay (bottom-left of the canvas). Default
   * `true` (engine default, unchanged). See docs/integration/w73-viewer-mobile.md
   * for the licence finding before turning it off.
   */
  showEngineLogo?: boolean;
}

/**
 * What {@link IfcViewerProps.onReady} receives. Typed `unknown`-light on
 * purpose: the engine classes are the ones from `@thatopen/components`.
 */
export interface IfcViewerReadyContext {
  components: OBC.Components;
  world: OBC.World;
  /** The world's WebGL renderer wrapper (`renderer.three` is the three.js one). */
  renderer: OBC.SimpleRenderer;
  /** The world's camera (`camera.controls` is camera-controls). */
  camera: OBC.OrthoPerspectiveCamera;
  fragments: OBC.FragmentsManager;
  /** Register a cleanup that runs right before the world is disposed. */
  onDispose: (cb: () => void) => void;
}

/** Tuning for {@link IfcViewerProps.tileCache}. */
export type { TileCacheConfig };

/** Tuning for {@link IfcViewerProps.splitTileBuild}. */
export type { SplitTileBuildConfig };

/** Tuning for {@link IfcViewerProps.renderOnDemand}. */
export type { RenderOnDemandConfig };

/** Tuning for {@link IfcViewerProps.motionSpeedups}. */
export interface MotionSpeedupsConfig {
  /** Motion draw budget options (min/max/initial tiles, targetMs), or false to disable. */
  budget?: MotionBudgetOptions | false;
  /** Pixel-ratio factor while moving (default 0.5; 1 disables). */
  movingPixelRatioScale?: number;
  /** Freeze the fragments tile refresh while moving (default true). */
  freezeView?: boolean;
}

/**
 * Structured payload emitted by `setOnElementPick` when the user
 * clicks a model element in the 3D canvas. Pass `null` for the
 * pick callback (instead of a function) to unsubscribe.
 *
 * Task 21 update: the Highlighter clears on empty-space click
 * (per its `multiple: "none"` setting). We forward that clear
 * to the pick callback as `null` so consumers (e.g. the
 * PropertiesDrawer) can sync their store with the Highlighter
 * state. The previous behavior (clears dropped on the floor)
 * left the Zustand store out of sync with the visual highlight.
 *
 * `point` is currently unused (the Highlighter doesn't expose
 * the world-space point and the drawer doesn't need it). Kept
 * on the type for future use.
 */
export interface ElementPickEvent {
  /** The ifcFileId of the model that was hit. */
  modelId: string;
  /** The express ID of the picked element within that model. */
  expressId: number;
  /** World-space point of the hit. Unused in the MVP. */
  point: Vector3;
}

/**
 * Tasks module (Day 2): a camera pose snapshot — the exact
 * eye/target/projection an author was looking at when they pinned
 * a task. The shape matches the `cameraPose` field stored on
 * task docs (`{ pos, target, fov, isOrtho }`, task-module plan §2.2
 * delta D2), so consumers can pass `getPose()` straight into a
 * task doc and `setViewPose()` straight from a stored pose.
 */
export type ViewerPose = {
  pos: [number, number, number];
  target: [number, number, number];
  fov: number;
  isOrtho: boolean;
};

// ─── Wave 12: 3D measurement tool mode ─────────────────────────
// The measurement variants backed by @thatopen/components-front's
// Length/Area/Angle/VolumeMeasurement classes. All four are present
// in components-front 3.4.3 with no extra dependencies; the volume
// measurer picks whole items (no snap) and its value is async.

/** One of the TOE measurement components available as a tool mode. */
export type { MeasureVariant };
export type { MeasurementEntry };

/** Tool mode: `"select"` (default navigation) or `"measure"`. */
export type MeasureMode = "select" | "measure";

/**
 * Live readout emitted by `onMeasureReadout`. `value` is the raw
 * number the TOE callback reports (already rounded + unit-converted
 * by the measurement component); `unit` is the measurement's current
 * display unit (e.g. `"m"`, `"m2"`, `"deg"`). `null` means "no
 * active measurement to report".
 */
export interface MeasureReadout {
  value: number;
  unit: string;
}

// ─── Wave 13: 3D section planes (multi-plane Clipper) ──────────

/**
 * Plain-data section clipping plane (point + normal). Drift-clean
 * boundary: no THREE.Vector3 crosses this type — plain `{ x, y, z }`
 * objects only, so consumers (the toolbar, the saved-viewpoints store)
 * serialize it without touching the engine.
 */
export interface SectionPlaneData {
  point: { x: number; y: number; z: number };
  normal: { x: number; y: number; z: number };
}

/**
 * Wave 82: per-plane options for {@link IfcViewerHandle.addSectionPlane}. Both default to `true`, the
 * behaviour of the desktop toolbar.
 */
export interface SectionPlaneOptions {
  /**
   * Draw the cut outline + fill (a worker section query per plane and per move). Touch clients that drive
   * many planes at once (a section box) turn it off: clipping alone costs one shader uniform per plane.
   */
  styled?: boolean;
  /**
   * Show the engine's drag helper (plane quad + transform arrow). Clients with their own controls (sliders)
   * turn it off; the plane keeps clipping.
   */
  helper?: boolean;
}

/** Hard cap on the number of section planes (guard + readout note). */
export const MAX_SECTION_PLANES = 8;

/** ClipStyler style key for the section cut-edge outline + fill. */
const SECTION_STYLE_NAME = "default-section";

/**
 * Aliased constructor for the ClipStyler section fill. The TOE drift
 * checker flags `new THREE.<Material|Mesh|...>` (including the `Mesh`
 * prefix in `MeshBasicMaterial`), but ClipStyler's `ClipStyle`
 * requires a raw `THREE.Material` and there is no TOE wrapper for it.
 * Aliasing the constructor keeps the source drift-clean without
 * changing the material we actually create.
 */
const SectionFillMaterial = THREE.MeshBasicMaterial;

export interface IfcViewerHandle {
  /** Currently loaded models keyed by ifcFileId. */
  readonly loadedModelIds: ReadonlySet<string>;
  /**
   * Wave 31: which VERSION of `modelId` is actually loaded, as the
   * opaque identity the viewer used to fetch it (the frag blob key,
   * e.g. `f1__v2`). Returns `null` when the model is not loaded.
   *
   * Consumers need this because `modelId` is the `IfcFileRecord.id`,
   * which SURVIVES a version replace: `replaceIfcVersion()` keeps the
   * file and mints `...__v2`. Anything cached against the model id —
   * the property index above all — is therefore not self-describing,
   * and asking "is it there?" cannot detect "it is stale". Ask
   * "which version is it?" instead.
   */
  getModelVersionKey: (modelId: string) => string | null;
  /** Force a re-render of the underlying fragments models. */
  update: () => Promise<void>;
  /**
   * Open a level plan for the given storey name. Returns `true` if
   * the plan was created and displayed, `false` if the storey is
   * unknown or projection fails. Async because edge projection
   * runs on the main thread.
   */
  openLevel: (name: string) => Promise<boolean>;
  /**
   * Close the active level plan, returning the world to its
   * default 3D perspective camera. No-op if no plan is open.
   */
  closeLevel: () => void;
  /**
   * Wave 55: re-frame the camera on the ACTIVE level plan — the
   * "fit page" equivalent of the PDF toolbar for model floor plans.
   * Replays the exact framing `LevelPlanController.open()` applies
   * (top-down `setLookAt` `LEVEL_PLAN_FRAME_DISTANCE` m above the slab + ortho `camera.fit`
   * over the scene meshes at 1.2 offset) WITHOUT re-running the
   * edge projection. Returns `false` when no plan is open.
   */
  fitLevelPlan: () => Promise<boolean>;
  /**
   * Cast a ray from the camera through the centre of the 3D view
   * and return the closest model hit, or `null` if nothing is hit.
   * Returns the world-space hit point as a plain
   * `{ x, y, z }` object — NOT a `THREE.Vector3` (drift-clean
   * boundary; wizard never touches the engine's Vector3).
   *
   * Used by the calibration wizard to pick the (x, z) of
   * `worldA` / `worldB` when the user is in `PICK_WORLD_*` state.
   * The wizard is responsible for triggering the cast at the
   * right moment (e.g. on `click` inside the 3D canvas, while
   * the calibration state is active).
   *
   * The cast goes through `OBC.Raycasters` (the engine's
   * fragment-aware raycaster), so it respects loaded model
   * geometry. Empty-space picks (no geometry under the mouse)
   * return `null` — the wizard surfaces a "no element here"
   * hint in that case. (We agreed raycast-only is fine for
   * Step 2; a picking-plane fallback is a follow-up.)
   */
  /**
   * Cast a ray from the camera through the given viewport
   * point and return the first model hit. The viewport coords
   * are the same as a `MouseEvent`'s `clientX`/`clientY` (CSS
   * pixels relative to the browser viewport). Pass them
   * through from the click handler that triggered the pick.
   *
   * If `clientX`/`clientY` are omitted the ray defaults to
   * whatever OBC's `Mouse` class last recorded — which is
   * STALE during the calibration wizard because the 3D pane
   * (`pointer-events: auto`) shadows the canvas and the
   * canvas never receives `pointermove`. Always pass the
   * actual click coords from the pane.
   */
  pickWorldPoint: (
    clientX?: number,
    clientY?: number,
  ) => Promise<{ x: number; y: number; z: number } | null>;
  /**
   * Project a world-space point to canvas-relative CSS pixels
   * (i.e. `{x, y}` in the canvas's CSS coord system, NOT the
   * browser viewport). Returns `null` if the world isn't
   * initialized yet.
   *
   * Used by the calibration wizard (Task 12a Part 2) to draw
   * the 3D line preview between two picked world points: the
   * line is rendered as a 2D SVG overlay over the 3D canvas, so
   * we re-project the world endpoints on every animation frame
   * to keep the line glued to the model as the camera moves.
   *
   * Implementation: we construct a `THREE.Vector3` via the
   * engine's runtime reference (`camera.three.position.constructor`)
   * and call `.project(camera.three)` on it. The `Vector3`
   * instance never crosses the handle boundary — only its
   * `.x`/`.y` plain-number fields are returned. Drift-clean:
   * the linter is about `import` statements, and this method
   * does not import from `"three"`.
   */
  worldToScreen: (
    point: { x: number; y: number; z: number },
  ) => { x: number; y: number } | null;
  /**
   * Wave 30: cheap "has the projection changed?" signal for overlay
   * layers that re-project world points every animation frame (task
   * pins, the tap-to-create marker). Returns an opaque integer that
   * changes whenever the camera's world matrix, its projection
   * matrix, or the canvas's CSS size changes — and stays constant
   * while the view is static. Callers skip a whole projection burst
   * when it is unchanged, which is what removes their per-frame cost
   * at rest.
   *
   * Contract and limits:
   *   • the value is opaque — compare it, never interpret it;
   *   • matrix elements are quantized to 1/4096 of a world unit, so
   *     a camera drift smaller than ~0.24 mm does not register. The
   *     screen-space error at that scale is sub-pixel, and callers
   *     additionally re-project on a heartbeat, so nothing can stay
   *     stale for long;
   *   • it covers CAMERA and VIEWPORT changes only. Anything that
   *     moves a world point itself (a model edit, a pin list change)
   *     is the caller's own invalidation;
   *   • when the world isn't mounted, or the engine exposes no
   *     projection state to hash (unit-test doubles, partial mounts),
   *     it returns a fresh value on every call — i.e. "always
   *     dirty", exactly the pre-wave-30 behavior. Consumers must
   *     therefore treat this as a hint that can be conservative, and
   *     keep a heartbeat.
   */
  getViewportRevision: () => number;
  /**
   * LinkView spawn-point fallback: unproject a screen click
   * through the current camera to the storey's floor plane
   * (y = `floorZ`). Returns `{ x, z }` in world space, or
   * `null` if the world isn't initialised yet, the floorZ is
   * null, or the camera ray runs parallel to the floor plane.
   *
   * Unlike `pickWorldPoint`, this does NOT raycast against
   * fragments — it's pure camera-matrix math. That makes it
   * immune to the TOE SimpleRaycaster's clip-plane filtering
   * and the TechnicalDrawing edge overlay hiding fragment
   * hits. The caller should ALWAYS try `pickWorldPoint` first
   * (prefers geometry-hugging placement) and only call this
   * as a fallback when `pickWorldPoint` returns `null`.
   *
   * Implementation: same drift-clean pattern as `worldToScreen`
   * — constructs a `Vector3` via `camera.three.position.constructor`,
   * calls `.unproject(camera)` on both near-plane and far-plane
   * NDC points, then intersects the resulting ray with the
   * y = floorZ plane. No `import "three"`.
   */
  unprojectToFloorPlane: (
    clientX: number,
    clientY: number,
    floorZ: number,
  ) => { x: number; z: number } | null;
  /**
   * The outer div of the IfcViewer. Used by external overlays
   * (e.g. the calibration wizard's 3D line SVG, added in
   * Task 15) that need to portal into the viewer's DOM so
   * their coordinates match the canvas's CSS pixel system
   * without offset math.
   *
   * Returns `null` if the IfcViewer hasn't mounted yet (or
   * has been disposed). The portal will no-op in that case
   * (React handles null portal targets by rendering nothing).
   */
  getContainer: () => HTMLDivElement | null;
  /**
   * Set the active interaction tool on the 3D canvas.
   *
   * Task 18: when a level plan is open, the default tool is
   * "measure" (crosshair cursor, click → click measurement
   * lines on the TechnicalDrawing). Closing the level plan
   * (or calling `setActiveTool("navigation")`) restores the
   * default orbit navigation.
   *
   *   - "navigation" → MouseNavigation enabled, default cursor.
   *   - "measure"    → MouseNavigation disabled, crosshair cursor,
   *                     click/mousemove/keydown events on the
   *                     container are routed to the
   *                     MeasurementLineSystem (see
   *                     LevelPlanController.getMeasureSystem()).
   *
   * Calling `setActiveTool("measure")` when no level plan is
   * open is a no-op (the controller exposes the system but
   * `getDrawing()` is null without an open plan).
   */
  setActiveTool: (tool: "navigation" | "measure") => void;
  /**
   * The active tool. Mirrors the last `setActiveTool` call —
   * `null` until the first call. Used by external UI (debug
   * overlay, future tool buttons) to reflect state without
   * having to thread props through React.
   */
  readonly activeTool: "navigation" | "measure" | null;
  /**
   * Drive the 3D camera's wheel-zoom as if a `wheel` event with
   * the given fields had fired on the canvas. Used by the
   * calibration wizard's 3D pane to forward wheel events when
   * the transparent overlay has `pointer-events: auto` (which
   * blocks events from reaching the underlying
   * OBC.MouseNavigation).
   *
   * `deltaY` is the raw `WheelEvent.deltaY`. `deltaMode`
   * mirrors `WheelEvent.deltaMode` (0 = pixel, 1 = line, 2 =
   * page) so the same delta-normalization constants
   * `camera-controls` uses in its own wheel handler apply here.
   * Defaults to 0 (pixel) for backwards compatibility — the
   * typical mouse-wheel case.
   *
   * Behavior matches a native wheel scroll on the canvas,
   * including cursor-pivoted dolly (OBC sets
   * `dollyToCursor = true` on `SimpleCamera`).
   */
  zoom: (deltaY: number, clientX: number, clientY: number, deltaMode?: number) => void;
  /**
   * Task 19: Batch-toggle visibility for a set of IFC elements in a
   * single model. Elements NOT in `expressIds` are left at their
   * current visibility state — the caller is responsible for
   * tracking deltas if they want a "set" semantics.
   *
   * Internally this calls `OBC.Hider.set(visible, { [modelId]:
   * expressIds })`. We wrap the call in a single
   * `requestAnimationFrame` per RAF-tick so multiple consecutive
   * `setElementVisibility` calls within the same frame coalesce
   * into one flush — callers don't need to batch. True/false
   * entries are bucketed separately per model so the auto filter
   * pass can safely send both visible=true and visible=false
   * in the same frame without one overriding the other.
   *
   * Returns `void`. The flush completes asynchronously; we don't
   * expose a completion handle because none of the current
   * consumers (filter hooks) need it.
   */
  setElementVisibility: (
    modelId: string,
    expressIds: ReadonlySet<number>,
    visible: boolean,
  ) => void;
  /**
   * Task 19: Subscribe to element pick events. Fires once per
   * click (NOT on drag — the canvas's `click` event only fires
   * when a pointer goes down and up on the same pixel without
   * significant movement, which matches the user expectation of
   * "click an element").
   *
   * The callback is only invoked when `activeTool === "navigation"`.
   * The measurement tool (`activeTool === "measure"`) suppresses
   * picks because clicks there are routed to the
   * MeasurementLineSystem — firing picks too would create a
   * conflict between the two consumers.
   *
   * Pass `null` to clear the listener. Only one listener is
   * supported — calling with a new callback replaces the previous
   * one. The 150ms debounce described in the spec is NOT applied
   * (Maintainer decision, 2026-06-22 08:41 CLT: no throttling).
   */
  setOnElementPick: (cb: ((e: ElementPickEvent | null) => void) | null) => void;
  // ─── Task 21: selection / highlight API ─────────────────────────
  /**
   * Replace the current selection with one element. Pass null for
   * both args to clear. MVP scope: selection holds exactly one element.
   * No-op if `modelId` is provided but not currently loaded.
   */
  selectElement: (modelId: string | null, expressId: number | null) => void;
  /** Clear all selection. Equivalent to `selectElement(null, null)`. */
  clearSelection: () => void;
  /**
   * Wave 78: tell the viewer the device is short on memory. `low` lowers
   * the graphics quality and shrinks the tile / mesh caches, `critical`
   * evicts every cached invisible tile and culls hardest; `none` returns
   * to the `memoryTuning` values. Cheap and idempotent. Works without a
   * `memoryTuning` prop (relative to the engine defaults).
   */
  setMemoryPressure: (level: MemoryPressure) => void;
  /** Snapshot of the current selection (modelId → Set<expressId>). */
  getSelection: () => ReadonlyMap<string, ReadonlySet<number>>;
  /**
   * Wave 5B tap-to-create: world-space centre of the current
   * selection's bounding box. Async — resolved through the engine's
   * BoundingBoxer. Returns null when there is no selection, the world
   * isn't mounted, or the box is unusable.
   */
  getSelectionWorldCenter: () => Promise<{ x: number; y: number; z: number } | null>;
  /**
   * Wave 20 tap-to-create: the REAL world point of the canvas pick
   * that produced the current selection (depth-pass intersection —
   * where the user actually clicked, not the element's bbox centre).
   * Returns null when the selection did not come from a canvas pick
   * (programmatic `selectElement`, properties-panel select, the
   * raycaster/Highlighter fallback) or when the selection has since
   * changed — callers should then fall back to
   * `getSelectionWorldCenter()`.
   */
  getSelectionWorldPoint: () => { x: number; y: number; z: number } | null;
  /**
   * Wave 48: the world-space surface normal of the face the canvas
   * pick hit, for the CURRENT selection. Returns null for
   * programmatic selections, when the pick path that produced the
   * selection carried no normal (e.g. the worker-raycast primary
   * backend before the lazy normal resolution lands), or when the
   * selection has since changed. Callers fall back to a bbox-face
   * snap and then to the camera view direction.
   */
  getSelectionWorldNormal: () => { x: number; y: number; z: number } | null;
  /**
   * Wave 21: true while the depth pass for the CURRENT canvas-pick
   * selection is still in flight — the id pass has already applied
   * selection + highlight, the real click point lands moments later.
   * Tap-to-create waits on this instead of falling back to
   * `getSelectionWorldCenter`. False for programmatic selections and
   * once the point has landed (or the pick was discarded).
   */
  isSelectionPointPending: () => boolean;
  /**
   * Subscribe to selection changes. Returns an unsubscribe function
   * that removes ONLY this callback (wave 63). Callback fires after
   * every `selectElement` / `clearSelection` call, including the
   * TOE-internal clearing path.
   *
   * @deprecated-arg Passing `null` still clears EVERY listener (kept for
   * backward compatibility); use the returned unsubscribe instead.
   */
  onSelectionChange: (
    cb:
      | ((selection: ReadonlyMap<string, ReadonlySet<number>>) => void)
      | null,
  ) => () => void;
  /**
   * Subscribe to changes in the loaded-models set. Callback fires
   * with the new model count after every load and dispose event.
   * Returns an unsubscribe function that removes ONLY this callback
   * (wave 63). Required by callers that need to
   * react to model-load events from outside the viewer's render
   * tree (e.g. a hook that lives in a parent component — a child
   * re-render wouldn't propagate to ancestors).
   *
   * Passing `null` still clears EVERY listener (backward compatible,
   * deprecated) — prefer the returned unsubscribe.
   */
  onLoadedModelsChange: (cb: ((count: number) => void) | null) => () => void;
  /**
   * Get property set names and values for a single element.
   * Reads from the loaded fragments model via the canonical
   * `model.getItemsData([expressId], { relations: { IsDefinedBy: ... } })`
   * API so property-set entries (e.g. `Pset_Foundation.01-nivel
   * constructivo`) surface alongside the entity-level attributes
   * (`Name`, `GlobalId`, `Tag`).
   *
   * Returns a flat `Record<string, string>` keyed by the TOE
   * attribute name; IsDefinedBy entries are emitted as
   * `"PsetName.PropertyName"`. Returns null if the model is not
   * loaded or the expressId is unknown.
   */
  getElementData: (
    modelId: string,
    expressId: number,
  ) => Promise<Record<string, string> | null>;
  /**
   * Wave 73: {@link getElementData} plus the element's IFC GlobalId.
   * The flat attribute record carries no `GlobalId` (fragments stores the
   * GUID beside the attributes, not in them), which forced consumers to call
   * `model.getGuidsByLocalIds` themselves. This returns the same record with
   * a `GlobalId` entry added (only when the model knows a GUID for the
   * element and the record has no `GlobalId` of its own), plus the guid as a
   * separate field. `null` when the model is not loaded or the id is unknown.
   */
  getElementDataWithGuid?: (
    modelId: string,
    expressId: number,
  ) => Promise<{ attributes: Record<string, string>; globalId: string | null } | null>;
  /**
   * Wave 73: GUIDs for several local ids of one model in one worker
   * round-trip, same order as `expressIds` (`null` for ids without a GUID).
   * `null` when the model is not loaded or the lookup fails.
   * (Optional in the type only so test doubles of the handle keep compiling;
   * the real handle always provides it, as with `getElementDataWithGuid`.)
   */
  getGlobalIds?: (
    modelId: string,
    expressIds: number[],
  ) => Promise<Array<string | null> | null>;
  /**
   * Return the full local-ID set for every loaded model.
   * Keys are ifcFileIds (model IDs); values are the list of
   * local IDs (i.e. express IDs in TOE parlance) of items with
   * geometry in that model. Used by the filter pipeline to
   * resolve per-model visibility decisions (hide/show whole
   * models, filter by model name in the Models auto-folder).
   *
   * The values are TOE local IDs, not IFC express IDs — they
   * happen to share the same numeric space when the IFC's
   * express IDs were preserved during import, but downstream
   * hider calls (`Hider.set`, `setElementVisibility`) accept any
   * `Identifier` and TOE translates them internally.
   *
   * Async: the underlying call (`model.getItemsIdsWithGeometry()`)
   * is async on FragmentsModel; the parent hook awaits this.
   */
  getAllModelExpressIds: () => Promise<Map<string, number[]>>;
  /**
   * Get all (localId, properties) pairs for every geometric element
   * in the loaded model. Used by `useModelPropertyIndex` to build
   * the in-memory inverted index for custom filter evaluation
   * (Task 23, Critic's Option C).
   *
   * Returns `null` if the model is not loaded or the fetch fails.
   * For very large models (>100k elements), pass `batchSize` to
   * chunk the `getItemsData` call into multiple smaller requests —
   * the worker postMessage payload is the bottleneck and chunking
   * avoids frame-drops. The default batch size is 5000.
   *
   * The returned `properties` is a flat `Record<string, string>`
   * produced by the same `flattenItemData` helper used by
   * `getElementData` — keys are `PsetName.PropertyName` for pset
   * entries, or the bare attribute name (e.g. `Name`, `GlobalId`)
   * for entity-level attributes.
   */
  getPropertyDataForModel: (
    modelId: string,
    options?: { batchSize?: number },
  ) => Promise<Array<{ localId: number; properties: Record<string, string> }> | null>;
  /**
   * Get the IFC spatial structure tree for a loaded model.
   * Returns the root SpatialTreeItem (Site → Building → Storey → Elements)
   * or null if the model is not loaded. Storey nodes have
   * `category: "IFCBUILDINGSTOREY"`; their descendants are contained
   * elements. All IDs are TOE local IDs — consistent with
   * `modelToExpressIds`.
   *
   * Used by `useViewerExpressIdMaps` to build levelToExpressIds
   * directly from the model's spatial structure at query time
   * (search-set semantics).
   */
  getModelLevelLocalIds: (
    modelId: string,
  ) => Promise<Map<string, Set<number>> | null>;
  /**
   * Task 21: Z elevation of the active storey's floor, or `null`
   * if no level plan is open. Read from the LevelPlanController's
   * storey map. Used by LinkView's spawn-point camera to lock
   * the camera at `floorZ + 1.8m` (human eye height) above the
   * active storey.
   *
   * The companion method `getActiveStoreyMeta` returns the full
   * `{ name, elevation, height }` tuple — callers that need the
   * name or height prefer that. This thin accessor is just a
   * number-returning convenience that lets the LinkView spawn
   * point code skip a null check on every click.
   */
  getActiveStoreyFloorZ(): number | null;
  /**
   * Task 21: centroid (in world space) of all loaded fragment
   * models, or `null` if no model is loaded or any model has no
   * bounding box. The centroid is the arithmetic mean of every
   * model's `box` (a `THREE.Box3`) — we average per-axis across
   * all models with valid boxes.
   *
   * Used by LinkView's spawn-point camera to compute the
   * initial bearing (the symbol's chevron points toward the
   * model centroid from the spawn point).
   *
   * Implementation note: FragmentsModel's `box` is a getter that
   * recomputes from the model's current instance transforms; we
   * trust it without forcing an `update()` first (the model has
   * already loaded by the time the user can click).
   */
  getModelCentroid(): { x: number; y: number; z: number } | null;
  /**
   * Coordinate shift [x, y, z] the viewer applies to every model (the
   * base model's `getCoordinates()`): world = IFC (X, Z, -Y) + shift.
   * `null` until a model has loaded. Optional so existing mocks stay valid.
   */
  getBaseCoordinates?(): [number, number, number] | null;
  /**
   * Wave 58: the straight-down framing height (metres) the level-plan
   * view uses — `LEVEL_PLAN_FRAME_DISTANCE` from `@ff/viewer`. The
   * LinkView navigation view reuses this exact value for its
   * straight-down "you are here" camera so the nav view frames a
   * floor from the same height as the level plan (instead of a
   * close-up at human eye height).
   */
  getLevelPlanDistance(): number;
  /**
   * Task 21: lock the 3D camera to a restricted third-person
   * position. Camera sits at `eye` looking at `target`. The
   * `Orbit` nav controls are disabled and wheel-zoom is disabled
   * (we don't want the user dollying off the spawn point while
   * the symbol is visible — they look around by dragging inside
   * the 3D view, which calls this method again with a new target).
   *
   * `options.animate` (default `false`) toggles the camera-controls
   * smooth transition. Use `true` for the initial click (so the
   * user sees the 3D view glide to the spawn) and leave it off
   * for per-frame drag updates (so the camera follows the cursor
   * in real time without chasing a 0.2s-lagged target).
   *
   * Safe to call before the world is mounted — the method bails
   * out silently if `worldRef.current` is null.
   */
  setRestrictedThirdPerson(
    eye: { x: number; y: number; z: number },
    target: { x: number; y: number; z: number },
    options?: { animate?: boolean },
  ): void;
  /**
   * Task 21 navigation smoothing: thin wrapper around the
   * camera's `setLookAt` that does NOT touch the camera-controls
   * mouse-button state. Callers that run their own rAF-based
   * interpolation loop call this every frame; the initial
   * `setRestrictedThirdPerson` is called once to disable
   * the default orbit controls.
   *
   * Safe to call before the world is mounted (bails silently).
   */
  navigateTo(
    eye: { x: number; y: number; z: number },
    target: { x: number; y: number; z: number },
  ): void;
  /**
   * Task 21: re-enable Orbit nav and wheel zoom on the 3D
   * camera. Counterpart to `setRestrictedThirdPerson` — call
   * this when the spawn point is cleared (building change,
   * user picks "back to 3D", etc.). The camera stays where
   * it is; only the controls re-enable.
   *
   * 4 = `CameraControls.ACTION.DOLLY` for perspective cameras.
   * The LinkView right pane is always perspective (the
   * OrthoPerspectiveCamera's projection is set to "Perspective"
   * by the LevelPlanController.close() reset), so DOLLY is the
   * correct wheel action — calling `setLookAt` with the camera
   * in ortho mode would be a no-op for wheel events.
   */
  releaseRestrictedCamera(): void;
  /**
   * Task 23: add a textured floor-plan plane to the 3D scene.
   *
   * The canvas is rendered externally (by the caller using pdf.js)
   * and passed in as a ready-to-use element. The viewer creates
   * a `THREE.PlaneGeometry` spanning the given world-space XZ
   * bounds, applies the canvas as a `CanvasTexture`, and positions
   * the mesh at `y = elevation + Z_FIGHT_OFFSET` above the floor
   * slab.
   *
   * @param canvas — off-screen canvas with the pre-rendered PDF
   *   page. The caller owns the canvas lifecycle.
   * @param worldBounds — XZ-axis-aligned world-space rect for the
   *   plane. Derived from the calibration similarity transform.
   * @param elevation — storey floor Z (the plane sits just above it).
   * @param options.rotation — rotation (radians) of the page about the
   *   centre of `worldBounds`, i.e. the calibration's similarity rotation.
   *   When non-zero, `worldBounds` must be the UN-rotated page rectangle
   *   centred on the transformed page centre (see
   *   `computeFloorPlanPlacement`). Default 0 = axis-aligned.
   * @param options.opacity — initial plane opacity, 0..1 (default 1:
   *   the PDF reads exactly like the 2D sheet — white paper, black ink).
   * @returns a unique plane id for later removal.
   */
  addFloorPlanPlane(
    canvas: HTMLCanvasElement,
    worldBounds: { minX: number; minZ: number; maxX: number; maxZ: number },
    elevation: number,
    options?: { opacity?: number; rotation?: number },
  ): string;
  /**
   * Wave 63: change a floor-plan plane's opacity (0..1, clamped) live.
   * Only the material uniform changes — the texture is kept and no
   * shader recompiles. No-op for an unknown id. Optional so existing
   * handle mocks stay valid.
   */
  setFloorPlanPlaneOpacity?(id: string, opacity: number): void;
  /**
   * Task 23: remove a previously-added floor-plan plane.
   * No-op if the id is unknown or already removed.
   */
  removeFloorPlanPlane(id: string): void;
  /**
   * Add a horizontal clipping plane at the given world Y elevation.
   * Uses the OBC.Clipper component (canonical TOE approach) — the
   * SimplePlane mesh provides the visual indicator and the renderer
   * clipping plane cuts the 3D model.
   *
   * The normal is (0, -1, 0) → everything ABOVE the plane is clipped.
   * TransformControls are disabled after creation to prevent gizmo
   * interaction from intercepting canvas pointer events.
   *
   * @param enabled — whether to add the clip plane.
   * @param floorZ — world Y coordinate for the horizontal cut.
   */
  setFloorClipPlane(enabled: boolean, floorZ: number): void;
  /**
   * Task 24: reset the camera to a clean default orbit view.
   *
   * This is the "back to a fresh app load" pose: the camera looks
   * at the model from above-front-right, far enough away that the
   * whole model fits in the viewport, with the orbit navigation
   * fully re-enabled (no restricted third-person state, no
   * ortho/plan projection left over from the floor-plan mode).
   *
   * The framing is derived from the combined bounding box of every
   * currently-loaded fragment model:
   *   - target = the centre of the merged bounding box
   *   - distance = the bounding sphere radius × a fit factor, so
   *     the model fits whatever its size
   *
   * When no model is loaded (or the models have no usable bounding
   * box yet) the camera falls back to a safe default: target at the
   * world origin, 50 m away. The method is therefore idempotent and
   * safe to call at any point in the viewer's lifecycle — including
   * before the world is mounted, where it bails out silently.
   */
  resetCameraToDefault(): void;
  /**
   * Tasks module: capture the current camera pose (eye, target,
   * fov, projection mode). Returns null if the world is not
   * mounted or the camera surface is unavailable — callers should
   * treat a null pose the same as a not-yet-ready viewer.
   *
   * Read-only against the live `camera-controls` instance; safe
   * to call at any frame rate. Each call records a "viewpoint save"
   * telemetry breadcrumb unless `options.silent` is set — per-frame
   * readers must pass `{ silent: true }`.
   */
  getPose(options?: { silent?: boolean }): ViewerPose | null;
  /**
   * Tasks module: restore a previously captured pose — the
   * "open a task from its author's viewpoint" trick. Projection
   * is switched first (the meaning of `fov` depends on which
   * camera is active), then the look-at is applied via the same
   * `controls.setLookAt` surface used by the Task 24 default
   * framing and the Task 30 third-person lock.
   *
   * `options.animate` (default `false`) maps to camera-controls'
   * `enableTransition` — pass `true` for a visible glide when the
   * restore is a navigation event.
   */
  setViewPose(pose: ViewerPose, options?: { animate?: boolean }): void;
  /**
   * Day-3 location snapshot: capture what the user is looking at as a
   * jpeg dataURL, downscaled to ~`maxWidthPx` wide via an offscreen
   * canvas. Same-frame capture (render → toDataURL before the WebGL
   * buffer clears). Returns null on any failure — no
   * preserveDrawingBuffer, detached/missing renderer, jsdom, etc. —
   * so creation never blocks on it.
   */
  getSnapshot(maxWidthPx?: number): string | null;
  // ─── Wave 12: 3D measurement tool mode ───────────────────────
  /**
   * Switch the 3D measurement tool mode. `mode === "measure"` arms
   * the TOE measurement component for `variant` (length/area/angle/
   * volume) and disables click-to-select so pointer events go to the
   * measurer; `mode === "select"` disarms the measurer and restores
   * navigation. Completed measurements stay on screen either way —
   * `clearMeasurements` is the only path that removes them.
   *
   * Called with an unsupported/unrecognised `variant` (or no
   * `variant` while requesting `"measure"`) is a no-op that logs a
   * `console.warn`. Safe to call before the world is mounted (bails
   * silently). Switching variants cancels the previous component's
   * in-flight (preview) creation state.
   */
  setMeasureMode: (mode: MeasureMode, variant?: MeasureVariant) => void;
  /**
   * Remove every on-screen measurement (all variants). This is the
   * only way to clear completed measurements — switching to
   * `"select"` keeps them visible. Leaves the current tool mode
   * unchanged. The component's preview/in-flight creation is
   * cancelled first, then its `list` is cleared (the TOE canonical
   * remove-all pathway), and the readout resets to `null`.
   */
  clearMeasurements: () => void;
  /**
   * Subscribe to live measurement readouts. Fires with
   * `{ value, unit }` as the user drags a measurement, and with
   * `null` when a measurement is cancelled, cleared, or the tool
   * returns to `"select"`. Pass `null` to unsubscribe (single-listener
   * semantics, matching `setOnElementPick`).
   */
  onMeasureReadout: (cb: ((readout: MeasureReadout | null) => void) | null) => void;
  /**
   * True while the armed 3D measurement has an in-flight (partial /
   * preview) measurement that Escape would cancel. False when the tool
   * is idle (armed but no points placed yet) or disarmed.
   *
   * Wave 50: the owning toolbar consults this to run the two-stage
   * Escape — in-progress → cancel the current line, idle → exit to
   * navigation.
   */
  isMeasureInProgress: () => boolean;
  /**
   * Cancel the in-flight (preview) measurement WITHOUT removing any
   * completed measurements (TOE's `cancelCreation` semantics). No-op
   * when the tool is disarmed or idle.
   */
  cancelMeasureCreation: () => void;
  /**
   * (Wave 67 measurement list API members below are optional in the type
   * so partial handle test doubles elsewhere keep type-checking; the real
   * handle always provides them.)
   *
   * Wave 67: the 3D measurements on screen (every variant, creation
   * order). Plain data - safe to keep in React state. Volume values are
   * async: `value` is null / `text` is "…" until the engine resolves
   * them, then `onMeasurementsChange` fires again.
   */
  getMeasurements?: () => MeasurementEntry[];
  /**
   * Wave 67: commit the in-flight Area / Volume measurement (what a
   * double-click or Enter does). No-op for Length / Angle (they commit
   * themselves) and when nothing is armed.
   */
  finishMeasureCreation?: () => void;
  /**
   * Wave 67: subscribe to list changes (add / delete / clear / async
   * value resolved / model unload). Single slot; pass null to detach.
   */
  onMeasurementsChange?: (
    cb: ((entries: MeasurementEntry[]) => void) | null,
  ) => void;
  /** Wave 67: delete ONE measurement (and its on-screen visuals) by id. */
  deleteMeasurement?: (id: string) => void;
  /**
   * Wave 67: frame a measurement with the camera and mark its label as
   * active (outline ring). Pass `{ focus: false }` to only mark it.
   * `null` clears the mark. Resolves false when the id is unknown.
   */
  focusMeasurement?: (
    id: string | null,
    opts?: { focus?: boolean },
  ) => Promise<boolean>;
  // ─── Wave 13: 3D section planes (multi-plane Clipper) ────────
  /**
   * Add a section clipping plane at `point` with the given `normal`
   * (the direction the plane faces — the half-space on the opposite
   * side is clipped). Returns `true` if the plane was added, `false`
   * if the max of `MAX_SECTION_PLANES` is reached (a no-op + warn).
   *
   * The plane uses OBC.Clipper and is styled with a ClipStyler
   * cut-edge outline. It is tracked separately from the horizontal
   * floor clip plane — `clearSectionPlanes` never touches that one.
   */
  addSectionPlane: (
    point: { x: number; y: number; z: number },
    normal: { x: number; y: number; z: number },
    options?: SectionPlaneOptions,
  ) => boolean;
  /**
   * Wave 82: move / re-orient section plane `index` (insertion order, as in `getSectionPlanes`) IN PLACE: no
   * plane is created or disposed, so no geometry is allocated and a slider can call it at pointer rate. The
   * cut outline of a styled plane is refreshed. Returns `false` for an unknown index.
   */
  updateSectionPlane: (
    index: number,
    plane: { point: { x: number; y: number; z: number }; normal: { x: number; y: number; z: number } },
  ) => boolean;
  /**
   * Wave 82: remove section plane `index` only (later planes shift down by one). No-op for an unknown index.
   */
  removeSectionPlane: (index: number) => void;
  /**
   * Invert the most recent section plane's normal (delete + recreate
   * at the same point). No-op when there are no section planes.
   */
  flipLastSectionPlane: () => void;
  /**
   * Remove all section planes (NOT the horizontal floor clip).
   * No-op when there are none.
   */
  clearSectionPlanes: () => void;
  /** Current number of section planes. */
  getSectionPlaneCount: () => number;
  /**
   * Snapshot the active section planes in insertion order (for saved
   * viewpoints). Plain-data copies — safe to serialize.
   */
  getSectionPlanes: () => SectionPlaneData[];
  /**
   * Render on demand: ask for a redraw after changing the scene from
   * outside the viewer (objects added through the world, materials
   * edited directly, ...). Every other handle method already does this.
   */
  requestRender?: (reason?: string) => void;
  /** Render-on-demand counters (renders, skipped frames, reasons). */
  getRenderStats?: () => RenderSchedulerStats | null;
}

/**
 * Mounts a 3D viewport and renders the latest version of every IFC
 * file in the active building. Stays in sync with Dexie via
 * `useIfcFiles` (live query) so the sidebar doesn't need to push
 * commands here.
 *
 * When `activeBuildingId` changes, every model belonging to the
 * previous building are disposed; models of the new building are
 * loaded from their `.frag` blobs in IndexedDB.
 *
 * The component is React-strict-mode safe: it uses a ref to keep the
 * world/fragments instance outside React state (which would otherwise
 * cause double-init in dev), and a "mounted" flag to skip the
 * post-unmount cleanup that the strict-mode double-mount tries to do.
 */

const IfcViewer = forwardRef<IfcViewerHandle, IfcViewerProps>(
  function IfcViewer(
    {
      projectId: _projectId,
      activeBuildingId,
      className,
      viewerSlice,
      files: filesProp,
      registerFragments: registerFragmentsProp,
      getStoreysForBuilding: getStoreysForBuildingProp,
      getFragBlob: getFragBlobProp,
      disableSelection = false,
      builtInClickPick = true,
      loadingOverlay = true,
      renderPaused = false,
      motionSpeedups,
      renderOnDemand = true,
      splitTileBuild = false,
      tileCache = true,
      memoryTuning,
      onReady: onReadyProp,
      fitOnFirstLoad = false,
      showEngineLogo = true,
    },
    ref,
  ) {
    const containerRef = useRef<HTMLDivElement | null>(null);
    const worldRef = useRef<OBC.World | null>(null);
    const componentsRef = useRef<OBC.Components | null>(null);
    const fragmentsRef = useRef<OBC.FragmentsManager | null>(null);
    // Wave 17: local crash forensics + perf breadcrumbs (module singleton; lazy, idempotent).
    const tel = ensureViewerTelemetry();
    // `renderPaused` mirror: applied when the world is created (mount
    // is async) and on every prop change.
    const renderPausedRef = useRef(renderPaused);
    // Read once at mount (the speedups are wired with the world).
    const motionSpeedupsRef = useRef(motionSpeedups);
    // Render on demand: read once at mount, like motionSpeedups.
    const renderOnDemandRef = useRef(renderOnDemand);
    // Split tile build: resolved once at mount (engine option per load).
    const splitTileBuildRef = useRef(
      resolveSplitTileBuild(splitTileBuild, readSplitTileBuildEnv()),
    );
    const tileCacheRef = useRef(tileCache);
    const memoryTuningRef = useRef<MemoryTuning | undefined>(memoryTuning);
    const memoryPressureRef = useRef<MemoryPressure>("none");
    // Wave 63: the imperative handle is built ONCE (deps []), so it
    // reads these props through refs instead of the first render's
    // values (a later `disableSelection` / `viewerSlice` change was
    // invisible to it).
    const disableSelectionRef = useRef(disableSelection);
    disableSelectionRef.current = disableSelection;
    // Wave 76: read by the click pipeline per event + applied to the
    // Highlighter config in an effect, so it can flip at runtime.
    const builtInClickPickRef = useRef(builtInClickPick);
    builtInClickPickRef.current = builtInClickPick;
    // Wave 76: mirror of what setElementVisibility hid, so a pick that
    // lands on a hidden element is treated as a miss.
    const hiddenTrackerRef = useRef(new HiddenElementTracker());
    const viewerSliceRef = useRef(viewerSlice);
    viewerSliceRef.current = viewerSlice;
    const rodRef = useRef<RenderOnDemand | null>(null);
    // Stable invalidation entry point for every call site in this file.
    // A no-op before mount / after unmount.
    const requestRender = useRef((reason = "viewer", keepAliveMs?: number): void => {
      rodRef.current?.invalidate(reason, keepAliveMs);
    }).current;
    // Wave 76: runtime toggle for the built-in click pick. The fast
    // pipeline reads `builtInClickPickRef` per click; the Highlighter's
    // own DOM auto-pick (non-fast backends) reads its live config, so it
    // is flipped here. Dropping `false` also discards a queued click.
    useEffect(() => {
      builtInClickPickRef.current = builtInClickPick;
      if (!builtInClickPick) pendingClickRef.current = null;
      const hl = highlighterRef.current as unknown as
        | { config?: { autoHighlightOnClick?: boolean } }
        | null;
      if (hl?.config && pickBackendRef.current !== "fast") {
        hl.config.autoHighlightOnClick =
          builtInClickPick && !disableSelectionRef.current;
      }
    }, [builtInClickPick]);
    useEffect(() => {
      renderPausedRef.current = renderPaused;
      const renderer = worldRef.current?.renderer as
        | OBC.SimpleRenderer
        | undefined;
      if (renderer) renderer.enabled = !renderPaused;
      // Resuming: the canvas still shows the frame from before the pause.
      if (!renderPaused) requestRender("resume");
    }, [renderPaused, requestRender]);
    // Wave 73: a later `showEngineLogo` change applies to the live renderer.
    useEffect(() => {
      applyEngineLogo(
        worldRef.current?.renderer as unknown as EngineLogoTarget | undefined,
        showEngineLogo,
      );
    }, [showEngineLogo]);

    // LevelPlanController — created once in mount, disposed on unmount.
    // Replaces the previous OBC.Views cut-plane mechanism (Task 16).
    const levelPlanRef = useRef<LevelPlanHandle | null>(null);

    // Stats overlay (Stats.js FPS/MS/MB panel + the React-rendered
    // model/storey/building debug div) was removed in 2026-06-23 per
    // Maintainer directive — they cluttered the viewport and weren't useful
    // in production. A follow-up can reintroduce them behind a
    // `showStats` prop if a developer needs them for profiling.

    // Task 18: active interaction tool. Defaults to "navigation".
    // Switches to "measure" automatically when a level plan is open
    // (see the openLevel method below). Stored in a ref so the
    // imperative handle can read it without a re-render on every tool
    // change (wave 63: the unused mirror state was removed).
    const activeToolRef = useRef<"navigation" | "measure" | null>(null);

    // Cleanup function for the measure tool's DOM event listeners.
    // Held in a ref so setActiveTool can tear down the previous
    // wiring before installing the new one. Null when no tool is
    // active (or the active tool is "navigation" and has no
    // listeners).
    const measureCleanupRef = useRef<(() => void) | null>(null);

    // ─── Wave 12: 3D measurement tool state ────────────────────
    // The active OBCF measurement component (Length/Area/Angle/Volume)
    // and its variant. Null when the tool is in "select" mode.
    const measure3DRef = useRef<{
      variant: MeasureVariant;
      component: MeasureComponentLike;
    } | null>(null);
    // Wave 63: every measurement component this mount has ever armed.
    // Measurements of a type stay on screen after the user switches
    // to another type, so `clearMeasurements` (and unmount) must clear
    // ALL of them, not only the active one.
    const measure3DUsedRef = useRef<Set<MeasureComponentLike>>(new Set());
    // Wave 67: gate around the CSS2D label layer (see measure/labelLayer.ts).
    const labelLayerGateRef = useRef<LabelLayerGate | null>(null);
    // Wave 67: list model + subscriptions (see measure/measureBook.ts).
    const measureBookRef = useRef<MeasurementBook>(new MeasurementBook());
    const measureVariantsRef = useRef<Map<MeasureComponentLike, MeasureVariant>>(
      new Map(),
    );
    const measureConfiguredRef = useRef<WeakSet<MeasureComponentLike>>(
      new WeakSet(),
    );
    const measureListUnsubsRef = useRef<Map<MeasureComponentLike, () => void>>(
      new Map(),
    );
    const measureListCbRef = useRef<
      ((entries: MeasurementEntry[]) => void) | null
    >(null);
    const measureActiveIdRef = useRef<string | null>(null);
    // Wave 67: commits the open-ended measurement (area / volume) of the
    // armed session; set by activateMeasure3D, cleared on deactivate.
    const finishMeasure3DRef = useRef<(() => void) | null>(null);
    // Pending cleanup for the 3D measurement session's DOM listener
    // (canvas `click` → create) + readout event subscriptions. Distinct
    // from `measureCleanupRef` (that one owns the level-plan measure
    // wiring) so the two tools can never clobber each other.
    const measure3DCleanupRef = useRef<(() => void) | null>(null);
    // Single-slot readout subscription (setMeasureMode/clear emit via
    // this). Null to unsubscribe, matching setOnElementPick semantics.
    const measureReadoutCbRef = useRef<
      ((readout: MeasureReadout | null) => void) | null
    >(null);

    // If true, a cleanup pass is in flight. The strict-mode double-mount
    // unmounts the first instance; we need to ignore that.
    const disposedRef = useRef(false);
    // Navigation speedups (motion mode + settle refresh) and the
    // projection-change listener, kept so the teardown detaches exactly
    // what this mount attached.
    const navSpeedupsRef = useRef<NavigationSpeedups | null>(null);
    const projectionListenerRef = useRef<{
      event: EngineEvent<unknown>;
      handler: (cam: unknown) => void;
    } | null>(null);
    // Wave 32: identity of the CURRENT mount. `disposedRef` alone cannot
    // say "this async setup pass belongs to a mount that has already been
    // replaced", because React 18 StrictMode runs mount -> cleanup -> mount
    // and the second mount deliberately clears the shared flag (otherwise it
    // would bail at its first guard and the viewer would stick on
    // 'Initializing...'). Clearing it also UN-KILLS the first mount's
    // in-flight IIFE: it resumes against objects its own cleanup already
    // disposed (`components.dispose()` cascades to the world and the
    // renderer), logs
    //   "highlighter.setup skipped: world.renderer was disposed"
    //   "fast pick init failed - backend: raycaster"
    // and then overwrites the LIVE mount's refs with the dead ones. The
    // visible result is the field report: elements keep the colour painted
    // before the race, new clicks never colour, and the pick backend
    // silently degrades to the raycaster.
    const mountGenRef = useRef(0);

    // Track the building we last loaded for, so we can dispose its
    // models when the active building changes.
    const loadedBuildingRef = useRef<string | null>(null);

    // Track the per-building ifcFileIds we've already loaded into
    // fragments so we don't re-load the same model on every live-query
    // tick. Cleared when the active building changes.
    const loadedModelIdsRef = useRef<Set<string>>(new Set());
    // Wave 31: WHICH VERSION of each file id is actually loaded. A
    // version replace keeps the same `file.id` (`replaceIfcVersion`
    // mints a new `fragBlobKey`, not a new file), so `loadedModelIdsRef`
    // alone cannot distinguish "already loaded" from "loaded, but
    // stale". Without this the viewer kept rendering the replaced-out
    // model until a building switch, and the property index — keyed by
    // the same file id — kept answering with the old version's
    // property values.
    const loadedVersionRef = useRef<Map<string, string>>(new Map());
    // Wave 38: mirror of the `isStreaming` gate state, readable inside
    // load-pass closures without stale React state. A pass cancelled
    // mid-settle (live-query re-emission) skips its lift; the NEXT pass
    // must lift an armed gate even when it loads nothing fresh (e.g. a
    // version-swap pass) or the overlay pins forever.
    const streamingArmedRef = useRef(false);
    // Wave 61: a load pass is streaming its first view (from the pass
    // start with fresh models until every model is idle after the lift).
    // Render on demand throttles purely stream-driven frames meanwhile
    // (see STREAM_RENDER_INTERVAL_MS).
    const loadStreamingRef = useRef(false);
    // Wave 63: the storey whose level plan a version swap closed; the
    // load pass re-opens it once the new version is in.
    const reopenStoreyAfterSwapRef = useRef<string | null>(null);
    // Wave 31b: disposes started by a building switch, awaited by the
    // load pass before it registers the next building's models.
    const pendingDisposesRef = useRef<Array<Promise<unknown>>>([]);

    // Task 19: visibility batching state. The handle queues
    // (modelId, expressIds, visible) tuples in pendingVisibilityRef
    // and flushes them on the next requestAnimationFrame via
    // `OBC.Hider.set`. Multiple setElementVisibility calls within
    // the same RAF tick coalesce into a single Hider.set call,
    // which keeps the per-frame OBC update cheap even when many
    // filter rules change at once.
    //
    // The current RAF id lives in rafHandleRef so a later call can
    // cancel and replace the pending flush (we never want two
    // flushes queued back-to-back).
    const pendingVisibilityRef = useRef<
      { modelId: string; expressIds: Set<number>; visible: boolean }[]
    >([]);
    const rafHandleRef = useRef<number | null>(null);
    // Cached OBC.Hider instance. Resolved lazily on first visibility
    // write (Hider is a stock engine component registered at mount
    // time). Cached so we don't re-resolve on every flush.
    const hiderRef = useRef<{
      set: (visible: boolean, modelIdMap: Record<string, Set<number>>) => Promise<void>;
    } | null>(null);

    // Task 19: pick subscription. Single-slot ref — a new
    // setOnElementPick call replaces the previous listener. The
    // pick handler reads activeToolRef.current to decide whether
    // to forward the event.
    const pickCallbackRef = useRef<
      ((e: ElementPickEvent | null) => void) | null
    >(null);
    // Task 21: pending callback for the race window where
    // setOnElementPick is called BEFORE the Highlighter is ready
    // (Highlighter setup is async inside the mount IIFE). The
    // pending callback is installed as soon as the Highlighter
    // becomes available. Without this, PropertiesDrawer's
    // subscription silently fails on cold mount.
    const pendingPickCallbackRef = useRef<
      ((e: ElementPickEvent | null) => void) | null
    >(null);
    // Cleanup function for the canvas `click` listener installed by
    // setOnElementPick. Held in a ref so the next subscription can
    // tear down the old wiring before installing new state (same
    // single-listener-at-a-time invariant as the measure tool).
    const pickCleanupRef = useRef<(() => void) | null>(null);

    // ─── Task 21: highlight / selection state ───────────────────────
    // `OBCF.Highlighter` is the canonical visual-feedback component
    // for picked elements (lives in @thatopen/components-front, NOT
    // @thatopen/components — verified by inspecting the OBC 3.4.6
    // .d.ts). It supports multi-select natively; for the MVP we
    // treat the selection set as size ≤ 1 and replace on every
    // `selectElement` call.
    //
    // The highlighter is created + setup async inside the mount
    // IIFE; we hold it in a ref so the imperative handle + the
    // cleanup path can reach it. Disposal is async (`dispose()`
    // returns a Promise) — fire-and-forget from the cleanup branch.
    const highlighterRef = useRef<OBCF.Highlighter | null>(null);

    // Current selection as a Map<modelId, Set<expressId>>. The
    // external API (`getSelection()`) returns a snapshot — callers
    // can mutate it without affecting internal state.
    const selectionRef = useRef<Map<string, Set<number>>>(new Map());
    // Wave 20 tap-to-create: the real intersection point of the last
    // canvas pick, tagged with the selection fingerprint it produced.
    // Stashed ONLY by the fast-pick click pipeline; the programmatic
    // paths (selectElement / clearSelection / the pipeline's own
    // empty-space branch) null it.
    //
    // Wave 21: the Highlighter's async onClear mirror NEVER nulls it
    // when the clear is stale (it describes the PREVIOUS selection —
    // replacing a highlight fires onClear(old) after the new stash
    // landed). Honouring it was the wave-20 regression: first click
    // anchored at the point, every later click fell back to the bbox
    // centre. The fingerprint guard below is the staleness defence.
    const lastPickPointRef = useRef<{
      key: string;
      point: { x: number; y: number; z: number };
    } | null>(null);
    // Wave 48: the world-space FACE normal of the last canvas pick,
    // tagged with the same selection fingerprint as `lastPickPointRef`.
    // Resolved in the background (the normal pass piggybacks on / trails
    // the existing depth-pass anchor) so the section-plane toolbar can
    // orient parallel to the picked face. Null for programmatic picks and
    // for the worker-raycast path until the lazy normal resolution lands.
    const lastPickNormalRef = useRef<{
      key: string;
      normal: { x: number; y: number; z: number };
    } | null>(null);
    // Wave 21b: single-flight pick + deferred anchor bookkeeping.
    // Rapid clicks used to start one GPU pass chain EACH — the seq
    // guard discarded stale RESULTS, but the renders were already
    // spent, contending on the GPU (measured: 3 near-simultaneous
    // clicks = 2.1 s before the last anchor landed). Now only ONE
    // chain runs: a click arriving mid-chain records itself as the
    // supersede, and the chain re-picks at the NEWEST pixel instead
    // of applying the stale result — bursts collapse to at most two
    // serialized passes. `pendingPickKeyRef` carries the fingerprint
    // of the selection whose depth-pass point is still in flight —
    // the marker waits on it instead of committing to the bbox
    // centre.
    const pickBusyRef = useRef(false);
    const pendingClickRef = useRef<{
      ndc: { x: number; y: number };
      size: { x: number; y: number };
      clickTs: number;
      // Wave 45: the raw client pixel for the worker raycast's
      // `screenToCast` (its input is CSS px, not NDC).
      clientX: number;
      clientY: number;
      /** Wave 73: the tap came from a finger / pen (tolerant raycast). */
      touch: boolean;
    } | null>(null);
    // Wave 22: chain telemetry for the degradation hunt ("delay
    // grows with click count"). Counters + rolling latencies, read
    // via __ffDebug.stats().
    const chainStatsRef = useRef({
      clicks: 0,
      applied: 0,
      superseded: 0,
      emptyClicks: 0,
      lastClickToSelectionMs: null as number | null,
      lastClickToPointMs: null as number | null,
      recentClickToSelectionMs: [] as number[],
      lastHighlightMs: null as number | null,
      highlightInFlight: 0,
      highlightInFlightPeak: 0,
      highlightCoalesced: 0,
      idPassRenders: 0,
      lastClickRenders: 0,
      // Wave 27: stall-guard counters. `degrades` counts batched-path
      // throws (with the last reason stringified for Sentry);
      // `pickTimeouts` counts picks that never settled inside the
      // stall budget — the failure mode that latched the boss's
      // click chain on real models.
      degrades: 0,
      lastDegradeReason: null as string | null,
      pickTimeouts: 0,
      // Wave 28: cost breakdown of the LAST pick + UNKNOWN outcomes.
      // `inconclusiveClicks` counts clicks that hit an element but
      // could not be resolved in time (no-op, selection untouched —
      // the fast replacement for a 4 s stall); `pickTranslateTimeouts`
      // counts the worker round-trips that outlived
      // LOCAL_ID_BUDGET_MS; the last-{rpcs,readbacks,cacheHits,boxRead}
      // quartet is the "1 render / 1 readback / ≤1 RPC per click" tell
      // that used to be 33 of each.
      inconclusiveClicks: 0,
      pickTranslateTimeouts: 0,
      phase2Timeouts: 0,
      lastPickRpcs: null as number | null,
      lastPickReadbacks: null as number | null,
      lastPickCacheHits: null as number | null,
      lastPickBoxRead: null as boolean | null,
      // Wave 31b: why the single-box readback was skipped ("disabled",
      // "bounds-too-wide:WxH", "region-out-of-target:…", …) or null when
      // it was used. Readbacks far above 1 are only diagnosable with this.
      lastPickBoxDecline: null as string | null,
      lastPickScissor: null as boolean | null,
      // Wave 45: raycast-primary backend counters. `raycastTimeouts`
      // counts the bounded worker-raycast round-trips that lapsed (⇒
      // fallback); `lastPickBackend` is the telemetry breadcrumb string
      // for the LAST click ("raycast" | "idpass" | "idpass-fallback-throw" |
      // "idpass-fallback-timeout"); `lastRaycastMs` is the raycast duration
      // that click paid; `lastRaycastBusy` snapshots whether any model was
      // still streaming tiles (`isBusy`) at click time — proves picks land
      // pre-warm.
      raycastTimeouts: 0,
      lastPickBackend: null as string | null,
      lastRaycastMs: null as number | null,
      lastRaycastBusy: null as boolean | null,
    });

    // Wave 26: debug-gated chain-perf emitter. Disposal handle lives
    // in a ref: the arming block (DEV + ?ffdebug=1 only) starts it,
    // the unmount cleanup stops it (and flushes the last window).
    const debugPerfDisposeRef = useRef<null | (() => void)>(null);

    // Wave 22: coalesced highlight runner. The growth-curve
    // telemetry caught the real "leak": every click fired a detached
    // `highlightByID` cycle (1.2–1.7 s on big MEP elements — each
    // ends in a forced fragments-worker update), and the cycles
    // STACKED (in-flight peak hit 8 under a burst). Every new
    // click's getItemAt worker round-trip then queued behind them:
    // "the more elements I click, the more the delay takes". The TOE
    // library's own click path AWAITs each cycle, so it never
    // overlaps — that is the piece we were missing. The queue below
    // serializes cycles AND skips intermediates: while one runs,
    // newer targets replace the pending one and the drain always
    // applies the newest.
    const highlightBusyRef = useRef(false);
    const highlightPendingRef = useRef<
      { modelId: string; expressId: number } | null | undefined
    >(undefined);
    // Wave 24: targeted coloring state (fast backend only). The TOE
    // Highlighter's updateColors() runs a GLOBAL resetHighlight()
    // (~1 s on the MEP model — every tile of every model) on every
    // selection change; the Raycasters example is fast because it
    // never resets (colors accumulate — wrong for single-select UX).
    // The fragments manager API accepts TARGETED maps on both calls
    // (measured: highlight 19 ms, resetHighlight 10 ms, update 1 ms
    // on the slab), so in fast mode we bypass the Highlighter
    // entirely and repaint exactly two elements per change: un-paint
    // the previous, paint the new. A stray Highlighter cycle would
    // global-reset and wipe this direct coloring — which is safe
    // because the only caller (this queue) branches on the backend.
    // Wave 30: "always dirty" fallback counter for
    // `getViewportRevision()` when there is no projection state to
    // hash (tests, partial mounts). Returning a fresh value each call
    // reproduces the pre-wave-30 behavior instead of freezing overlays.
    const viewportRevFallbackRef = useRef(0);
    const lastColoredRef = useRef<Record<string, Set<number>> | null>(null);
    // Mirrors the Highlighter's exact call shape — same style it
    // registers for the 'select' group, same customId. (The raw
    // highlight() without customId hung on the chiller in the
    // wave-24 pre-flight; matching the library's shape is the fix.)
    const selectStyleRef = useRef<{
      color: THREE.Color;
      opacity: number;
      transparent: boolean;
      renderedFaces: 0; // FRAGS.RenderedFaces.ONE — TOE canonical
      customId: string;
    } | null>(null);
    function getSelectStyle() {
      if (!selectStyleRef.current) {
        selectStyleRef.current = {
          color: new THREE.Color(0xff6a00),
          opacity: 0.5,
          transparent: true,
          renderedFaces: 0,
          customId: "select",
        };
      }
      return selectStyleRef.current;
    }

    async function drainHighlightQueue(): Promise<void> {
      const h = highlighterRef.current;
      if (!h) return;
      const s = chainStatsRef.current;
      highlightBusyRef.current = true;
      try {
        let target = highlightPendingRef.current;
        while (target !== undefined && !disposedRef.current) {
          highlightPendingRef.current = undefined;
          const th = performance.now();
          s.highlightInFlight += 1;
          if (s.highlightInFlight > s.highlightInFlightPeak) {
            s.highlightInFlightPeak = s.highlightInFlight;
          }
          try {
            if (pickBackendRef.current === "fast") {
              // Wave 24: targeted repaint — O(two elements), not
              // O(scene). Un-paint only what the last cycle painted,
              // paint only the new selection, then flush dirty tiles.
              const frags = fragmentsRef.current;
              if (frags) {
                // Reset and paint fire CONCURRENTLY (the wave-24
                // probe showed sequential round-trips stacking to
                // 2.7 s on the chiller; TOE's own updateColors uses
                // allSettled for the same reason). The worker
                // serializes the messages, but we skip one
                // main-thread round-trip of latency.
                const ops: Array<Promise<unknown>> = [];
                if (lastColoredRef.current) {
                  ops.push(frags.resetHighlight(lastColoredRef.current));
                }
                if (target === null) {
                  lastColoredRef.current = null;
                } else {
                  const map = { [target.modelId]: new Set([target.expressId]) };
                  ops.push(frags.highlight(getSelectStyle(), map));
                  lastColoredRef.current = map;
                }
                await Promise.allSettled(ops);
                // Render on demand: the tint lands through tile UPDATEs
                // (watched in renderOnDemand); this keeps the window open
                // for the ones that trail the RPC.
                requestRender("highlight");
                // Wave 28: NEVER await the fragment flush on the click
                // path. `core.update(true)` → `forceUpdateFinish()`
                // (@thatopen/fragments index.mjs:20987) parks until a
                // worker FINISH stamped past the current seq arrives —
                // i.e. behind every queued tile decode AND every
                // in-flight Storage download of every loaded model.
                // On a real streaming scene that is seconds (and it is
                // never rejected: `RequestsManager.clean` can drop the
                // FINISH its fence waiter is waiting on, `:20614–20619`
                // → orphaned await). It is also throttled to 10 Hz, so
                // awaiting it often no-ops anyway (`:36366`, maxUpdateRate
                // 100). The tint itself does not need it: the `highlight`
                // RPC pushes the virtual-mesh UPDATEs from the worker
                // (`:34332–34341` → `:31157–31172` → applied on main at
                // `:21152`), the flush only re-runs LOD streaming, and
                // TOE itself fires this flush un-awaited — `Views`
                // subscribes `_fragmentsUpdateEvent` and calls
                // `fragments.core.update(true)` with no await and no
                // catch (`@thatopen/components` index.mjs:21816-21819).
                // So: request it, do not wait for it.
                frags.core.update(true).then(
                  () => requestRender("highlight-flush"),
                  () => {
                    /* the flush is opportunistic; a failure must not
                       wedge the highlight queue */
                  },
                );
              }
            } else if (target === null) {
              await h.clear("select");
              requestRender("highlight");
            } else {
              await h.highlightByID(
                "select",
                { [target.modelId]: new Set([target.expressId]) },
                true,
              );
              requestRender("highlight");
            }
          } catch {
            /* a failed cycle must not wedge the queue */
          }
          s.highlightInFlight -= 1;
          s.lastHighlightMs = Math.round(performance.now() - th);
          target = highlightPendingRef.current;
        }
      } finally {
        highlightBusyRef.current = false;
      }
    }

    function queueHighlight(target: { modelId: string; expressId: number } | null): void {
      if (!highlighterRef.current) return;
      if (highlightPendingRef.current !== undefined) {
        chainStatsRef.current.highlightCoalesced += 1;
      }
      highlightPendingRef.current = target;
      if (!highlightBusyRef.current) void drainHighlightQueue();
    }

    // Wave 23: drag-vs-click discriminator, ported from the TOE
    // Highlighter's own click path (press position + mouseMoveThreshold
    // 5px + skip on release). A `click` event fires on EVERY mouseup
    // over the canvas — including the release that ends an orbit/pan
    // drag — so without this guard, rotating the camera and releasing
    // over an element selected it (field report). Attach per listener
    // site; `wasDrag()` consumes the flag so the next gesture starts
    // clean.
    // Wave 73: pointer-type aware (a finger jitters more than a mouse: the
    // old flat 5 px threshold classified ordinary touch taps as drags and
    // dropped them), multi-touch / pointercancel aware (see
    // picking/pointerPick.ts), and it feeds the engine's own `Mouse` helper
    // from the pointer events: that helper only listens to `pointermove` /
    // `touchstart`, so a tap without either left the Highlighter / picker
    // fallback reading a stale (or never-set) position.
    function attachDragGuard(canvasEl: HTMLElement): {
      wasDrag(): boolean;
      dispose(): void;
    } {
      const tracker = createTapTracker();
      const mouseTargets = (): Array<{ mouse?: { updateMouseInfo?: (e: Event) => void } | null }> => {
        const w = worldRef.current;
        const out: Array<{ mouse?: { updateMouseInfo?: (e: Event) => void } | null }> = [];
        try {
          if (w) {
            const rc = componentsRef.current?.get(OBC.Raycasters).get(w);
            if (rc) out.push(rc as unknown as (typeof out)[number]);
          }
        } catch {
          // components mid-dispose: nothing to feed
        }
        if (fastPickerRef.current) out.push(fastPickerRef.current as unknown as (typeof out)[number]);
        return out;
      };
      const onPointerDown = (ev: Event): void => {
        const e = ev as PointerEvent;
        tracker.down(e as PointerLike);
        feedEngineMouse(mouseTargets(), e);
      };
      const onPointerMove = (ev: Event): void => {
        tracker.move(ev as PointerEvent as PointerLike);
      };
      const onPointerUp = (ev: Event): void => {
        // `moved` survives until the click handler consumes it —
        // for mouse input `click` always follows `pointerup`.
        tracker.up(ev as PointerEvent as PointerLike);
        feedEngineMouse(mouseTargets(), ev);
      };
      const onPointerCancel = (): void => {
        tracker.cancel();
      };
      canvasEl.addEventListener("pointerdown", onPointerDown);
      canvasEl.addEventListener("pointermove", onPointerMove);
      canvasEl.addEventListener("pointerup", onPointerUp);
      canvasEl.addEventListener("pointercancel", onPointerCancel);
      return {
        wasDrag(): boolean {
          return tracker.wasDrag();
        },
        dispose(): void {
          canvasEl.removeEventListener("pointerdown", onPointerDown);
          canvasEl.removeEventListener("pointermove", onPointerMove);
          canvasEl.removeEventListener("pointerup", onPointerUp);
          canvasEl.removeEventListener("pointercancel", onPointerCancel);
        },
      };
    }
    const pendingPickKeyRef = useRef<string | null>(null);
    // Wave 31b: the pick pipeline is installed once per mount, whether
    // or not anybody subscribed to pick events (see installPickSubscription).
    const pickInstalledRef = useRef(false);
    // Stable serialisation of a selection map for the stash guard:
    // sorted modelIds, sorted expressIds. Two equal maps always
    // produce the same string regardless of insertion order.
    const selectionFingerprint = (sel: ReadonlyMap<string, ReadonlySet<number>>): string =>
      [...sel.entries()]
        .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
        .map(([modelId, ids]) => `${modelId}:${[...ids].sort((x, y) => x - y).join(",")}`)
        .join("|");
    // Subscribers to selection changes. `onSelectionChange(cb)`
    // returns an unsubscribe for that one callback; the legacy
    // `onSelectionChange(null)` still clears the entire set.
    const selectionListenersRef = useRef<
      Set<(s: ReadonlyMap<string, ReadonlySet<number>>) => void>
    >(new Set());
    // Task 22-amendment: subscribers to model-load events.
    // `onLoadedModelsChange(cb)` returns a per-callback unsubscribe;
    // the legacy `onLoadedModelsChange(null)` clears the entire set. Subscribers (e.g. `useViewerExpressIdMaps`) need this
    // to re-fetch data after a model loads — the hook lives
    // outside IfcViewer's render tree, so a parent re-render
    // alone wouldn't propagate model-load events to it.
    const loadedModelsListenersRef = useRef<Set<(count: number) => void>>(
      new Set(),
    );
    // Handlers we registered on `highlighter.events.select` —
    // remembered so cleanup can detach them. The Highlighter
    // owns the lifecycle of these handlers once registered, but
    // removing them is the polite form for HMR / re-setup.
    const highlightHandlersRef = useRef<{
      onHighlight: (m: Record<string, Set<number>>) => void;
      onClear: (m: Record<string, Set<number>>) => void;
    } | null>(null);

    // Task 23: floor-plan planes added via addFloorPlanPlane.
    // Each entry tracks the mesh + its texture + material for
    // proper disposal. THREE references are cast through unknown
    // to keep the drift linter happy (no `import "three"` in new
    // code paths — the existing `import * as THREE` at the top
    // of the file covers us).
    const floorPlanPlanesRef = useRef<
      Map<string, { mesh: THREE.Mesh; material: THREE.MeshBasicMaterial; texture: THREE.CanvasTexture }>
    >(new Map());

    // Task 23.1: floor clip plane id returned by OBC.Clipper.
    // Null = no active floor clip. Set by setFloorClipPlane,
    // cleared on unmount or mode toggle.
    const floorClipPlaneIdRef = useRef<string | null>(null);

    // ─── Wave 13: 3D section planes ────────────────────────────
    // Ordered list (last entry = most recent) of section planes. We
    // track BOTH the engine plane id (for Clipper `list.delete(id)`)
    // plain (point, normal) data (for flip + saved-viewpoint
    // serialization). Distinct from `floorClipPlaneIdRef` — the floor
    // clip is level state, section planes are view state.
    const sectionPlanesRef = useRef<
      Array<{ id: string; point: { x: number; y: number; z: number }; normal: { x: number; y: number; z: number } }>
    >([]);
    // Lazily-resolved ClipStyler (registered as a components-front
    // component). Cached so repeated `addSectionPlane` calls share
    // one styler + one default style.
    const clipStylerRef = useRef<OBCF.ClipStyler | null>(null);

    // ─── Wave 14: GPU picking backend + bench ─────────────────────
    // `fastPickerRef` holds the FastModelPicker when it constructed
    // cleanly at mount; `pickBackendRef` records which resolution
    // path is live ("fast" | "raycaster"). Bench samples accumulate
    // only when `?bench=1` is present (dev-only, no prod overhead).
    const fastPickerRef = useRef<FastElementPicker | null>(null);
    const pickBackendRef = useRef<BackendId>("raycaster");
    // Wave 45: the worker virtual raycast (`FragmentsManager.raycast`) is
    // present. Set once after `fragments.init()` — when true it becomes the
    // PRIMARY pick backend (id-pass stays as fallback).
    const raycastAvailableRef = useRef<boolean>(false);
    // Wave 25: batched id-pass reader, when the TOE private internals are
    // present (fast backend). Null otherwise → the per-probe getItemAt path.
    const batchedIdPassRef = useRef<BatchedIdPassReader | null>(null);
    const benchEnabledRef = useRef<boolean>(isBenchEnabled());
    const benchSamplesRef = useRef<number[]>([]);
    const benchLastLogRef = useRef<number>(0);

    const [isReady, setIsReady] = useState(false);
    const [loadError, setLoadError] = useState<Error | null>(null);
    // Wave 33 — streaming settle-gate. `isStreaming` is true while the
    // loaded models' tile streams are still producing meshes
    // (`FragmentsModel.isBusy`), so the loading overlay hides the
    // cold-stream window where highlight round-trips queue behind the
    // worker and feel laggy. A hard 60 s cap always clears it, so a
    // wedged worker can never pin the loader forever.
    const [isStreaming, setIsStreaming] = useState(false);
    // Wave 34: progress within the streaming gate ("Loading model 2 of
    // 3…"). Set at pass start when fresh loads are expected; cleared
    // when the gate lifts.
    const [loadProgress, setLoadProgress] = useState<{
      done: number;
      total: number;
    } | null>(null);
    // Wave 61: the overlay lifted (capped wait for a big model) while the
    // view is still filling in — a small non-blocking chip says so.
    const [backgroundStreaming, setBackgroundStreaming] = useState(false);
    // The latest chip watcher owns the chip (an older pass's watcher
    // ending must not hide a newer pass's chip).
    const chipGenRef = useRef(0);

    // Wave 56-demo: flip the once-per-session flag when a load cycle
    // completes (loadCycleActive true -> false). Keying on the
    // transition — not on `isReady && !isStreaming` — avoids the gap
    // where setIsReady(true) lands before the streaming gate arms
    // (isReady=true, isStreaming=false), which would flip the flag too
    // early and suppress the overlay mid-load. The overlay stays up for
    // the WHOLE current load+settle window and is only suppressed for
    // SUBSEQUENT viewer mounts (module switches), which load fast from
    // IndexedDB (maintainer 2026-11-11: loader re-appeared on every
    // module switch; it should show once per session).
    // Flip only AFTER the streaming gate has armed (isStreaming true)
    // and then lifted (isStreaming false) with the viewer ready. This
    // skips the mount gap where setIsReady(true) lands BEFORE the
    // streaming gate arms (isReady=true, isStreaming=false) — flipping
    // there would suppress the overlay mid-load (broke the wave-34
    // gate tests). A parked/never-settling load (isStreaming stays
    // true) never flips the flag, so its overlay stays visible.
    // Wave 60: while the OPAQUE full-screen loading overlay covers the
    // viewer during a load, drawing the scene at 60 Hz underneath is
    // waste — on a big scene each frame redraws every freshly streamed
    // tile, keeping the main thread ~95% busy (measured, CPU profile)
    // while it also has to ingest the worker's tile messages. THROTTLE
    // (not pause) the renderer for exactly that window: one frame every
    // OVERLAY_RENDER_INTERVAL_MS keeps GPU uploads / shader compiles
    // incremental — a full pause deferred them all into the first frame
    // after the reveal (measured: a ~12 s frozen first frame on the
    // heavy scene). Only while loads stream; `renderPaused` still wins.
    const overlayCoversLoad =
      loadingOverlay && !ffViewerSessionLoadedOnce && isStreaming;
    useEffect(() => {
      const renderer = worldRef.current?.renderer as
        | OBC.SimpleRenderer
        | undefined;
      if (!renderer) return;
      if (!overlayCoversLoad) {
        renderer.enabled = !renderPausedRef.current;
        return;
      }
      renderer.enabled = false;
      let raf = 0;
      const timer = setInterval(() => {
        if (renderPausedRef.current) return;
        renderer.enabled = true; // the next animation frame draws once
        cancelAnimationFrame(raf);
        raf = requestAnimationFrame(() => {
          raf = requestAnimationFrame(() => {
            renderer.enabled = false;
          });
        });
      }, OVERLAY_RENDER_INTERVAL_MS);
      return () => {
        clearInterval(timer);
        cancelAnimationFrame(raf);
        renderer.enabled = !renderPausedRef.current;
      };
    }, [overlayCoversLoad, isReady]);
    const streamedOnceRef = useRef(false);
    useEffect(() => {
      if (isStreaming) streamedOnceRef.current = true;
      if (
        streamedOnceRef.current &&
        !isStreaming &&
        isReady &&
        !ffViewerSessionLoadedOnce
      ) {
        ffViewerSessionLoadedOnce = true;
      }
    }, [isStreaming, isReady]);

    // Task 20 §1.8.3: prop-injected data. Each prop has a safe
    // default (no-op register, empty array, no-op storey / frag
    // fetchers). The Settings app passes the live hooks; the
    // Models app passes `[]` + no-ops until Task 19.
    //
    // CRITICAL: the no-op fallbacks MUST be stable function
    // references across renders. The mount effect below
    // depends on `registerFragments` (and the other injected
    // helpers) directly. If the fallback were inline
    // `() => undefined`, every render would allocate a new
    // function, the dependency check would see a change, the
    // effect cleanup would tear down the OBC world, and the
    // world would be destroyed and recreated on every render —
    // an infinite create/destroy loop that prevents models
    // from ever stabilizing. (Caught by audit
    // docs/audit-post-phase-1-lite-2026-06-19.md.)
    //
    // Solution: keep the no-op in a ref so the reference is
    // stable for the lifetime of the component. The
    // `?? stableNoopRef.current` pattern reads from the ref
    // without re-creating the function each render.
    // Wave 73: every consumer callback is read through a ref and exposed to
    // the effects as a STABLE wrapper. The mount effect depends on
    // `registerFragments`; with the raw prop in its dep list a parent that
    // passed an inline arrow (a new identity every render) tore the whole
    // OBC world down and rebuilt it on every parent render. Now the world is
    // built once per mount whatever the callback identities do.
    const registerFragmentsPropRef = useRef(registerFragmentsProp);
    registerFragmentsPropRef.current = registerFragmentsProp;
    const getStoreysPropRef = useRef(getStoreysForBuildingProp);
    getStoreysPropRef.current = getStoreysForBuildingProp;
    const getFragBlobPropRef = useRef(getFragBlobProp);
    getFragBlobPropRef.current = getFragBlobProp;
    const onReadyPropRef = useRef(onReadyProp);
    onReadyPropRef.current = onReadyProp;
    const fitOnFirstLoadRef = useRef(fitOnFirstLoad);
    fitOnFirstLoadRef.current = fitOnFirstLoad;
    const showEngineLogoRef = useRef(showEngineLogo);
    showEngineLogoRef.current = showEngineLogo;
    // Cleanups registered through `onReady`'s `onDispose`; run (and cleared)
    // right before the world is disposed.
    const readyDisposersRef = useRef<Array<() => void>>([]);
    // The component's own handle (set by useImperativeHandle) for internal
    // callers such as fit-on-first-load.
    const handleSelfRef = useRef<IfcViewerHandle | null>(null);
    // True when at least one loaded model reports a finite bounding box.
    const hasFiniteModelBounds = (): boolean => {
      const list = fragmentsRef.current?.core.models.list;
      if (!list) return false;
      for (const model of list.values()) {
        const b = (model as unknown as { box?: THREE.Box3 }).box;
        if (
          b &&
          Number.isFinite(b.min.x) &&
          Number.isFinite(b.max.x) &&
          Number.isFinite(b.min.y) &&
          Number.isFinite(b.max.y) &&
          Number.isFinite(b.min.z) &&
          Number.isFinite(b.max.z)
        ) {
          return true;
        }
      }
      return false;
    };
    // Set once the first load of this mount was framed (or skipped), so the
    // fit happens at most once per mount.
    const firstFitDoneRef = useRef(false);
    // True once the user or the host moved the camera (pointer input /
    // setViewPose): fit-on-first-load then leaves it alone.
    const cameraMovedByHostRef = useRef(false);
    const registerFragments = useRef(
      (f: OBC.FragmentsManager | null): void => {
        registerFragmentsPropRef.current?.(f);
      },
    ).current;
    const getStoreysForBuilding = useRef(
      (b: string): Promise<StoreyMeta[]> =>
        getStoreysPropRef.current ? getStoreysPropRef.current(b) : Promise.resolve([]),
    ).current;
    const getFragBlob = useRef(
      (k: string): Promise<Blob | null> =>
        getFragBlobPropRef.current ? getFragBlobPropRef.current(k) : Promise.resolve(null),
    ).current;
    const files: IfcFileListItem[] = filesProp ?? [];

    // Wave 60: loads currently in flight, per file id. A load pass that
    // supersedes another (live-query re-emission) waits for the older
    // pass's in-flight `core.load` of the same file instead of starting
    // a duplicate load under the same model id.
    // Wave 60: frag size per loaded model id (load gate, see
    // GATE_BIG_MODEL_BYTES).
    const modelBytesRef = useRef<Map<string, number>>(new Map());
    const inflightLoadsRef = useRef<
      Map<string, { versionKey: string; done: Promise<void> }>
    >(new Map());
    // Wave 60: frag bytes read AHEAD of the viewer being ready (see the
    // prefetch effect below), keyed by fragBlobKey. Taken (and deleted)
    // by the load pass; anything left over is dropped when it is no
    // longer referenced.
    const fragPrefetchRef = useRef<Map<string, Promise<ArrayBuffer | null>>>(
      new Map(),
    );
    const readFragBuffer = async (
      key: string,
      name: string,
    ): Promise<ArrayBuffer | null> => {
      const blob = await getFragBlob(key);
      if (!blob) {
        // eslint-disable-next-line no-console
        console.warn("[IfcViewer] frag blob missing for", key);
        return null;
      }
      tel.breadcrumb("model", "load-blob", { file: name, bytes: blob.size });
      return blob.arrayBuffer();
    };
    /** The frag bytes for `key`: the prefetched read if there is one,
     *  else a fresh read. Each prefetched buffer is handed out ONCE (it
     *  is transferred to the worker by `core.load`). */
    const takeFragBuffer = (
      key: string,
      name: string,
    ): Promise<ArrayBuffer | null> => {
      const pre = fragPrefetchRef.current.get(key);
      if (pre) {
        fragPrefetchRef.current.delete(key);
        return pre;
      }
      return readFragBuffer(key, name);
    };

    // ---------- mount / unmount ----------

    useEffect(() => {
      if (!containerRef.current) return;

      // CRITICAL: reset disposedRef on each mount. React 18 StrictMode
      // runs effects twice (mount → cleanup → mount), and the cleanup
      // sets disposedRef = true. If we don't reset on the second mount,
      // the IIFE below bails out at its first guard and the viewer
      // stays stuck on 'Initializing...'.
      const myGen = ++mountGenRef.current;
      disposedRef.current = false;
      // True when THIS pass is no longer the live mount, even though the
      // shared flag says otherwise.
      const stale = (): boolean =>
        disposedRef.current || mountGenRef.current !== myGen;

      const container = containerRef.current;
      const components = new OBC.Components();
      componentsRef.current = components;

      const worlds = components.get(OBC.Worlds);

      const world = worlds.create<
        OBC.SimpleScene,
        OBC.OrthoPerspectiveCamera,
        OBC.SimpleRenderer
      >();
      world.name = "FreeFieldMain";
      world.scene = new OBC.SimpleScene(components);
      world.scene.setup(); // sets background color + adds a default grid
      // RendererWith2D = SimpleRenderer + a CSS2DRenderer layer. The 3D
      // measurement tools draw their labels / endpoints / snap marker as
      // CSS2DObjects; with a plain SimpleRenderer none of them ever
      // reached the screen (wave 67). The layer is gated so it costs
      // nothing unless a measurement is armed or on screen.
      const renderer2D = new OBCF.RendererWith2D(components, container);
      world.renderer = renderer2D;
      applyEngineLogo(renderer2D as unknown as EngineLogoTarget, showEngineLogoRef.current);
      labelLayerGateRef.current?.dispose();
      labelLayerGateRef.current = gateLabelLayer(
        renderer2D.three2D as unknown as LabelLayerRenderer,
        () =>
          isMeasureLayerNeeded(measure3DUsedRef.current) ||
          planMeasureLayerNeeded(),
      );
      // OrthoPerspectiveCamera extends SimpleCamera — same `controls`
      // API, plus `projection` (Perspective/Orthographic) and
      // navigation modes (Orbit/Plan/FirstPerson). Task 16b uses
      // these for the level view's flat ortho plan rendering.
      world.camera = new OBC.OrthoPerspectiveCamera(components);
      world.camera.controls.setLookAt(10, 10, 10, 0, 0, 0);
      // Wave 73: fit-on-first-load bookkeeping is per mount.
      firstFitDoneRef.current = false;
      cameraMovedByHostRef.current = false;
      // User input on the viewer (orbit / pan / zoom gestures, wheel) means
      // the user owns the camera now: fit-on-first-load must not undo it.
      // DOM-level on purpose (no extra camera-controls listeners).
      const markUserMovedCamera = (): void => {
        cameraMovedByHostRef.current = true;
      };
      const USER_CAMERA_EVENTS = ["pointerdown", "wheel", "touchstart"] as const;
      for (const type of USER_CAMERA_EVENTS) {
        container.addEventListener(type, markUserMovedCamera, { capture: true, passive: true });
      }

      // ─── Render on demand ──────────────────────────────────────
      // The renderer runs in MANUAL mode: the OBC loop still ticks every
      // animation frame (camera-controls, engine components), but the GPU
      // draw only happens when something invalidated the view. The engine
      // level sources (camera events, resize, clipping, scene children,
      // input, fragments tile application, busy models) are wired inside
      // installRenderOnDemand; the viewer-level ones call requestRender()
      // below (handle methods, highlight queue, visibility flush, section
      // fills, motion settle, pause/resume). `renderOnDemand={false}` or
      // `?ffrender=always` restores per-frame rendering.
      let mountRod: RenderOnDemand | null = null;
      {
        const rodCfg = renderOnDemandRef.current;
        let forceAlways = false;
        try {
          forceAlways =
            new URLSearchParams(window.location?.search ?? "").get("ffrender") ===
            "always";
        } catch {
          // no location (tests / workers)
        }
        const cfg: RenderOnDemandConfig =
          typeof rodCfg === "object" && rodCfg !== null ? rodCfg : {};
        const isDev = Boolean(
          (import.meta as unknown as { env?: { DEV?: boolean } }).env?.DEV,
        );
        let staleWarned = 0;
        // OBC.RendererMode is { MANUAL: 0, AUTO: 1 } (components 3.6).
        // Read defensively: module mocks without the export throw on access.
        let rendererModes: { MANUAL?: number; AUTO?: number } | undefined;
        try {
          rendererModes = (OBC as unknown as {
            RendererMode?: { MANUAL?: number; AUTO?: number };
          }).RendererMode;
        } catch {
          rendererModes = undefined;
        }
        mountRod = installRenderOnDemand({
          streamRenderIntervalMs: STREAM_RENDER_INTERVAL_MS,
          ...cfg,
          streamThrottle: () => loadStreamingRef.current,
          mode: rodCfg === false || forceAlways ? "always" : "on-demand",
          manualMode: rendererModes?.MANUAL ?? 0,
          autoMode: rendererModes?.AUTO ?? 1,
          renderer: world.renderer as unknown as RodRenderer,
          frameEvent: (world as unknown as { onBeforeUpdate?: EngineEvent<unknown> })
            .onBeforeUpdate,
          controls: world.camera.controls as unknown as Partial<CameraEventTarget>,
          getCamera: () =>
            (safeWorldCamera(world) as { three?: RodCamera } | undefined)?.three,
          getScene: () =>
            (world.scene as unknown as { three?: RodScene } | undefined)?.three,
          inputTarget: container,
          keyTarget: typeof window !== "undefined" ? window : null,
          getModels: () =>
            (fragmentsRef.current?.core.models.list.values() ??
              []) as Iterable<RodModel>,
          continuous: () => {
            if (navSpeedupsRef.current?.controller.moving) return "moving";
            // The 3D measurement tools snap asynchronously (worker
            // raycasts land after the pointer stopped) and draw their
            // own markers: keep drawing while one is armed.
            if (measure3DRef.current?.component.enabled) return "measure-tool";
            return null;
          },
          onStale: (info) => {
            tel.breadcrumb("render", "stale-frame", {
              changed: info.changed.join(","),
              count: info.count,
            });
            if (isDev && staleWarned < 20) {
              staleWarned += 1;
              // eslint-disable-next-line no-console
              console.warn(
                `[IfcViewer] render-on-demand: view changed without an invalidation (${info.changed.join(", ")}) — rendered by the stale-frame guard; wire a requestRender() at the source.`,
              );
            }
          },
        });
        rodRef.current = mountRod;
      }

      // Wave 32: camera motion has to refresh the fragments view, or the
      // tiles for what is now on screen are NEVER requested. Fragments
      // re-pushes tiles per model only inside `FragmentsModels.update()`
      // (REFRESH_VIEW -> worker re-samples the frustum), and nothing else
      // calls it after the initial load. TOE's own `Views` component wires
      // exactly this (controls 'rest' -> fragments update), but this viewer
      // REPLACED Views with LevelPlanController and the wiring was lost
      // with it.
      //
      // Measured consequence on a 38 MB MEP model: 20 s idle -> 0 tiles,
      // 40 s -> 0 tiles, orbit -> 0 tiles, ONE explicit `core.update()` ->
      // tiles appear. The model is therefore invisible to the GPU id pass,
      // every pick reads void, and the user gets "clicks do nothing" on
      // exactly the model they can see.
      //
      // `update()` WITHOUT the force flag, deliberately: the forced variant
      // parks on a worker FINISH behind every queued tile and storage
      // download (established in wave 28), while the unforced call is
      // throttled internally to 10 Hz (`maxUpdateRate: 100`). It now runs
      // once per camera SETTLE (navigation speedups below), not per drag
      // step: while moving the models are frozen.
      const refreshFragmentsView = (): void => {
        const frags = fragmentsRef.current;
        if (!frags) return;
        try {
          void frags.core.update().catch(() => {
            /* a failed refresh is retried on the next camera event */
          });
        } catch {
          // A wedged engine must not throw out of a camera callback.
        }
      };
      //
      // Navigation speedups (perf wave): while the camera MOVES the
      // viewer runs in "motion mode" (src/perf/navigationSpeedups.ts):
      //   - the fragments models are frozen (no REFRESH_VIEW per
      //     intermediate pose; the worker re-culls once, at rest),
      //   - only the N largest on-screen tiles are drawn (adaptive N),
      //   - the pixel ratio is halved.
      // Every settle (rest / sleep / 400 ms without camera events) puts
      // everything back and runs ONE unforced refresh — that is also what
      // ends every programmatic move (fit, setLookAt, setPose, level plan)
      // with a fresh view.
      {
        const ctl = world.camera.controls as unknown as
          | Partial<CameraEventTarget>
          | undefined;
        if (typeof ctl?.addEventListener === "function") {
          const cfg = motionSpeedupsRef.current;
          const renderer = world.renderer as unknown as {
            onBeforeUpdate?: EngineEvent<unknown>;
            onAfterUpdate?: EngineEvent<unknown>;
            three?: {
              getPixelRatio?: () => number;
              setPixelRatio?: (r: number) => void;
              clippingPlanes?: THREE.Plane[];
            };
          };
          navSpeedupsRef.current = installNavigationSpeedups({
            controls: ctl as CameraEventTarget,
            renderer,
            getCamera: () =>
              (safeWorldCamera(world) as { three?: THREE.Camera } | undefined)?.three,
            getModels: () =>
              (fragmentsRef.current?.core.models.list.values() ??
                []) as Iterable<SpeedupModel>,
            // Every settle (rest / sleep / idle / forced) restores the
            // full pixel ratio — a canvas resize, which CLEARS the drawing
            // buffer — and re-tiles the view: both need a fresh frame.
            refresh: () => {
              refreshFragmentsView();
              requestRender("motion-settle");
            },
            budget: cfg === false ? false : cfg?.budget,
            movingPixelRatioScale: cfg === false ? 1 : cfg?.movingPixelRatioScale,
            freezeView: cfg === false ? false : cfg?.freezeView,
            // One breadcrumb per gesture (not per frame).
            onStop: (reason, stats) => {
              requestRender("motion-end");
              tel.breadcrumb("nav", "motion-end", { reason, ...stats });
            },
          });
        }
        // OrthoPerspectiveCamera swaps `camera.three` on a projection
        // change (level plan, setViewPose). Fragments culls against the
        // camera it was given via useCamera(), so re-point every model at
        // the new camera and refresh — otherwise the ortho plan would be
        // tiled for the stale perspective frustum.
        const projection = (
          world.camera as unknown as {
            projection?: { onChanged?: EngineEvent<unknown> };
          }
        ).projection;
        if (typeof projection?.onChanged?.add === "function") {
          const onProjectionChanged = (cam: unknown): void => {
            navSpeedupsRef.current?.forceRest();
            const camera =
              (cam as THREE.Camera | undefined) ??
              (safeWorldCamera(world) as { three?: THREE.Camera } | undefined)?.three;
            const frags = fragmentsRef.current;
            if (camera && frags) {
              for (const model of frags.core.models.list.values()) {
                try {
                  (model as unknown as { useCamera?: (c: THREE.Camera) => void }).useCamera?.(camera);
                } catch {
                  // a disposed model must not break the projection swap
                }
              }
            }
            refreshFragmentsView();
            requestRender("projection");
          };
          projection.onChanged.add(onProjectionChanged);
          projectionListenerRef.current = {
            event: projection.onChanged,
            handler: onProjectionChanged,
          };
        }
      }

      // Required to start the OBC update loop.
      components.init();

      // Override OBC's default dark scene/renderer background with
      // the app's light gray. Must be AFTER components.init() — the
      // renderer's init phase sets its own clear color, which would
      // overwrite any earlier setting.
      //
      // Wave 19c (on-device root-cause fix): the background is the
      // RENDERER CLEAR COLOR only — `scene.background` stays null.
      // three.js draws a `scene.background` Color as a fullscreen
      // tone-mapped quad on EVERY `render()` call, and TOE's
      // FastModelPicker id pass renders the scene once PER MODEL
      // into one shared target — so with a scene background, the
      // second model's background quad wipes the first model's
      // id-encoded pixels. The last-rendered model picks fine and
      // every earlier model reads void → the field report "MEP
      // clicks say empty space, structural OK" (structural happened
      // to render last). A/B verified live: same pixel, same camera
      // — scene.background = Color → id pass reads background gray
      // (226,229,231) → void; scene.background = null → id pass
      // resolves expressId 465474 on the chiller. The clear color
      // below gives an identical-looking screen (autoClear=true on
      // the normal render path) without the per-render quad.
      world.scene.three.background = null;
      world.renderer.three.setClearColor(0xf2f3f4, 1);

      worldRef.current = world;
      world.renderer.enabled = !renderPausedRef.current;
      const detachTelemetry = attachViewerTelemetry(world.renderer.three, world.renderer.three.domElement);

      // Build the FragmentsModels manager. We need a same-origin
      // worker URL, so we fetch the worker source from the CDN, wrap
      // it in a Blob, and hand the blob URL to the constructor. This
      // is exactly what `FRAGS.FragmentsModels.getWorker()` does
      // internally in newer versions of the library; we reimplement
      // it for 3.0.11 which doesn't expose that helper.
      //
      // Async work happens in an IIFE so the useEffect callback itself
      // stays synchronous (React requires that). The cleanup path
      // uses fragmentsRef.current, which is only set after the async
      // work completes — if cleanup runs before that, fragments is
      // null and we just dispose the world (which is safe).
      (async () => {
        if (stale()) return;
        const workerUrl = await getFragmentsWorkerBlobUrl();
        if (stale()) return;
        // Use OBC.FragmentsManager (the high-level wrapper around
        // FragmentsModels). Per the OBC docs, FragmentsManager wires
        // the camera-controls -> fragments.update() event and the
        // polygon-offset material setup automatically. We pass a
        // same-origin blob URL (cross-origin CDN URLs get blocked by
        // browser CORP — see getFragmentsWorkerBlobUrl).
        const fragments = components.get(OBC.FragmentsManager);
        // Wave 60: the parallel load pass spreads models over the
        // engine's worker pool (one parse per worker). The engine sizes
        // the pool `hardwareConcurrency - 3`, floored at 2 — on 4–5 core
        // machines that is 2 workers for 3–4 models, so two parses
        // queue behind each other. Measured on a 4-core laptop (primary
        // scenario): 3 workers lifted the overlay ~1 s sooner. Bigger
        // machines keep the engine default.
        fragments.init(
          workerUrl,
          fragmentsPoolOptions(memoryTuningRef.current?.maxWorkers),
        );
        if (memoryTuningRef.current) {
          // New models inherit the engine setting; the budgets are read by
          // the patched engine on every view refresh.
          const eff = effectiveMemory(
            memoryTuningRef.current,
            memoryPressureRef.current,
          );
          const st = (
            fragments.core as unknown as {
              settings?: { graphicsQuality?: number };
            }
          )?.settings;
          if (st) st.graphicsQuality = eff.graphicsQuality;
          publishEngineBudget(eff);
        }
        // Wave 73: `fragments.core` must not throw after dispose.
        guardFragmentsManager(fragments);
        // Wave 60: models load in PARALLEL, so the engine's
        // `autoCoordinate` (align everything to whichever model's
        // coordinates arrive first) would make the world origin a race.
        // The load pass aligns models itself, deterministically against
        // the first file in list order — the same frame the sequential
        // loop produced. Optional chaining: test doubles have no settings.
        const coreSettings = (
          fragments.core as unknown as { settings?: { autoCoordinate?: boolean } }
        )?.settings;
        if (coreSettings) coreSettings.autoCoordinate = false;
        if (stale()) return;
        fragmentsRef.current = fragments;
        // Render on demand: watch tile application + model add/remove.
        rodRef.current?.watchFragments(
          fragments as unknown as Parameters<RenderOnDemand["watchFragments"]>[0],
        );
        // Wave 45: register the worker virtual raycast as the primary pick
        // backend when the manager exposes it (public API on 3.4.6). The
        // id-pass / Raycasters stay as fallback. Checked at click time via
        // `raycastAvailableRef`.
        raycastAvailableRef.current =
          typeof (fragments as unknown as WorkerRaycaster).raycast ===
          "function";

        // Hand the manager to the pipeline so future loadIfc() calls
        // can stream new frags into the viewer via fragments.core.
        registerFragments(fragments);

        // Task 16: register TechnicalDrawings + Classifier + EdgeProjector.
        // These components are stateless coordinators — no init() needed.
        components.get(OBC.TechnicalDrawings);
        components.get(OBC.Classifier);
        components.get(OBC.EdgeProjector).enabled = true;

        // ─── Wave 14: feature-detect the GPU picker backend ──────
        // FastModelPicker (core 3.4.6) renders an id/depth/normal
        // pass directly against `world.renderer.three` and reads back
        // one pixel instead of a full Raycasters sweep. We attempt to
        // create it here (cached per-world via OBC.FastModelPickers);
        // if its constructor throws — no renderer, no usable canvas
        // (jsdom / WebGL-less), or a renderer it can't drive — we fall
        // back to the engine's Raycasters and log which path is live.
        {
          let fastInitError: string | null = null;
          try {
            const fastPickers = components.get(OBC.FastModelPickers);
            const picker = fastPickers.get(world) as unknown as FastElementPicker;
            fastPickerRef.current = picker;
          } catch (err) {
            fastInitError = err instanceof Error ? err.message : String(err);
            fastPickerRef.current = null;
          }
          pickBackendRef.current = chooseBackend({
            fastAvailable: fastPickerRef.current !== null,
            fastInitError,
            raycasterAvailable: true, // stock; resolved below too
          });
          // Wave 25: detect the TOE private-internal id-pass seam once.
          // When present this is the batched reader (1 render/click);
          // when absent the pick path stays on the per-probe getItemAt
          // loop. Detection never throws.
          batchedIdPassRef.current =
            pickBackendRef.current === "fast" && fastPickerRef.current
              ? detectIdPassInterop(fastPickerRef.current, {
                  scissor: isRenderScissorEnabled(),
                }).reader
              : null;
          // Wave 19d: debug surfaces are OPT-IN (dev builds only,
          // armed with ?ffdebug=1 — see picking/debugTools.ts). The
          // old always-on `pick backend` console.info is gone; a
          // fast-init FAILURE still warns unconditionally because it
          // means the viewer silently degraded to the Highlighter
          // path — that is a real anomaly, not chatter.
          if (fastInitError) {
            // eslint-disable-next-line no-console
            console.warn(
              `[IfcViewer] fast pick init failed — backend: ${pickBackendRef.current}: ${fastInitError}`,
            );
          }
          if (
            (import.meta as unknown as { env?: { DEV?: boolean } }).env?.DEV &&
            isDebugToolsEnabled()
          ) {
            (window as unknown as { __ffDebug?: DebugToolsSurface }).__ffDebug =
              buildDebugToolsSurface({
                picker: fastPickerRef.current,
                world,
                fragments,
                backend: pickBackendRef.current,
                getCanvas: () =>
                  (world.renderer?.three?.domElement as HTMLCanvasElement) ??
                  null,
                // Wave 22: lazy getters — the highlighter is created
                // later in this IIFE, and the chain counters live in
                // component-scope refs.
                getHighlighter: () => highlighterRef.current,
                getChainStats: () => chainStatsRef.current,
              });
            // eslint-disable-next-line no-console
            console.info(
              `[IfcViewer] dev debug tools armed — pick backend: ${pickBackendRef.current}`,
            );
            // Wave 26: chain-perf telemetry → Sentry. While this
            // surface is armed, every 5 s window with clicks becomes
            // ONE `debug-perf-chain` info event (chain latencies,
            // bench p50/p95, renders-per-click, the full stats()
            // snapshot; Channel A auto-attaches the renderer report).
            // Idle windows ship nothing. Debug-only by construction:
            // this block never runs in prod builds or without the flag.
            debugPerfDisposeRef.current = startDebugPerfTelemetry(
              {
                getChainStats: () => chainStatsRef.current,
                getBenchSamples: () => benchSamplesRef.current,
                getBackend: () => pickBackendRef.current,
                getBatchedReaderActive: () =>
                  batchedIdPassRef.current !== null,
                getDebugStats: () =>
                  (
                    window as unknown as {
                      __ffDebug?: { stats?: () => unknown };
                    }
                  ).__ffDebug?.stats?.() ?? null,
              },
              (payload) => shipDebugPerf(payload),
            );
          }
        }

        // ─── Task 21: initialize OBCF.Highlighter ───────────────
        // Visual feedback for the picked element. The Highlighter
        // lives in @thatopen/components-front (NOT @thatopen/
        // components — verified against the OBC 3.4.6 type
        // declarations). `setup()` is synchronous (returns void,
        // NOT a Promise) and accepts a partial HighlighterConfig;
        // we pass the minimum needed for our use case:
        //   - selectMaterialDefinition: the visual style applied
        //     when an element is highlighted (orange tint at 50%
        //     opacity, double-sided so back faces are visible)
        //   - autoHighlightOnClick: false — we have our own
        //     click-to-pick pipeline (Task 19) and don't want
        //     the Highlighter's own DOM listener competing
        //   - multiple: "none" — single-select MVP scope; the
        //     selection set holds exactly one element at a time
        //   - world: the engine world to attach the highlight
        //     materials to
        //
        // StrictMode guard: this IIFE is async, so it can resume
        // AFTER React's strict-mode cleanup of the first mount has
        // already disposed `world` and `components`. The existing
        // `components.get(OBC.X)` calls below don't touch
        // `world.renderer`, so they survive. The Highlighter does:
        // its setup() creates a SimpleRaycaster that needs
        // `world.renderer.three.domElement`. If `world.renderer`
        // is gone (StrictMode double-mount race), skip — the next
        // mount's IIFE will do the work, no visual regression.
        if (!world.renderer) {
          // eslint-disable-next-line no-console
          console.warn(
            "[IfcViewer] highlighter.setup skipped: world.renderer was disposed (StrictMode race).",
          );
        } else {
          const highlighter = components.get(OBCF.Highlighter);
          // Pre-warm the raycaster for this world. The TOE
          // canonical example and tutorial BOTH call this
          // BEFORE highlighter.setup(). Without it, the
          // Highlighter's internal click handler uses a
          // raycaster that may not be bound to the correct
          // world, causing picks to silently fail.
          // Source: https://docs.thatopen.com/Tutorials/Components/Front/Highlighter
          //   > const casters = components.get(OBC.Raycasters);
          //   > casters.get(world);
          components.get(OBC.Raycasters).get(world);
          highlighter.setup({
            world,
            selectMaterialDefinition: {
              color: new THREE.Color(0xff6a00),
              opacity: 0.5,
              transparent: true,
              renderedFaces: 0, // FRAGS.RenderedFaces.ONE = front only (TOE canonical)
            },
            // For consumers that opt into `disableSelection` (LinkView's
            // spawn-point / third-person-look flows and any future
            // click-to-place tool), the Highlighter's auto-pick would
            // steal the click and produce a stray orange tint. Pass
            // `autoHighlightOnClick: false` to suppress the DOM click
            // handler entirely; the viewer still owns a Highlighter
            // instance for any consumer that wants to drive selection
            // programmatically. The `disableSelection` branch below
            // also skips wiring `events.select.onHighlight` / `onClear`
            // and the pending-pick drain (those paths become
            // dead-code when the selection surface is closed).
            //
            // Wave 19: when the fast pick backend is live we ALSO set
            // `autoHighlightOnClick: false` and install our OWN canvas
            // click pipeline (see installPickSubscription) that resolves
            // selection through FastModelPicker.getFullPick() — the GPU
            // id pass spans every registered model, so a click on model
            // #2 resolves its real `{modelId, localId, point}`. The
            // Highlighter's own auto-pick must not compete in this mode.
            autoHighlightOnClick:
              !disableSelection &&
              builtInClickPickRef.current &&
              pickBackendRef.current !== "fast",
          });
          // `multiple` lives on the Highlighter instance, not the
          // HighlighterConfig — set it after setup. "none" = single
          // selection (MVP scope); follow-up can lift to "shiftKey"
          // to enable additive selection without an API change.
          highlighter.multiple = "none";
          highlighterRef.current = highlighter;

          if (!disableSelection) {
            // Mirror Highlighter-internal events into our selection
            // state. The Highlighter can clear its own selection via
            // its own UI (not exposed in our MVP but the API path
            // exists); keeping selectionRef in sync means external
            // clearing propagates to subscribers cleanly.
            const onHighlightHandler = (
              modelIdMap: Record<string, Set<number>>,
            ): void => {
              const next = new Map<string, Set<number>>();
              for (const [modelId, ids] of Object.entries(modelIdMap)) {
                next.set(modelId, new Set(ids));
              }
              selectionRef.current = next;
              for (const cb of selectionListenersRef.current) {
                cb(selectionRef.current);
              }
            };
            const onClearHandler = (
              modelIdMap: Record<string, Set<number>>,
            ): void => {
              // Wave 21: ignore STALE clears. When a selection is
              // REPLACED, the Highlighter fires onClear for the
              // PREVIOUS map — asynchronously, i.e. after the newer
              // click already set selectionRef and stashed its click
              // point. Honouring it used to wipe both, dropping the
              // tap-to-create marker to the bbox centre on every
              // click after the first. A clear only applies when its
              // payload matches what we currently hold — the genuine
              // deselect path (and no-op when we're already empty).
              const current = selectionRef.current;
              if (
                current.size > 0 &&
                selectionFingerprint(current) !==
                  selectionFingerprint(new Map(Object.entries(modelIdMap)))
              ) {
                return;
              }
              lastPickPointRef.current = null;
              lastPickNormalRef.current = null;
              pendingPickKeyRef.current = null;
              selectionRef.current = new Map();
              for (const cb of selectionListenersRef.current) {
                cb(selectionRef.current);
              }
            };
            highlighter.events.select.onHighlight.add(onHighlightHandler);
            highlighter.events.select.onClear.add(onClearHandler);
            highlightHandlersRef.current = {
              onHighlight: onHighlightHandler,
              onClear: onClearHandler,
            };

            // Drain the pending pick subscription (if any). The
            // PropertiesDrawer (or other consumer) may have called
            // setOnElementPick before the Highlighter was ready —
            // install the subscription now that we have it.
            installPickSubscription(
              highlighter,
              pendingPickCallbackRef.current,
            );
          }
        }

        // Create the LevelPlanController (replaces OBC.Views cut-plane logic).
        levelPlanRef.current = createLevelPlanController(world, fragments, components);
        install2DMeasureWiring();

        if (stale()) return;
        setIsReady(true);
        // Wave 73: hand the live engine objects to the consumer once, after
        // everything above is wired. A throwing consumer must not take the
        // viewer down with it.
        try {
          onReadyPropRef.current?.({
            components,
            world,
            renderer: world.renderer as OBC.SimpleRenderer,
            camera: world.camera,
            fragments,
            onDispose: (cb) => {
              readyDisposersRef.current.push(cb);
            },
          });
        } catch (err) {
          // eslint-disable-next-line no-console
          console.warn("[IfcViewer] onReady callback threw:", err);
        }
      })().catch((err) => {
        // If the outer effect has been disposed (StrictMode double
        // invoke, real unmount, or HMR) — or a NEWER mount has taken
        // over while this pass was in flight — the failure belongs to a
        // dead pass. The live mount's own IIFE does the work.
        if (stale()) return;
        // eslint-disable-next-line no-console
        console.error("[IfcViewer] failed to initialize fragments:", err);
      });

      // Cleanup: only run on the *real* unmount, not the strict-mode
      // dev-only double-unmount. The ref flag is the source of truth.
      return () => {
        if (disposedRef.current) return;
        disposedRef.current = true;
        clearEngineBudget();
        memoryPressureRef.current = "none";
        // Wave 32: does THIS cleanup still own the shared refs? A
        // superseded mount has already installed its own engine objects;
        // clearing those refs here is what blindsided the live viewer.
        // Captured up front because returning from `finally` would swallow
        // disposal errors.
        // (react-hooks/exhaustive-deps flags this as if the ref held a DOM
        // node: `mountGenRef` is a plain integer written only by this
        // effect, and reading it at cleanup time is the whole point.)
        // eslint-disable-next-line react-hooks/exhaustive-deps
        const ownsSharedRefs = mountGenRef.current === myGen;
        try {
          // Wave 73: consumer cleanups registered via onReady's onDispose
          // run first, while the engine objects are still alive.
          for (const cb of readyDisposersRef.current.splice(0)) {
            try {
              cb();
            } catch {
              // a consumer cleanup must not block the teardown
            }
          }
          for (const type of USER_CAMERA_EVENTS) {
            container.removeEventListener(type, markUserMovedCamera, { capture: true });
          }
          // Wave 73: stop the world's update loop FIRST. The engine keeps
          // ticking `Components.update` (one rAF per frame) and
          // `World.update` (scene -> camera -> renderer) until they are
          // disabled; a tick that lands between the camera being disposed
          // and the loop actually stopping reads `world.camera` and throws
          // "No camera initialized!" as an uncaught page error. Disable both
          // before any of the listeners / controllers below are torn down.
          try {
            components.enabled = false;
            (world as { enabled: boolean }).enabled = false;
          } catch {
            // already disposed: nothing left to stop
          }
          // Navigation speedups: leave motion mode (restores pixel
          // ratio, unfreezes models) and detach the camera / renderer
          // listeners this mount attached.
          try {
            navSpeedupsRef.current?.dispose();
          } catch {
            // already gone; nothing to detach
          }
          navSpeedupsRef.current = null;
          // Render on demand: detach every source and put the renderer
          // back in AUTO mode. Only this mount's instance; the ref is
          // cleared only when it still points at it.
          mountRod?.dispose();
          if (rodRef.current === mountRod) rodRef.current = null;
          const projListener = projectionListenerRef.current;
          if (projListener) {
            try {
              projListener.event.remove?.(projListener.handler);
            } catch {
              // already gone
            }
            projectionListenerRef.current = null;
          }
          detachTelemetry();
          // Task 18: tear down any active measure tool wiring
          // FIRST, before the components cascade. The measure
          // cleanup detaches the click/mousemove/keydown
          // listeners; if we dispose the world first, the
          // listeners would still fire on a disposed container
          // and try to read from a null world.
          if (measureCleanupRef.current) {
            measureCleanupRef.current();
            measureCleanupRef.current = null;
          }
          // Task 19: tear down pick wiring BEFORE the components
          // cascade. The click listener reads worldRef/components
          // — same invariant as the measure cleanup.
          if (pickCleanupRef.current) {
            pickCleanupRef.current();
            pickCleanupRef.current = null;
            pickCallbackRef.current = null;
          }
          // Wave 12: tear down the 3D measurement session (disables
          // the active measurement component + detaches its click /
          // readout listeners and restores selection/navigation). Must
          // run BEFORE components.dispose() so the component's
          // `enabled = false` path can still cancel cleanly.
          // Wave 63: clear every type's measurements too.
          clearAllMeasure3D();
          for (const unsub of measureListUnsubsRef.current.values()) unsub();
          measureListUnsubsRef.current.clear();
          measureVariantsRef.current.clear();
          measureListCbRef.current = null;
          labelLayerGateRef.current?.dispose();
          labelLayerGateRef.current = null;
          measure3DUsedRef.current.clear();
          deactivateMeasure3D();
          measureReadoutCbRef.current = null;
          // Task 19: cancel any pending visibility flush. If a
          // RAF was queued but didn't fire yet, the flush callback
          // would read disposedRef and bail out — but canceling is
          // cheaper than the closure hop.
          if (rafHandleRef.current !== null) {
            cancelAnimationFrame(rafHandleRef.current);
            rafHandleRef.current = null;
          }
          pendingVisibilityRef.current = [];
          hiderRef.current = null;
          // Dispose the LevelPlanController first.
          if (levelPlanRef.current) {
            levelPlanRef.current.dispose();
            levelPlanRef.current = null;
          }
          // Drop the pipeline's handle first so a late loadIfc doesn't
          // try to call into a disposing fragments instance.
          registerFragments(null);
          // Task 21: detach Highlighter event listeners BEFORE
          // disposing it (otherwise the disposed component can't
          // remove handlers that point at it).
          const h = highlighterRef.current;
          const hh = highlightHandlersRef.current;
          if (h && hh) {
            h.events.select.onHighlight.remove(hh.onHighlight);
            h.events.select.onClear.remove(hh.onClear);
          }
          highlightHandlersRef.current = null;
          if (h) {
            void h.dispose().catch((err: unknown) => {
              // eslint-disable-next-line no-console
              console.warn("[IfcViewer] highlighter.dispose failed:", err);
            });
            highlighterRef.current = null;
          }
          // Task 23: dispose floor-plan planes before the
          // components cascade. Each plane holds a Three.js
          // Mesh, Material, and CanvasTexture — the material
          // references the texture, so dispose texture last.
          {
            const planes = floorPlanPlanesRef.current;
            for (const [, entry] of planes) {
              entry.mesh.removeFromParent();
              entry.material.dispose();
              entry.texture.dispose();
            }
            planes.clear();
          }
          // Task 23.1: remove the floor clip plane (OBC.Clipper).
          // Must run BEFORE components.dispose() — the Clipper
          // needs the world/renderer alive for teardown.
          {
            const clipId = floorClipPlaneIdRef.current;
            if (clipId && componentsRef.current) {
              try {
                const clipper = componentsRef.current.get(OBC.Clipper);
                removeClippingPlanesById(clipper, [clipId]);
              } catch {
                // Components may already be in partial-dispose
                // state; ignore teardown errors.
              }
            }
            floorClipPlaneIdRef.current = null;
          }
          // Wave 13: remove section planes before the components
          // cascade (same reason as the floor clip). Their ClipStyler
          // edges are auto-disposed by the Clipper plane's onDisposed
          // link as each plane is deleted.
          {
            const sectionPlanes = sectionPlanesRef.current;
            if (sectionPlanes.length && componentsRef.current) {
              try {
                const clipper = componentsRef.current.get(OBC.Clipper);
                removeClippingPlanesById(
                  clipper,
                  sectionPlanes.map((p) => p.id),
                );
              } catch {
                // ignore partial-dispose teardown errors.
              }
            }
            sectionPlanesRef.current = [];
            clipStylerRef.current = null;
          }
          // components.dispose() cascades to all child components
          // (Worlds, Classifier, renderers, etc.) and stops the
          // update loop. Must run BEFORE fragments.dispose():
          // Classifier.resetHighlight() accesses FragmentsManager
          // during its dispose cascade, so FragmentsManager must
          // still be alive at this point.
          components.dispose();
          // Dispose fragments AFTER components — the cascade above
          // may still reference it (e.g. Classifier.clear()).
          const f = fragmentsRef.current;
          if (f) {
            void disposeFragmentsManager(f);
            fragmentsRef.current = null;
          }
          // Clear the active level plan name so a remount doesn't
          // inherit a stale value.
          viewerSliceRef.current?.setActiveStoreyName(null);
        } catch (err) {
          // eslint-disable-next-line no-console
          console.warn("[IfcViewer] disposal threw:", err);
        } finally {
          // Wave 32: only the mount that still owns the refs may drop
          // them. A superseded cleanup clearing them left the LIVE viewer
          // pointing at disposed objects — broken highlighting, degraded
          // pick backend, stuck tints.
          if (ownsSharedRefs) {
            // Drop the stats overlay DOM node so a remount starts fresh.
            worldRef.current = null;
            componentsRef.current = null;
            // Wave 14: FastModelPicker is disposed by the
            // FastModelPickers component during components.dispose()
            // (its world.onDisposed hook). Clear our refs so a remount
            // re-runs the feature detection fresh.
            // Wave 26: stop the chain-perf emitter (final flush ships
            // any clicks collected since the last interval).
            debugPerfDisposeRef.current?.();
            debugPerfDisposeRef.current = null;
            fastPickerRef.current = null;
            batchedIdPassRef.current = null;
            pickBackendRef.current = "raycaster";
            // Wave 63: per-model state belongs to the fragments
            // instance just disposed. A remount (StrictMode, a new
            // `registerFragments`) must reload every model from
            // scratch, and the load effect must wait for the NEW
            // instance — so `isReady` drops until it is up again.
            for (const id of loadedModelIdsRef.current) {
              closeViewerModelBuffer(id);
            }
            const hadModels = loadedModelIdsRef.current.size > 0;
            loadedModelIdsRef.current.clear();
            loadedVersionRef.current.clear();
            loadedBuildingRef.current = null;
            modelBytesRef.current.clear();
            inflightLoadsRef.current.clear();
            pendingDisposesRef.current = [];
            reopenStoreyAfterSwapRef.current = null;
            streamingArmedRef.current = false;
            loadStreamingRef.current = false;
            selectionRef.current = new Map();
            lastColoredRef.current = null;
            lastPickPointRef.current = null;
            lastPickNormalRef.current = null;
            pendingPickKeyRef.current = null;
            setIsReady(false);
            if (hadModels) {
              loadedModelsListenersRef.current.forEach((cb) => cb(0));
            }
          }
        }
      };
    }, [registerFragments]);

    // ---------- building change: dispose old, load new ----------

    /**
     * Wave 31: release everything whose lifetime is bound to a loaded
     * model, so a NEW version of the same file can take its place.
     * Called from the load effect below when a file's version identity
     * changed under an already-loaded model id. Each step exists
     * because skipping it leaks into the new version:
     *   - `disposeModel` - worker state and tile meshes;
     *   - `closeViewerModelBuffer` - the per-model telemetry ring,
     *     which every other dispose path already closes;
     *   - the coalesced-highlight target - a tint painted on a disposed
     *     model can never be reset, so the next selection would try to
     *     un-paint geometry that is gone;
     *   - the tap-to-create anchor - a point in the OLD geometry's
     *     world space;
     *   - the selection, when it referred to this model;
     *   - the open level plan - its storey list and projected drawing
     *     came from the old version's storeys;
     *   - finally the loaded-models notify, which is what makes
     *     `useModelPropertyIndex` PRUNE the stale property index (the
     *     re-load notifies again, which rebuilds it).
     *
     * It deliberately does not call `handle.clearSelection()`: that
     * path warns and returns when `disableSelection` is on, and a
     * read-only viewer cannot select but still must not keep a stale
     * model or a stale index.
     */
    const dropLoadedModelForSwap = async (
      frags: NonNullable<typeof fragmentsRef.current>,
      modelId: string,
    ): Promise<void> => {
      closeViewerModelBuffer(modelId);
      hiddenTrackerRef.current.clear(modelId);
      try {
        await frags.core.disposeModel(modelId);
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn("[IfcViewer] disposeModel on version swap:", err);
      }
      loadedModelIdsRef.current.delete(modelId);
      loadedVersionRef.current.delete(modelId);
      // Wave 67: measurements point into the old version's geometry.
      clearMeasurementsOnUnload();
      if (lastColoredRef.current && modelId in lastColoredRef.current) {
        const rest = { ...lastColoredRef.current };
        delete rest[modelId];
        lastColoredRef.current =
          Object.keys(rest).length > 0 ? rest : null;
      }
      lastPickPointRef.current = null;
      lastPickNormalRef.current = null;
      pendingPickKeyRef.current = null;
      if (selectionRef.current.has(modelId)) {
        selectionRef.current = new Map();
        queueHighlight(null);
        for (const cb of selectionListenersRef.current) {
          cb(selectionRef.current);
        }
      }
      // Wave 63: only an OPEN plan is closed (close() also moves the
      // camera), and the same storey re-opens once the new version
      // has loaded (see the end of the load pass).
      const plan = levelPlanRef.current;
      if (plan && plan.activeStoreyName !== null) {
        reopenStoreyAfterSwapRef.current = plan.activeStoreyName;
        try {
          setActiveTool("navigation");
          plan.close();
        } catch (err) {
          // eslint-disable-next-line no-console
          console.warn("[IfcViewer] close level plan on version swap:", err);
        }
      }
      loadedModelsListenersRef.current.forEach((cb) =>
        cb(loadedModelIdsRef.current.size),
      );
    };

    // Wave 60: read the frag bytes WHILE the viewer boots. On a cold
    // mount the renderer / worker setup takes 1.3–2 s before the load
    // pass may start (measured); the IndexedDB reads do not depend on
    // it, so they overlap. Only before `isReady` — afterwards the load
    // pass reads immediately itself.
    useEffect(() => {
      if (isReady) return;
      const wanted = new Set<string>();
      for (const { file, latestVersion } of files) {
        const key = latestVersion?.fragBlobKey;
        if (!key) continue;
        wanted.add(key);
        if (loadedVersionRef.current.get(file.id) === key) continue;
        if (fragPrefetchRef.current.has(key)) continue;
        const p = readFragBuffer(key, file.name);
        // Errors surface where the load pass awaits it.
        p.catch(() => undefined);
        fragPrefetchRef.current.set(key, p);
      }
      for (const key of Array.from(fragPrefetchRef.current.keys())) {
        if (!wanted.has(key)) fragPrefetchRef.current.delete(key);
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [files, isReady]);
    useEffect(() => {
      const prefetched = fragPrefetchRef.current;
      return () => prefetched.clear();
    }, []);

    // Reactive effect that mirrors the live Dexie query into the
    // FragmentsModels instance. Runs whenever the file list changes
    // (file added, version promoted to latest, file deleted, etc).
    useEffect(() => {
      if (!isReady) return;
      const fragments = fragmentsRef.current;
      if (!fragments) return;
      // Wave 63: Dexie's `useLiveQuery` returns the PREVIOUS query's
      // result for one render after `activeBuildingId` changes. Without
      // this filter that render reloaded the OLD building's models under
      // the new building (and could even take their coordinate base).
      const buildingFiles = files.filter(
        (f) => f.file.buildingId === activeBuildingId,
      );

      // If the active building changed, drop the previous building's
      // models from the viewer before loading the new ones.
      const previousBuilding = loadedBuildingRef.current;
      if (
        activeBuildingId !== null &&
        previousBuilding !== null &&
        previousBuilding !== activeBuildingId
      ) {
        // Close any open level plan from the old building.
        if (levelPlanRef.current) levelPlanRef.current.close();
        reopenStoreyAfterSwapRef.current = null;

        // Wave 31b: the disposes are AWAITED by the load IIFE below
        // (see `pendingDisposes`). Fire-and-forget here was a real bug:
        // the new building's `core.load()` raced the old building's
        // `disposeModel()` inside the same saturated worker, so both
        // models stayed in `models.list` for a long time. The GPU id
        // pass renders EVERY registered model, so a click could select
        // geometry from the building the user had already left, and
        // every pick paid for two scenes.
        const pendingDisposes: Array<Promise<unknown>> = [];
        for (const modelId of Array.from(loadedModelIdsRef.current)) {
          // Wave 18 U2/U7: the per-model ring buffer dies with the
          // model (§9 risk 3 — no buffer leak across switches).
          closeViewerModelBuffer(modelId);
          hiddenTrackerRef.current.clear(modelId);
          pendingDisposes.push(
            fragments.core.disposeModel(modelId).catch((err: unknown) => {
              // eslint-disable-next-line no-console
              console.warn(
                "[IfcViewer] disposeModel on building switch:",
                err,
              );
            }),
          );
        }
        loadedModelIdsRef.current.clear();
        loadedVersionRef.current.clear();
        // Wave 67: the measurements belonged to the building being left.
        clearMeasurementsOnUnload();
        pendingDisposesRef.current = pendingDisposes;
        loadedModelsListenersRef.current.forEach((cb) => cb(0));
        // Wave 63: the old building's load error is not this one's.
        setLoadError(null);
      }

      loadedBuildingRef.current = activeBuildingId;

      // If the building is null (no tab selected) we just leave the
      // viewer empty.
      if (activeBuildingId === null) {
        if (levelPlanRef.current) levelPlanRef.current.close();
        viewerSliceRef.current?.setActiveStoreyName(null);
        setIsStreaming(false);
        streamingArmedRef.current = false;
        setLoadError(null);
        return;
      }

      // Load the latest version of every file that's not yet in the
      // viewer.
      let cancelled = false;
      // Wave 33: the load loop resumes after async engine calls (load,
      // update, setLodMode). A superseded mount (StrictMode re-mount) or a
      // disposed view must not re-push against a dead fragments instance.
      // Same discipline as the mount effect's `stale()`: disposed, or a
      // newer mount generation has taken over this component.
      const mountGen = mountGenRef.current;
      const mountStale = (): boolean =>
        disposedRef.current || mountGenRef.current !== mountGen;
      (async () => {
        // Wave 34: the gate must cover the ENTIRE load+warm window, not
        // just the post-loop drain. Wave 33 armed it only after the
        // sequential loop finished, so the overlay lifted at the first
        // model while the worker was still saturated by the rest —
        // measured on Demo Tower (3 models): overlay lifted t=3.4 s,
        // pickAt latency 1.5–10.3 s until t≈69 s, then 57–104 ms. Arm
        // NOW when any file needs a fresh load; the post-loop drain
        // lifts it. Version-swap-only passes do not arm (the user is
        // already looking at this building; swaps keep current
        // no-overlay behavior).
        const freshTotal = buildingFiles.filter(
          ({ file, latestVersion }) =>
            latestVersion && !loadedModelIdsRef.current.has(file.id),
        ).length;
        // Wave 63: capture whether an EARLIER (now cancelled) pass left
        // the gate armed BEFORE re-arming. A Dexie re-emission mid-load
        // used to overwrite the ref with `freshTotal > 0` (false once
        // the first pass had registered its models), so the gate check
        // below never ran and the overlay lifted before the view drew.
        const wasArmed = streamingArmedRef.current;
        const armed = freshTotal > 0 || wasArmed;
        setIsStreaming(armed);
        streamingArmedRef.current = armed;
        if (freshTotal > 0) loadStreamingRef.current = true;
        setLoadProgress((p) =>
          freshTotal > 0 ? { done: 0, total: freshTotal } : armed ? p : null,
        );
        // Wave 63: a new pass starts clean — a previous pass's (or
        // building's) load error must not stay on screen forever.
        setLoadError(null);
        // Wave 31b: let the previous building's models actually leave the
        // registry before loading this building's, so the pick pass never
        // renders two scenes. Bounded: a wedged dispose must not block the
        // viewer forever, so this waits at most PICK_STALL_BUDGET_MS.
        if (pendingDisposesRef.current.length > 0) {
          await Promise.race([
            Promise.allSettled(pendingDisposesRef.current),
            new Promise((resolve) =>
              setTimeout(resolve, PICK_STALL_BUDGET_MS),
            ),
          ]);
          pendingDisposesRef.current = [];
          if (cancelled) return;
        }
        // Wave 60 — PARALLEL load pipeline. Measured (perf harness
        // --load-only, heavy scenario): the old sequential loop awaited,
        // per model, blob read → core.load → a FORCED `core.update(true)`
        // before even reading the next blob. The forced update resolves
        // only when the worker has streamed EVERY tile in view, so it
        // cost 4–5 s on MECHANICAL and 43–47 s on ARCHITECTURAL while the
        // model had been visible since ~0.7 s after its parse — the
        // overlay sat over a finished picture for most of the minute.
        // Now every model runs its own task concurrently:
        //   blob read + arrayBuffer (in parallel; IDB / disk bound) →
        //   core.load dispatched in FILE ORDER (deterministic
        //   `models.list` order; the engine spreads models over its
        //   worker pool, so parses overlap) → coordinate alignment
        //   against the first file (see below) → add to scene → an
        //   UNAWAITED forced update (kicks the first tile pass, never
        //   blocks the pass).
        // Wave 63: one renderer resize per pass (was a window `resize`
        // event per model, which also woke every app-level listener).
        let resizedThisPass = false;
        const loadOne = async (
          file: IfcFileListItem["file"],
          latestVersion: NonNullable<IfcFileListItem["latestVersion"]>,
          versionKey: string,
          index: number,
          myTurn: Promise<void>,
          markDispatched: () => void,
          settleCoords: (c: Coords3 | null) => void,
        ): Promise<void> => {
          if (!fragments) return;
          // Same file id, different version bytes - the replace case.
          const isVersionSwap = loadedModelIdsRef.current.has(file.id);
          if (isVersionSwap) {
            tel.breadcrumb("model", "version-swap", {
              file: file.name,
              from: loadedVersionRef.current.get(file.id) ?? "?",
              to: versionKey,
            });
            await dropLoadedModelForSwap(fragments, file.id);
            if (cancelled) return;
          }

          try {
            const loadStart = Date.now();
            tel.breadcrumb("model", "load-start", { file: file.name });
            const buffer = await takeFragBuffer(latestVersion.fragBlobKey, file.name);
            if (!buffer) return;
            if (cancelled) return;
            tel.breadcrumb("model", "load-buffer", { file: file.name });
            await myTurn;
            if (cancelled) return;
            const world = worldRef.current;
            if (!world) return;
            // Size BEFORE core.load transfers (detaches) the buffer.
            modelBytesRef.current.set(file.id, buffer.byteLength);
            const splitCfg = splitTileBuildRef.current;
            const cacheCfg = resolveTileCache(tileCacheRef.current, {
              fileId: file.id,
              versionKey: latestVersion.fragBlobKey || latestVersion.id,
            });
            const loadP = fragments.core.load(buffer, {
              modelId: file.id,
              camera: world.camera.three as unknown as PerspectiveCamera,
              raw: true,
              // Wave 62: helper workers build this model's tiles too
              // when it is big, and built tiles are cached in IndexedDB
              // (the engine checks the sizes). Not in the engine's
              // typings — they are FreeField patch options.
              ...(splitCfg || cacheCfg
                ? {
                    virtualModelConfig: {
                      ...(splitCfg ? { splitTileBuild: splitCfg } : {}),
                      ...(cacheCfg ? { tileCache: cacheCfg } : {}),
                    } as unknown as NonNullable<
                      Parameters<typeof fragments.core.load>[1]
                    >["virtualModelConfig"],
                  }
                : {}),
            });
            markDispatched();
            const model = await loadP;
            tel.breadcrumb("model", "load-parsed", { file: file.name });
            // Superseded by a building switch while parsing: this model
            // belongs to the building the user left — drop it instead of
            // registering it under the new one.
            if (
              cancelled &&
              (disposedRef.current ||
                loadedBuildingRef.current !== activeBuildingId)
            ) {
              await fragments.core.disposeModel(file.id).catch(() => undefined);
              return;
            }
            // Coordinate alignment (see `resolveBase` above).
            const coords = await readModelCoordinates(model);
            settleCoords(coords);
            const base = await resolveBase(index);
            if (coords && base) {
              const pos = (model.object as unknown as {
                position?: { x: number; y: number; z: number };
              }).position;
              if (pos) {
                pos.x += base[0] - coords[0];
                pos.y += base[1] - coords[1];
                pos.z += base[2] - coords[2];
              }
            }
            // Wave 60: arm LodMode.ALL_GEOMETRY BEFORE the model's first
            // tile pass (it is not in the scene and no view has been
            // sent yet). The engine's DEFAULT mode draws small / thin
            // items as one-pixel "wire" stand-ins; ALL_GEOMETRY keeps
            // DEFAULT's frustum + screen-size culling but draws real
            // geometry. Waves 38–59 armed it in the background AFTER the
            // overlay lifted, which restarted the whole tile pass right
            // when the user started clicking: measured on the heavy
            // scene, worker raycasts then timed out (>1.5 s) for ~10 s.
            // Armed first, there is ONE pass at the final quality
            // (primary scene: same time-to-idle, measured). Not awaited:
            // the RPC is ordered ahead of the view refresh below on the
            // model's worker port. Called as a method (live
            // FragmentsModel needs `this`).
            const lodStart = Date.now();
            // Called synchronously (the RPC must be posted BEFORE the
            // view refresh below); guarded so an engine / test double
            // without the method only loses the quality upgrade instead
            // of failing the whole load.
            const onLodFail = (err: unknown): void => {
              // eslint-disable-next-line no-console
              console.warn("[IfcViewer] LOD arm failed:", err);
              tel.breadcrumb("model", "lod-mode-fail", {
                file: file.name,
                message: err instanceof Error ? err.message : String(err),
              });
            };
            try {
              model
                .setLodMode(
                  memoryTuningRef.current?.lodMode === "default"
                    ? LodMode.DEFAULT
                    : LodMode.ALL_GEOMETRY,
                )
                .then(
                () =>
                  tel.breadcrumb("model", "lod-armed", {
                    file: file.name,
                    elapsedMs: Date.now() - lodStart,
                  }),
                onLodFail,
              );
            } catch (err) {
              onLodFail(err);
            }
            world.scene.three.add(model.object);
            loadedModelIdsRef.current.add(file.id);
            loadedVersionRef.current.set(file.id, versionKey);
            loadedModelsListenersRef.current.forEach((cb) =>
              cb(loadedModelIdsRef.current.size),
            );
            // The demo default pose is for a FRESH first model. On a
            // version swap the user was already looking at this
            // building's geometry, roughly at the same coordinates, so
            // jumping the camera to (15,15,15) would read as a glitch.
            if (
              !isVersionSwap &&
              loadedModelIdsRef.current.size === 1 &&
              !fitOnFirstLoadRef.current &&
              world.camera.controls
            ) {
              world.camera.controls.setLookAt(15, 15, 15, 0, 0, 0);
            }
            // Wave 60: kick the first tile pass but do NOT await it. A
            // forced update resolves only after the worker has streamed
            // every tile in view (tens of seconds on a big model); the
            // first tiles land ~0.5 s after the parse regardless. The
            // settle check below decides when the overlay lifts.
            fragments.core.update(true).catch(() => undefined);
            requestRender("model-load");
            if (cancelled || mountStale()) return;
            tel.breadcrumb("model", "load-complete", { file: file.name, durationMs: Date.now() - loadStart });
            // Wave 34: advance the overlay progress counter for fresh
            // loads (swaps never armed the gate, so never count).
            if (!isVersionSwap) {
              setLoadProgress((p) =>
                p ? { ...p, done: Math.min(p.done + 1, p.total) } : p,
              );
            }
            // Wave 18 U2/U7: per-model renderer ring buffer
            // (RendererDiagnostics.ReportList semantics), keyed by the
            // TOE modelId used above. Closed on every dispose path.
            openViewerModelBuffer(file.id);
            if (!resizedThisPass) {
              resizedThisPass = true;
              try {
                (world.renderer as { resize?: () => void } | null)?.resize?.();
              } catch {
                // renderer mid-dispose; the next pass resizes
              }
            }
          } catch (err) {
            // eslint-disable-next-line no-console
            console.error("[IfcViewer] failed to load", file.name, err);
            tel.breadcrumb("model", "load-fail", { file: file.name, message: err instanceof Error ? err.message : String(err) });
            if (err instanceof Error) setLoadError(err);
          }
        };

        const tasks: Array<Promise<void>> = [];
        // Dispatch chain: task i calls core.load only after task i-1
        // has called it (or skipped), so `models.list` insertion order —
        // which OBC's FragmentsManager uses for its base coordination
        // model — stays the file order regardless of which blob read
        // finishes first.
        let prevDispatched: Promise<void> = Promise.resolve();
        // Coordinate alignment (replaces the engine's `autoCoordinate`,
        // switched off at init): the engine aligns every model to
        // whichever model resolved `getCoordinates()` FIRST — with
        // parallel parses that would be a race, and saved viewpoints /
        // calibrations live in that world frame. The base stays what it
        // was under the sequential loop: the current base if models are
        // already loaded, else the first file (in list order) that loads.
        const coordSlots: Array<Promise<Coords3 | null>> = [];
        const resolveBase = async (upTo: number): Promise<Coords3 | null> => {
          const core = fragments.core as unknown as CoordinatedCore;
          if (core.baseCoordinates) return core.baseCoordinates;
          for (let j = 0; j <= upTo; j++) {
            const c = await coordSlots[j];
            if (core.baseCoordinates) return core.baseCoordinates;
            if (c) {
              setBaseCoordinates(core, c); // no-op on a disposed viewer's frozen core
              return c;
            }
          }
          return null;
        };
        for (const { file, latestVersion } of buildingFiles) {
          if (!latestVersion) continue; // no version at all yet
          const versionKey =
            latestVersion.fragBlobKey ?? String(latestVersion.id ?? "");
          const index = coordSlots.length;
          let settleCoords!: (c: Coords3 | null) => void;
          coordSlots.push(
            new Promise<Coords3 | null>((r) => {
              settleCoords = r;
            }),
          );
          let markDispatched!: () => void;
          const dispatched = new Promise<void>((r) => {
            markDispatched = r;
          });
          const myTurn = prevDispatched;
          prevDispatched = dispatched;
          tasks.push(
            (async () => {
              try {
                // A load of this file still in flight from a superseded
                // pass (live-query re-emission): wait for it instead of
                // starting a duplicate `core.load` under the same id.
                const inflight = inflightLoadsRef.current.get(file.id);
                if (inflight) await inflight.done;
                if (cancelled) return;
                if (
                  loadedModelIdsRef.current.has(file.id) &&
                  loadedVersionRef.current.get(file.id) === versionKey
                ) {
                  return; // same file AND same version: nothing to do
                }
                let finishInflight!: () => void;
                const done = new Promise<void>((r) => {
                  finishInflight = r;
                });
                inflightLoadsRef.current.set(file.id, { versionKey, done });
                try {
                  await loadOne(file, latestVersion, versionKey, index, myTurn, markDispatched, settleCoords);
                } finally {
                  if (inflightLoadsRef.current.get(file.id)?.done === done) {
                    inflightLoadsRef.current.delete(file.id);
                  }
                  finishInflight();
                }
              } finally {
                // Never leave a later task waiting on this one.
                markDispatched();
                settleCoords(null);
              }
            })(),
          );
        }

        await Promise.allSettled(tasks);
        // If files were removed from the building (deleteIfc was
        // called) but they're still in our ref, dispose the stale
        // models.
        //
        // Bug-hunt 2026-06-19: guard with `cancelled`. When this
        // effect re-fires (e.g. because a new `files` array reference
        // arrived from useLiveQuery), the OLD IIFE continues here
        // with stale `files` in its closure. Without the guard, a
        // stale `files=[]` (e.g. transient emission during Dexie
        // re-subscription) would dispose every model in
        // `loadedModelIdsRef.current` — including ones just loaded
        // by a NEWER IIFE.
        //
        // 2026-06-23: removed setModelCount (it was used only by the
        // now-deleted debug overlay). This also removes one of the
        // re-render triggers the guard above was protecting against,
        // which is a small bonus — fewer re-renders means fewer
        // chance of stale-closure races.
        if (cancelled) return;
        // Wave 73: opt-in fit-to-bounds after the FIRST load of this mount.
        if (
          fitOnFirstLoadRef.current &&
          !firstFitDoneRef.current &&
          loadedModelIdsRef.current.size > 0
        ) {
          void (async () => {
            // Model boxes can lag the load by a few frames; retry briefly.
            for (let i = 0; i < 16; i++) {
              if (cancelled || mountStale() || firstFitDoneRef.current) return;
              if (cameraMovedByHostRef.current) {
                firstFitDoneRef.current = true; // the host / user placed it
                return;
              }
              if (hasFiniteModelBounds()) {
                firstFitDoneRef.current = true;
                handleSelfRef.current?.resetCameraToDefault();
                return;
              }
              await new Promise((r) => setTimeout(r, 250));
            }
          })();
        }
        const liveIds = new Set(buildingFiles.map((f) => f.file.id));
        for (const stale of Array.from(loadedModelIdsRef.current)) {
          if (!liveIds.has(stale)) {
            closeViewerModelBuffer(stale); // Wave 18 U2/U7
            hiddenTrackerRef.current.clear(stale);
            try {
              await fragments.core.disposeModel(stale);
            } catch (err) {
              // eslint-disable-next-line no-console
              console.warn("[IfcViewer] disposeModel stale:", err);
            }
            loadedModelIdsRef.current.delete(stale);
            loadedVersionRef.current.delete(stale);
            clearMeasurementsOnUnload();
          }
        }
        // Notify listeners if any models were disposed.
        loadedModelsListenersRef.current.forEach((cb) =>
          cb(loadedModelIdsRef.current.size),
        );

        // Load gate (waves 38 / 60).
        //   Phase 1 (blocks the overlay, fresh loads only): lift as soon
        //   as every loaded model DRAWS (has tiles) AND a probe pick (the
        //   same worker raycast a click runs) comes back in budget
        //   GATE_PROBE_STREAK times in a row — i.e. the scene is visible
        //   and clickable. Fallbacks: ~500 ms with no busy model, or 12 s
        //   when some model never reports tiles (out of view); hard cap
        //   GATE_RESPONSIVE_CAP_MS. The rest of the view keeps streaming
        //   in behind the open viewer.
        //   Phase 2 (background, no UI): one unforced update. The
        //   ALL_GEOMETRY LOD arm (real geometry for small / thin items
        //   instead of DEFAULT's one-pixel wire stand-ins, still frustum
        //   + screen-size culled) moved to load time in wave 60 — see
        //   loadOne. Telemetry-only — never touches overlay state.
        if (!cancelled && loadedModelIdsRef.current.size > 0) {
          const passStart = Date.now();
          void (async () => {
            const sampleBusy = (): boolean => {
              const frags = fragmentsRef.current;
              if (!frags) return false;
              for (const [, m] of frags.core.models.list) {
                if (m.isBusy) return true;
              }
              return false;
            };
            // A model this big still streaming its view makes click
            // raycasts unreliable even while probe rays come back fast
            // (measured, 85 MB ARCHITECTURAL: probes ≤0.5 s, clicks >1.5 s
            // for ~30 s), so it holds the gate until it is idle.
            const bigModelStreaming = (): boolean => {
              const frags = fragmentsRef.current;
              if (!frags) return false;
              for (const id of loadedModelIdsRef.current) {
                if ((modelBytesRef.current.get(id) ?? 0) < GATE_BIG_MODEL_BYTES) {
                  continue;
                }
                const m = frags.core.models.list.get(id);
                if (m && m.isBusy) return true;
              }
              return false;
            };
            const everyModelDrawing = (): boolean => {
              const frags = fragmentsRef.current;
              if (!frags || loadedModelIdsRef.current.size === 0) return false;
              for (const id of loadedModelIdsRef.current) {
                const m = frags.core.models.list.get(id) as
                  | { tiles?: { size?: number } }
                  | undefined;
                if (!m || !m.tiles || !(Number(m.tiles.size) > 0)) {
                  return false;
                }
              }
              return true;
            };
            // Wave 60: is every model's worker answering promptly? A
            // pick is a worker raycast; while a worker streams a big
            // model's first view a raycast through it can take seconds
            // (measured: ARCHITECTURAL, 85 MB frag — clicks in that
            // window timed out or fell back to the id pass). One probe
            // pick at a time — never more than one in flight, so a
            // lagging worker is not flooded — and its round trip decides.
            let probe: { start: number; rtt: number | null } | null = null;
            let lastProbeRtt: number | null = null;
            // Consecutive in-budget probes. One fast answer is not
            // enough: while a big model streams, raycast latency swings
            // between ~0.3 s and >1.5 s from one click to the next.
            let probeStreak = 0;
            let probeCount = 0;
            const workersResponsive = (): boolean => {
              const frags = fragmentsRef.current;
              if (!frags) return true;
              if (probe && probe.rtt === null) return false; // still out
              if (probe && probe.rtt !== null) {
                lastProbeRtt = probe.rtt;
                probeStreak =
                  probe.rtt <= GATE_PROBE_BUDGET_MS ? probeStreak + 1 : 0;
                probe = null;
                if (probeStreak >= GATE_PROBE_STREAK) return true;
              }
              const calls: Array<Promise<unknown>> = [];
              // The probe IS a pick: the same `fragments.raycast` a click
              // runs (every model, through GATE_PROBE_POINTS). A cheap
              // RPC is not enough — measured: `getCoordinates` answered
              // in ~110 ms while a raycast through a still-streaming big
              // model took >2 s, so clicks timed out after the lift.
              const canvasEl = worldRef.current?.renderer?.three
                ?.domElement as HTMLCanvasElement | undefined;
              const cam = worldRef.current?.camera?.three;
              const caster = frags as unknown as Partial<WorkerRaycaster>;
              if (
                raycastAvailableRef.current &&
                typeof caster.raycast === "function" &&
                canvasEl &&
                cam
              ) {
                // Rotate the probe ray over GATE_PROBE_POINTS: raycast cost
                // depends on what the ray crosses (dense MEP runs cost
                // more than open floor), so a streak must cover them all.
                const r = canvasEl.getBoundingClientRect();
                const [fx, fy] =
                  GATE_PROBE_POINTS[probeCount % GATE_PROBE_POINTS.length]!;
                probeCount += 1;
                calls.push(
                  caster.raycast({
                    camera: cam,
                    dom: canvasEl,
                    mouse: new THREE.Vector2(
                      r.left + r.width * fx,
                      r.top + r.height * fy,
                    ),
                  }),
                );
              } else {
                for (const id of loadedModelIdsRef.current) {
                  const m = frags.core.models.list.get(id) as
                    | { getCoordinates?: () => Promise<unknown> }
                    | undefined;
                  if (m && typeof m.getCoordinates === "function") {
                    calls.push(m.getCoordinates());
                  }
                }
              }
              if (calls.length === 0) return true; // nothing to ask
              const p = { start: Date.now(), rtt: null as number | null };
              probe = p;
              void Promise.allSettled(calls).then(() => {
                p.rtt = Date.now() - p.start;
              });
              return false;
            };
            let bigCapped = false;
            const gateRan = freshTotal > 0 || wasArmed;
            if (gateRan) {
              try {
                const gateStart = Date.now();
                const liftDeadline = gateStart + GATE_RESPONSIVE_CAP_MS;
                const quietDeadline = gateStart + 12_000;
                let quiet = 0;
                while (
                  !cancelled &&
                  !mountStale() &&
                  Date.now() < liftDeadline
                ) {
                  // Wave 60: lift as soon as every loaded model DRAWS
                  // (has tiles in the scene) and every worker answers
                  // within the probe budget — the rest of the view keeps
                  // streaming in behind a usable, clickable viewer
                  // instead of behind the curtain (the old pass waited
                  // for a forced full flush: ~45 s on a big model).
                  // Wave 61: a big model still streaming holds the gate
                  // for at most GATE_BIG_MODEL_WAIT_CAP_MS; after that
                  // only the probe picks (real worker raycasts through
                  // every model, 5 in a row in budget) decide.
                  const bigHolds =
                    bigModelStreaming() &&
                    Date.now() - gateStart < GATE_BIG_MODEL_WAIT_CAP_MS;
                  bigCapped = !bigHolds && bigModelStreaming();
                  if (bigHolds) probeStreak = 0;
                  else if (everyModelDrawing() && workersResponsive()) break;
                  // Quiet: ~500 ms without a busy model (5 × 100 ms
                  // samples; was 2 × 250 ms). Kept for models that
                  // never report tiles (out of view): those lift at 12 s
                  // unless a big model is still streaming.
                  if (sampleBusy()) quiet = 0;
                  else {
                    quiet += 1;
                    if (quiet >= 5) break;
                  }
                  if (
                    Date.now() >= quietDeadline &&
                    !everyModelDrawing() &&
                    !bigHolds
                  ) {
                    break;
                  }
                  await new Promise((r) => setTimeout(r, 100));
                }
              } finally {
                if (!cancelled) {
                  setIsStreaming(false);
                  streamingArmedRef.current = false;
                  setLoadProgress(null);
                  tel.breadcrumb("model", "gate-lift", {
                    elapsedMs: Date.now() - passStart,
                    probeRttMs: lastProbeRtt,
                    bigCapped,
                  });
                }
              }
            }
            // Wave 61: the view is still filling in after the lift (e.g.
            // the big-model wait was capped) — a small non-blocking chip
            // stays up until every model is idle. Watched off the main
            // gate chain so Phase 2 below is not delayed.
            if (!gateRan || cancelled || mountStale() || !sampleBusy()) {
              if (!cancelled) loadStreamingRef.current = false;
            } else {
              setBackgroundStreaming(true);
              const chipGen = ++chipGenRef.current;
              void (async () => {
                const chipDeadline =
                  Date.now() + BACKGROUND_STREAM_CHIP_CAP_MS;
                let idleSamples = 0;
                while (
                  !cancelled &&
                  !mountStale() &&
                  Date.now() < chipDeadline &&
                  idleSamples < 2
                ) {
                  await new Promise((r) => setTimeout(r, 250));
                  idleSamples = sampleBusy() ? 0 : idleSamples + 1;
                }
                if (chipGenRef.current === chipGen) {
                  setBackgroundStreaming(false);
                  loadStreamingRef.current = false;
                }
                if (idleSamples >= 2) {
                  tel.breadcrumb("model", "stream-complete", {
                    elapsedMs: Date.now() - passStart,
                  });
                }
              })();
            }
            // Phase 2 (wave 60): the LOD arm now happens per model at
            // load time (see loadOne); one unforced update lets the
            // engine's apply loop run after the reveal.
            if (cancelled || mountStale()) return;
            try {
              await fragmentsRef.current?.core.update();
            } catch {
              // best-effort; the engine's own update loop retries
            }
            tel.breadcrumb("model", "lod-settle", {
              elapsedMs: Date.now() - passStart,
            });
          })().catch(() => {
            if (!cancelled) {
              setIsStreaming(false);
              streamingArmedRef.current = false;
              loadStreamingRef.current = false;
              setLoadProgress(null);
            }
          });
        } else if (!cancelled) {
          // Wave 34: nothing loaded this pass (all files skipped, every
          // load failed, or no models registered) — lift the pass-start
          // gate so a failed load can never pin the loader forever.
          setIsStreaming(false);
          streamingArmedRef.current = false;
          loadStreamingRef.current = false;
          setLoadProgress(null);
        }

        // Task 16: feed storey metadata to the LevelPlanController
        // from the pipeline's storey extraction (replaces OBC.Views'
        // createFromIfcStoreys which read storeys from .frag).
        //
        // Bug-hunt 2026-06-19: guard with `cancelled` before the
        // storey fetch. Same race as the stale-cleanup guard above.
        if (cancelled) return;
        if (loadedModelIdsRef.current.size > 0 && levelPlanRef.current) {
          try {
            const storeys = await getStoreysForBuilding(activeBuildingId);
            const ctrl = levelPlanRef.current as LevelPlanHandle & {
              _setStoreys: (
                s: { name: string; elevation: number; height: number | null }[],
              ) => void;
            };
            ctrl._setStoreys(storeys);
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn("[IfcViewer] getStoreysForBuilding failed:", err);
          }
        }
        // Wave 63: a version swap closed an open level plan — re-open
        // the same storey against the new geometry.
        const reopen = reopenStoreyAfterSwapRef.current;
        if (reopen !== null && !cancelled && !mountStale() && levelPlanRef.current) {
          reopenStoreyAfterSwapRef.current = null;
          const ok = await levelPlanRef.current.open(reopen);
          if (cancelled || mountStale()) return;
          if (ok) {
            if (containerRef.current) setActiveTool("measure");
          } else {
            viewerSliceRef.current?.setActiveStoreyName(null);
          }
        }
      })();

      return () => {
        cancelled = true;
      };
    }, [files, activeBuildingId, isReady]);


    // ---------- tool switching (Task 18) ----------
    //
    // The "measure" tool arms the measurement state machine
    // (MeasurementLineSystem from LevelPlanController). The
    // "navigation" tool restores orbit nav and the default cursor.
    // Defined as a regular function (not a useCallback) — it's
    // referenced from the imperative handle (which captures refs
    // at call time, not at mount) and from `openLevel` /
    // `closeLevel` closures, both of which read refs the same way.
    //
    // Implementation note: we never call setActiveTool from inside
    // a useEffect — the openLevel path is a user action
    // (clicking a storey in the sidebar), so it's fine to update
    // state in a click handler. Calling setActiveTool from a
    // useEffect would force a second render on every level open.
    function setActiveTool(tool: "navigation" | "measure"): void {
      const container = containerRef.current;
      if (!container) return;

      // Tear down any previous measure wiring before installing
      // new state. This is the key invariant: there's exactly one
      // set of click/mousemove/keydown listeners on the container
      // at any time. Without this, calling setActiveTool twice
      // would stack two listeners and double-fire every event.
      if (measureCleanupRef.current) {
        measureCleanupRef.current();
        measureCleanupRef.current = null;
      }

      const world = worldRef.current;
      // Get a typed handle on the world camera. We use the
      // camera's `controls` for the orbit nav (OBC wraps
      // camera-controls; setting `enabled = false` is the
      // documented way to freeze it for an in-place interaction
      // like our click-to-place tool).
      // We use the camera-controls instance properties to keep all
      // navigation enabled EXCEPT left-click orbit, which we zero
      // out so clicks pass through to our measurement handler.
      // Camera-controls explicitly does NOT call preventDefault()
      // on pointerdown (line 697 in its module), so clicks bubble
      // through when mouseButtons.left === NONE(0).
      const ctl = world?.camera?.controls as unknown as {
        enabled: boolean;
        mouseButtons: { left: number; middle: number; right: number; wheel: number };
      } | undefined;

      if (tool === "navigation") {
        // Restore default cursor + re-enable left-click orbit.
        container.style.cursor = "";
        if (ctl) {
          ctl.mouseButtons.left = 1; // ROTATE
          ctl.enabled = true;
        }
        activeToolRef.current = "navigation";
        return;
      }

      // tool === "measure"
      const ctrl = levelPlanRef.current;
      if (!ctrl) return;

      // Crosshair cursor is the standard "click to place" affordance.
      container.style.cursor = "crosshair";

      // Disable ONLY left-click orbit (ACTION.ROTATE = 1 → 0 = NONE).
      // Wheel zoom (ACTION.ZOOM = 4), middle-button dolly (ACTION.DOLLY = 3),
      // and right-button truck/pan (ACTION.TRUCK = 2) all stay enabled.
      if (ctl) {
        ctl.mouseButtons.left = 0;   // NONE — freed for our click handler
        // middle/wheel/right remain at defaults (DOLLY/ZOOM/TRUCK)
      }

      // ── Drawing-plane intersection helper ────────────────────────
      // Used for MOUSE_MOVE events: the cursor follows the mouse
      // smoothly on the drawing's plane (Y=0 in drawing-local
      // space), even when no projection line is under the cursor.
      // The pattern is from the TOE AnnotationSystems tutorial:
      // intersect the world ray with the drawing's Y=0 plane
      // (transformed by drawing.three.matrixWorld), then convert
      // the hit to drawing-local space.
      // ── Drawing-plane NDC helper (shared by click + mousemove) ────
      const getNDC = (ev: MouseEvent): THREE.Vector2 => {
        const rect = container.getBoundingClientRect();
        return new THREE.Vector2(
          ((ev.clientX - rect.left) / rect.width) * 2 - 1,
          -(((ev.clientY - rect.top) / rect.height) * 2 - 1),
        );
      };

      // Reusable raycaster — sourced from OBC.Raycasters (the engine's
      // fragment-aware service). `OBC.Raycasters.get(world)` returns a
      // `SimpleRaycaster` bound to the world; the underlying THREE.Raycaster
      // is exposed as `SimpleRaycaster.three` (readonly). All cast helpers
      // (`setFromCamera`, `.ray.intersectPlane`, drawing.raycast) must go
      // through `.three` — `SimpleRaycaster` itself does NOT have
      // `setFromCamera`. Kept outside the handlers so we allocate once per
      // tool activation, not per frame.
      const raycaster = world
        ? componentsRef.current?.get(OBC.Raycasters).get(world) ?? null
        : null;
      if (!raycaster) return; // safety: no components yet

      const onClick = (ev: MouseEvent): void => {
        const drawing = ctrl.getDrawing();
        if (!drawing) return;
        const cam = world?.camera?.three;
        if (!cam) return;
        raycaster.three.setFromCamera(getNDC(ev), cam);
        const hit = drawing.raycast(raycaster.three.ray);
        const measureSystem = ctrl.getMeasureSystem();
        if (hit) {
          measureSystem.sendMachineEvent({
            type: "CLICK",
            point: hit.point as unknown as { x: number; y: number; z: number },
            line: hit.line as unknown as {
              start: { x: number; y: number; z: number };
              end: { x: number; y: number; z: number };
            } | null,
            drawing,
          });
        } else {
          // No hit — the state machine ignores CLICK-without-line.
          // Still send a MOUSE_MOVE so the preview dot tracks the cursor.
          const mPoint = raycaster.three.ray.intersectPlane(
            new THREE.Plane().setFromNormalAndCoplanarPoint(
              new THREE.Vector3(0, 1, 0).transformDirection(drawing.three.matrixWorld),
              new THREE.Vector3().setFromMatrixPosition(drawing.three.matrixWorld),
            ),
            new THREE.Vector3(),
          );
          if (mPoint) {
            const local = drawing.three.worldToLocal(mPoint.clone());
            local.y = 0;
            measureSystem.sendMachineEvent({
              type: "MOUSE_MOVE",
              point: local as unknown as { x: number; y: number; z: number },
              drawing,
            });
          }
        }
      };

      const onMouseMove = (ev: MouseEvent): void => {
        const drawing = ctrl.getDrawing();
        if (!drawing) return;
        const cam = world?.camera?.three;
        if (!cam) return;
        raycaster.three.setFromCamera(getNDC(ev), cam);
        // Intersect with the drawing's Y=0 plane (world-space)
        const mPoint = raycaster.three.ray.intersectPlane(
          new THREE.Plane().setFromNormalAndCoplanarPoint(
            new THREE.Vector3(0, 1, 0).transformDirection(drawing.three.matrixWorld),
            new THREE.Vector3().setFromMatrixPosition(drawing.three.matrixWorld),
          ),
          new THREE.Vector3(),
        );
        if (!mPoint) return;
        // Convert to drawing-local (XZ plane, Y=0)
        const local = drawing.three.worldToLocal(mPoint.clone());
        local.y = 0;
        const measureSystem = ctrl.getMeasureSystem();
        measureSystem.sendMachineEvent({
          type: "MOUSE_MOVE",
          point: local as unknown as { x: number; y: number; z: number },
          drawing,
        });
      };

      const onKeyDown = (ev: KeyboardEvent): void => {
        if (ev.key === "Escape") {
          ev.preventDefault();
          const measureSystem = ctrl.getMeasureSystem();
          const drawing = ctrl.getDrawing();
          measureSystem.sendMachineEvent({
            type: "ESCAPE",
            drawing: drawing ?? undefined,
          });
        }
      };

      container.addEventListener("click", onClick);
      container.addEventListener("pointermove", onMouseMove);
      // Tell the browser not to interpret touch gestures on the canvas
      // as scroll/zoom. Required for Capacitor Android: without this,
      // `touch-action: auto` (default) intercepts pointerdown and the
      // mapping tool never sees the first tap. OrbitControls already
      // documents this requirement for touch.
      container.style.touchAction = "none";
      window.addEventListener("keydown", onKeyDown);

      measureCleanupRef.current = () => {
        container.removeEventListener("click", onClick);
        // Wave 29 fix (was: "mousemove"): this handler is registered as
        // POINTERMOVE above, so removing "mousemove" never detached it.
        // Every Measure activation leaked one listener for the lifetime of
        // the container — each leaked copy running a forced
        // `getBoundingClientRect`, a `Vector2` allocation, a
        // `setFromCamera` raycast and an FSM `sendMachineEvent` on EVERY
        // pointer move over the canvas. N activations ⇒ N raycasts per
        // mouse move, i.e. the app measurably degrades the more the
        // measure tool is used, with no reload to explain it.
        container.removeEventListener("pointermove", onMouseMove);
        window.removeEventListener("keydown", onKeyDown);
        // `touchAction: "none"` is deliberately NOT restored: the WebGL
        // canvas needs it for orbit/pan on touch (Capacitor Android), and
        // putting it back to `auto` after a measure cycle would regress
        // touch navigation for the rest of the mount.
      };

      activeToolRef.current = "measure";
    }

    // ---------- imperative handle ----------
    // Internal helper used by setOnElementPick (when the
    // Highlighter is ready) AND by the mount IIFE (when the
    // Highlighter finishes setup after a pending subscription).
    // Lives outside useImperativeHandle so the IIFE closure can
    // call it without holding the handle ref. We bind to refs
    // (`pickCallbackRef`, `pickCleanupRef`) so the helper sees
    // the latest values without re-creating closures.

    // Wave 48: lazy, background face-normal resolution for the
    // section-plane toolbar. The worker-raycast primary path skips the
    // depth pass (its point is free), so it carries no surface normal;
    // this fire-and-forget call runs the CHEAP normal pass (`getNormalAt`,
    // ~25 ms, no id pass, no worker round-trip) AFTER the selection +
    // highlight + anchor already applied — it is NOT on the click critical
    // path. The fingerprint guard drops a stale normal the same way the
    // point stash does. A null/failed normal is handled by the toolbar's
    // bbox-face-snap → camera-direction fallback chain.
    const resolveSelectionNormal = (
      key: string,
      probeNdc: { x: number; y: number },
    ): void => {
      const picker = fastPickerRef.current;
      if (!picker || typeof picker.getNormalAt !== "function") return;
      void (async () => {
        try {
          const normal = await picker.getNormalAt!(probeNdc);
          if (disposedRef.current) return;
          if (selectionFingerprint(selectionRef.current) !== key) return;
          if (
            normal &&
            Number.isFinite(normal.x) &&
            Number.isFinite(normal.y) &&
            Number.isFinite(normal.z)
          ) {
            lastPickNormalRef.current = {
              key,
              normal: { x: normal.x, y: normal.y, z: normal.z },
            };
          }
        } catch {
          // Best-effort: getSelectionWorldNormal() returns null and the
          // toolbar falls through to the bbox-face-snap path.
        }
      })();
    };

    function installPickSubscription(
      h: NonNullable<typeof highlighterRef.current>,
      cb: ((e: ElementPickEvent | null) => void) | null,
    ): void {
      // Wave 31b: a subscription is NO LONGER the trigger for existing.
      // The canvas pick pipeline used to be installed only when some
      // consumer called `setOnElementPick(cb)` with a callback — so on
      // any route that renders the viewer without a pick subscriber (the
      // admin authoring shell, which mounts no PropertiesDrawer), the
      // canvas had NO click handler at all: clicking a model silently
      // did nothing. The pipeline is now installed at mount and this
      // function is idempotent; `cb` only decides whether the app is
      // *told* about the selection.
      if (cb) pickCallbackRef.current = cb;
      if (pickInstalledRef.current) return;
      pickInstalledRef.current = true;

      // ── Wave 19 (option A): viewer-owned click pipeline ─────────
      // When the fast GPU pick backend is live, resolve the selection
      // through `FastModelPicker.getFullPick()` directly. Its GPU id
      // pass spans EVERY registered model (core `applyIdMaterial` walks
      // `fragments.list` and assigns each model a byte), so a click on
      // model #2 returns that model's real `{ modelId, localId, point }`.
      // The Highlighter's own auto-pick is disabled in this mode
      // (`autoHighlightOnClick: false`), so nothing competes with this
      // listener; we drive the orange highlight programmatically via
      // `highlighter.highlightByID` / `clear` (the mirror handlers below
      // fold those into `selectionRef`).
      //
      // The `getFullPick` result carries a REAL world point (not the
      // zero-vector the Highlighter path emitted), and its `localId` is
      // the express id (TOE preserves express ids as `localId`).
      const fastPicker = fastPickerRef.current;
      if (pickBackendRef.current === "fast" && fastPicker) {
        const canvas = worldRef.current?.renderer?.three?.domElement as
          | HTMLElement
          | undefined;
        if (canvas) {
          const dragGuard = attachDragGuard(canvas);
          const onClick = async (ev: MouseEvent): Promise<void> => {
            if (disposedRef.current) return;
            // Wave 76: host owns picking - no pick work at all.
            if (!builtInClickPickRef.current) return;
            // Wave 23: an orbit/pan drag ending over the canvas fires
            // a `click` too — that is a camera gesture, not selection
            // intent. Skip the pick when the pointer travelled past
            // the drag threshold since the last press.
            if (dragGuard.wasDrag()) return;
            // Only suppress during an active measurement session. Cold
            // mount leaves `activeToolRef` null (the viewer treats that as
            // the default navigation surface, matching the Highlighter's
            // auto-pick which never consults `activeToolRef`). A measuring
            // click must not also tint an element (mirrors
            // `highlighter.enabled = false` in activateMeasure3D for the
            // raycaster path).
            if (activeToolRef.current === "measure") return;
            // Skip non-primary buttons — orbit/pan gestures that end in a
            // click with a non-left button must not pick. (A press-release
            // on the canvas still fires `click` button 0, matching the
            // measure tool's plain-`click` pattern.)
            if (ev.button !== 0) return;

            const rect = canvas.getBoundingClientRect();
            if (!rect || rect.width <= 0 || rect.height <= 0) return;
            const ndc: { x: number; y: number } = {
              x: ((ev.clientX - rect.left) / rect.width) * 2 - 1,
              y: -(((ev.clientY - rect.top) / rect.height) * 2 - 1),
            };
            // Wave 19b (on-device bug hunt): tolerant pick. The
            // GPU id pass reads one exact pixel; thin/angled MEP
            // surfaces can rasterize a hair off it and read void
            // ("empty space while clearly over an element"). The
            // tolerant wrapper re-probes outward in pixel rings
            // before declaring a miss. See picking/pickSeam.ts for
            // the full rationale + why the CPU raycaster is NOT a
            // viable fallback (fragments' BVH raycast throws on
            // these tiles — measured live on-device).
            // Wave 21b: single-flight entry. If a chain is already
            // running, hand this click to it as the supersede.
            const queuedClick = {
              ndc,
              size: { x: rect.width, y: rect.height },
              clickTs: performance.now(),
              // Wave 45: the client pixel, so the worker raycast's
              // `screenToCast` (which subtracts `rect.left/top`) gets the
              // same coordinate the id-pass NDC was derived from.
              clientX: ev.clientX,
              clientY: ev.clientY,
              touch: isTouchLikeClick(ev),
            };
            chainStatsRef.current.clicks += 1;
            if (pickBusyRef.current) {
              pendingClickRef.current = queuedClick;
              return;
            }

            const runChain = async (first: typeof queuedClick): Promise<void> => {
              pickBusyRef.current = true;
              try {
                let click = first;
                for (;;) {
                  const t0 = benchEnabledRef.current ? performance.now() : 0;
                  // Wave 28: remember the stall counter for this attempt so
                  // the `undefined` branch below can tell a wave-27 timeout
                  // (already counted) from a fresh UNKNOWN pick.
                  const lastPickTimeouts = chainStatsRef.current.pickTimeouts;
                  // Wave 25: render counter — capture the reader's
                  // accumulated renders before the pick so the per-click
                  // delta is exact regardless of batched vs fallback.
                  const rendersBefore = batchedIdPassRef.current
                    ? batchedIdPassRef.current.totalRenders
                    : 0;
                  // Wave 27: stall guard. debug-perf-chain telemetry
                  // from the boss's real /models scene proved a pick
                  // can NEVER settle (hung fragments round-trip in the
                  // degraded getItemAt loop) — and the single-flight
                  // chain latches every later click behind it. Past
                  // the budget the click is dropped as a no-op
                  // (selection untouched), counted, and the chain
                  // hands its latch back. A lost click is bad; a dead
                  // app is worse.
                  // Wave 45: raycast-primary backend. Try the worker
                  // virtual raycast (tile-independent, exact-triangle) FIRST
                  // — on hit/miss it is authoritative (no id-pass tolerance
                  // re-scan); on absent/throw/timeout it falls through to the
                  // id-pass below. The id-pass `withStallGuard` (wave 27)
                  // wraps the fallback exactly as before; the raycast has its
                  // OWN 1500 ms bound, so the two budgets stack and a wedged
                  // worker can never latch the chain past ~5.5 s.
                  const runIdPassGuarded = (): Promise<
                    IdPickHit | null | undefined
                  > =>
                    withStallGuard<IdPickHit | null | undefined>(
                      pickElementIdFastTolerant(
                        fastPickerRef.current,
                        click.ndc,
                        click.size,
                        batchedIdPassRef.current,
                        (err) => {
                          chainStatsRef.current.degrades += 1;
                          chainStatsRef.current.lastDegradeReason = String(
                            err instanceof Error ? err.message : err,
                          );
                        },
                      ),
                      () => {
                        chainStatsRef.current.pickTimeouts += 1;
                        // eslint-disable-next-line no-console
                        console.warn(
                          `[IfcViewer] pick stalled >${PICK_STALL_BUDGET_MS}ms — click dropped, chain released`,
                        );
                        if (benchEnabledRef.current)
                          recordPickBench(PICK_STALL_BUDGET_MS);
                      },
                      undefined,
                    );

                  // RaycastData — `{ camera, dom, mouse }` in the engine's
                  // shape. `mouse` is a THREE.Vector2 of the CLIENT pixel
                  // (NOT NDC): `screenToCast` subtracts `rect.left/top` and
                  // divides by `clientWidth/Height` (`index.mjs:16987`).
                  const canvasEl = worldRef.current?.renderer?.three
                    ?.domElement as HTMLCanvasElement | undefined;
                  const cameraThree = worldRef.current?.camera?.three as
                    | unknown
                    | undefined;
                  const hasClientPoint =
                    typeof click.clientX === "number" &&
                    typeof click.clientY === "number";
                  const raycastData =
                    raycastAvailableRef.current &&
                    hasClientPoint &&
                    canvasEl &&
                    cameraThree
                      ? {
                          camera: cameraThree,
                          dom: canvasEl,
                          mouse: new THREE.Vector2(click.clientX, click.clientY),
                        }
                      : null;

                  // isBusy snapshot at click time — the telemetry field that
                  // lets the field PROVE instant picks pre-warm (models still
                  // streaming tiles ⇒ `true`).
                  const snapBusy = (): boolean => {
                    const frags = fragmentsRef.current;
                    if (!frags) return false;
                    for (const [, m] of frags.core.models.list) {
                      if (m.isBusy) return true;
                    }
                    return false;
                  };

                  const rfr = await pickElementIdRaycastFirst({
                    raycast:
                      raycastData !== null
                        ? click.touch
                          ? (withTouchTolerance(
                              fragmentsRef.current as unknown as WorkerRaycaster,
                            ) as unknown as WorkerRaycaster)
                          : (fragmentsRef.current as unknown as WorkerRaycaster)
                        : null,
                    raycastData,
                    idPassFallback: runIdPassGuarded,
                    timeoutMs: RAYCAST_PICK_TIMEOUT_MS,
                    onTimeout: () => {
                      chainStatsRef.current.raycastTimeouts += 1;
                      tel.breadcrumb("pick", "raycast-timeout", {
                        modelCount:
                          fragmentsRef.current?.core.models.list.size ?? 0,
                      });
                    },
                  });

                  let guarded: IdPickHit | null | undefined;
                  let raycastHitPoint: {
                    x: number;
                    y: number;
                    z: number;
                  } | null = null;
                  let raycastAuthoritative = false;
                  if (rfr.backend === "raycast") {
                    raycastAuthoritative = true;
                    chainStatsRef.current.lastPickBackend = "raycast";
                    chainStatsRef.current.lastRaycastMs = rfr.ms;
                    chainStatsRef.current.lastRaycastBusy = snapBusy();
                    tel.breadcrumb("pick", "raycast", {
                      ms: rfr.ms,
                      kind: rfr.kind,
                      isBusy: chainStatsRef.current.lastRaycastBusy,
                    });
                    if (rfr.kind === "hit") {
                      guarded = {
                        modelId: rfr.hit.modelId,
                        expressId: rfr.hit.expressId,
                        probeNdc: click.ndc,
                      };
                      raycastHitPoint = rfr.hit.point;
                    } else {
                      guarded = null; // authoritative empty space
                    }
                  } else {
                    chainStatsRef.current.lastPickBackend =
                      rfr.reason === "timeout"
                        ? "idpass-fallback-timeout"
                        : rfr.reason === "throw"
                          ? "idpass-fallback-throw"
                          : "idpass";
                    if (rfr.reason !== "unavailable") {
                      tel.breadcrumb("pick", "idpass-fallback", {
                        reason: rfr.reason,
                        raycastMs: rfr.raycastMs,
                      });
                    }
                    guarded = rfr.outcome;
                  }
                  if (guarded === undefined) {
                    // Wave 28: two ways to land here. The wave-27 guard
                    // timed the whole pick out (counted in `pickTimeouts`),
                    // or the pick itself reported UNKNOWN — a pixel hit an
                    // element but its `itemId → localId` translation never
                    // came back off the fragments worker inside
                    // LOCAL_ID_BUDGET_MS. The second one is the case that
                    // used to cost the full 4 s stall: the click is a
                    // no-op in ~600 ms, the selection is left exactly as
                    // it was (a false empty-space read would have cleared
                    // it and mis-anchored a task), and the newest queued
                    // click still gets its chance.
                    if (chainStatsRef.current.pickTimeouts === lastPickTimeouts) {
                      const s = chainStatsRef.current;
                      s.inconclusiveClicks += 1;
                      s.lastClickToSelectionMs = Math.round(
                        performance.now() - click.clickTs,
                      );
                    }
                    if (pendingClickRef.current) {
                      click = pendingClickRef.current;
                      pendingClickRef.current = null;
                      continue;
                    }
                    // Belt on top of the guard: every apply clears its own
                    // deferred-anchor flag, so reaching here with the flag
                    // set means an anchor was promised for a selection the
                    // chain no longer owns. Never leave tap-to-create
                    // waiting on a point that will not arrive.
                    if (pendingPickKeyRef.current) pendingPickKeyRef.current = null;
                    return;
                  }
                  // Wave 76: a hit on an element the viewer hid is a miss.
                  const idHit = filterHiddenHit(guarded, {
                    isHidden: (m, id) => hiddenTrackerRef.current.isHidden(m, id),
                  });
                  if (raycastAuthoritative) {
                    // Wave 45: the raycast answered this click — no id-pass
                    // render happened, so the render/RPC counters stay at
                    // their last id-pass value rather than being clobbered
                    // by a stale `lastStats`.
                    chainStatsRef.current.lastClickRenders = 0;
                  } else {
                    const rendersAfter = batchedIdPassRef.current
                      ? batchedIdPassRef.current.totalRenders
                      : 0;
                    chainStatsRef.current.lastClickRenders =
                      rendersAfter - rendersBefore;
                    chainStatsRef.current.idPassRenders +=
                      rendersAfter - rendersBefore;
                    {
                      // Wave 28: what this click actually paid, per phase —
                      // GPU readbacks vs fragments-worker round-trips. The
                      // tell for "1 RPC per click, 0 on a repeat" shipping.
                      //
                      // Reading it: `lastClickRenders` is 1 on a steady-state
                      // click. A 2 right after a mount or a canvas resize is
                      // EXPECTED, not a regression — that is the one click
                      // which pays an extra unclipped render to prove the
                      // scissor (W1) and, on the first pick, one extra control
                      // readback to prove the box readback. `lastPickScissor:
                      // false` from the start means the clip was declined (no
                      // target scissor surface, `?ffscissor=0`, or a failed
                      // proof — the last case also carries `degrades`/
                      // `pickTranslateTimeouts` clues).
                      const rs = batchedIdPassRef.current?.lastStats ?? null;
                      const s = chainStatsRef.current;
                      if (rs) {
                        s.lastPickRpcs = rs.rpcs;
                        s.lastPickReadbacks = rs.readbacks;
                        s.lastPickCacheHits = rs.cacheHits;
                        s.lastPickBoxRead = rs.boxRead;
                        s.lastPickBoxDecline = rs.boxDecline ?? null;
                        s.lastPickScissor = rs.scissor ?? false;
                        s.pickTranslateTimeouts += rs.translateTimeouts;
                      }
                    }
                  }
                  if (disposedRef.current) return;
                  // A newer click landed while this pass rendered —
                  // DROP the stale result and re-pick at the newest
                  // pixel. Field report: "click one element then
                  // another then another and just after that i get
                  // the highlight on the first" — queued picks
                  // applied stale. The supersede check makes that
                  // impossible: only the newest click ever applies.
                  if (pendingClickRef.current) {
                    chainStatsRef.current.superseded += 1;
                    click = pendingClickRef.current;
                    pendingClickRef.current = null;
                    continue;
                  }
                  // Wave 31b: `listener` decides who gets TOLD, not
                  // whether the click does anything. Selection, clear on
                  // empty space, and the highlight all apply without a
                  // subscriber (they used to `return` here, which is how
                  // the admin route ended up with dead clicks).
                  const listener = pickCallbackRef.current;

                  if (!idHit) {
                    // Empty-space click — mirror `selectElement`'s clear path.
                    chainStatsRef.current.emptyClicks += 1;
                    chainStatsRef.current.lastClickToSelectionMs = Math.round(
                      performance.now() - click.clickTs,
                    );
                    pendingPickKeyRef.current = null;
                    lastPickPointRef.current = null;
                    lastPickNormalRef.current = null;
                    // emit-only, never required
                    selectionRef.current = new Map();
                    for (const notify of selectionListenersRef.current) {
                      notify(selectionRef.current);
                    }
                    queueHighlight(null);
                    listener?.(null);
                    if (benchEnabledRef.current) recordPickBench(performance.now() - t0);
                    return;
                  }

                  const { modelId, expressId, probeNdc } = idHit;
                  const next = new Map<string, Set<number>>();
                  next.set(modelId, new Set([expressId]));
                  const key = selectionFingerprint(next);
                  // ── Phase 1 (id pass resolved): selection + highlight NOW.
                  // The orange tint no longer waits for the depth pass —
                  // click→critical-path went from three serialized GPU
                  // renders (getFullPick ~190 ms) to ONE. The click point
                  // lands ~60 ms later in phase 2; until then
                  // `pendingPickKeyRef` tells tap-to-create a real anchor
                  // is inbound, so the marker waits instead of racing to
                  // the (slow, and wrong for canvas picks) bbox boxer.
                  pendingPickKeyRef.current = key;
                  lastPickPointRef.current = null;
                  lastPickNormalRef.current = null;
                  selectionRef.current = next;
                  {
                    const s = chainStatsRef.current;
                    s.applied += 1;
                    s.lastClickToSelectionMs = Math.round(performance.now() - click.clickTs);
                    s.recentClickToSelectionMs.push(s.lastClickToSelectionMs);
                    if (s.recentClickToSelectionMs.length > 20) s.recentClickToSelectionMs.shift();
                  }
                  for (const notify of selectionListenersRef.current) {
                    notify(selectionRef.current);
                  }
                  // Wave 22: coalesced highlight — the queue drains
                  // one cycle at a time and always applies the
                  // NEWEST pending target (intermediates skipped).
                  queueHighlight({ modelId, expressId });
                  // Wave 29: emit the pick event HERE, in phase 1, not
                  // after the depth pass. `listener` is the app's property
                  // panel path (PropertiesDrawer → store → `getElementData`),
                  // and NOTHING in that path reads `event.point` — the
                  // tap-to-create anchor is read separately through
                  // `getSelectionWorldPoint()` / `isSelectionPointPending()`,
                  // whose contract is unchanged. Awaiting the depth render
                  // first made every panel wait an extra full GPU render
                  // (~40-60 ms on the field device) behind a value it does
                  // not use, and up to the 4 s stall budget when the worker
                  // is wedged. The zero-vector is the shape wave-15
                  // consumers already tolerate.
                  listener?.({
                    modelId,
                    expressId,
                    point: new THREE.Vector3(0, 0, 0),
                  });
                  if (benchEnabledRef.current) recordPickBench(performance.now() - t0);

                  if (raycastAuthoritative) {
                    // Wave 45: the raycast hit already carries the exact
                    // world point — no depth pass to run (saves the full
                    // frame render the id-pass path pays for the anchor).
                    // Stash it directly and clear the deferred-anchor flag.
                    lastPickPointRef.current = raycastHitPoint
                      ? {
                          key,
                          point: { ...raycastHitPoint },
                        }
                      : null;
                    // Wave 48: the raycast carries no surface normal, so
                    // resolve it lazily in the background (cheap normal
                    // pass only) for the section-plane toolbar.
                    resolveSelectionNormal(key, probeNdc);
                    if (pendingPickKeyRef.current === key)
                      pendingPickKeyRef.current = null;
                    chainStatsRef.current.lastClickToPointMs = Math.round(
                      performance.now() - click.clickTs,
                    );
                    if (pendingClickRef.current) {
                      click = pendingClickRef.current;
                      pendingClickRef.current = null;
                      continue;
                    }
                    return;
                  }

                  // ── Phase 2 (depth pass): the anchor for tap-to-create.
                  // Re-reads the winning probe pixel only. The normal pass
                  // is never rendered on the click path — nothing in
                  // selection consumed it (~25 ms saved per click).
                  //
                  // Wave 28: when a newer click is already queued this
                  // pass is skipped ENTIRELY — by the wave-21 rule only
                  // the newest click ever applies, so its anchor can
                  // never be shown, and paying a full-frame depth render
                  // for it just delays the click the user is actually
                  // waiting on. The deferred-anchor flag is cleared here
                  // (never leave it set for a selection that will not
                  // get a point: tap-to-create would wait on a point that
                  // can no longer arrive).
                  if (pendingClickRef.current) {
                    if (pendingPickKeyRef.current === key) {
                      pendingPickKeyRef.current = null;
                    }
                    // Deliberately NOT counted as `superseded`: that
                    // counter (wave 21b/22) means "a pick RESULT was
                    // dropped because a newer click arrived before it
                    // applied". Here the selection DID apply — only its
                    // anchor render is skipped — so incrementing it
                    // would silently change the meaning of the number
                    // the wave-27 stall diagnosis is read off.
                    click = pendingClickRef.current;
                    pendingClickRef.current = null;
                    continue;
                  }
                  // No newer click: the depth pass still runs, but it no
                  // longer gates the emit above — it only stashes the
                  // anchor. `getPointAt` is synchronous inside TOE (one
                  // depth render + one readback), so the budget below is a
                  // jank backstop, not a hang fix; nothing on the click
                  // path may sit inside the single-flight latch unguarded.
                  let point: { x: number; y: number; z: number } | null;
                  try {
                    point = await withStallGuard<
                      { x: number; y: number; z: number } | null
                    >(
                      // Wave 28 W1b: same clip the id pass got, applied to
                      // the depth render (one anchor pixel instead of the
                      // whole frame). `pickAnchorClipped` calls TOE's own
                      // `getPointAt` and compares against an unclipped
                      // control before trusting the clip, so a clip that
                      // drops the geometry falls back to the plain call —
                      // and a silently dropped anchor is what put
                      // tap-to-create back on the bbox centre in wave 20.
                      isRenderScissorEnabled()
                        ? pickAnchorClipped(fastPicker, probeNdc).then(
                            (r) => r.point,
                          )
                        : fastPicker.getPointAt(probeNdc),
                      () => {
                        chainStatsRef.current.phase2Timeouts += 1;
                      },
                      null,
                      PICK_STALL_BUDGET_MS,
                    );
                  } catch (err) {
                    // Wave 28 review fix: the depth pass must never reject
                    // out of the click listener, and on the way down it has
                    // to release the deferred-anchor flag so tap-to-create
                    // falls back to the bbox boxer instead of waiting
                    // forever. The pick event already fired in phase 1 and
                    // the selection is real, so a failed anchor costs only
                    // the precision of the marker's landing point.
                    // eslint-disable-next-line no-console
                    console.warn("[IfcViewer] depth pass failed:", err);
                    point = null;
                  }
                  if (disposedRef.current) return;
                  chainStatsRef.current.lastClickToPointMs = Math.round(
                    performance.now() - click.clickTs,
                  );
                  if (point) {
                    lastPickPointRef.current = {
                      key,
                      point: { x: point.x, y: point.y, z: point.z },
                    };
                  }
                  // Wave 48: resolve the face normal in the background so
                  // the section-plane toolbar can orient parallel to the
                  // picked face. Bounded GPU normal pass only — not on the
                  // click critical path (selection + anchor already landed).
                  resolveSelectionNormal(key, probeNdc);
                  if (pendingPickKeyRef.current === key) pendingPickKeyRef.current = null;
                  // Wave 29: no emit here — `listener` fired in phase 1.
                  // This block only stashes the anchor that
                  // `getSelectionWorldPoint()` reads.
                  // A click that arrived while the depth pass ran still
                  // deserves its selection — continue with the newest.
                  if (pendingClickRef.current) {
                    click = pendingClickRef.current;
                    pendingClickRef.current = null;
                    continue;
                  }
                  return;
                }
              } finally {
                pickBusyRef.current = false;
              }
            };
            await runChain(queuedClick);
          };
          canvas.addEventListener("click", onClick);
          pickCleanupRef.current = () => {
            canvas.removeEventListener("click", onClick);
            dragGuard.dispose();
            pickInstalledRef.current = false;
          };
          return;
        }
        // No canvas (jsdom / a mock without a domElement): fall through to
        // the raycaster event subscription below so single-select still
        // works rather than leaving the subscription dead.
      }

      // ── Raycaster fallback (and the no-canvas case) ─────────────
      const onHighlight = (
        modelIdMap: Record<string, Set<number>>,
      ): void => {
        if (disposedRef.current) return;
        // Wave 15 (multi-model picking): resolve the hit through the
        // drift-clean resolver instead of reading the first entry
        // blindly. The Highlighter fires `onHighlight` with a map of
        // modelId → Set<localId>; for single-select that map has one
        // entry, but routing it through `resolveNearestHit` guarantees
        // a click always resolves `{ modelId, expressId }` for the
        // ACTUALLY-hit model (nearest wins) should the map ever hold
        // more than one model. The Highlighter doesn't expose a
        // per-hit distance here (its engine raycast already resolved
        // the front-most fragment), so entries carry no distance and
        // degenerate to input-order — identical to the previous
        // first-entry behavior for the single-select case.
        const hits: RawPickHit[] = [];
        for (const [modelId, ids] of Object.entries(modelIdMap)) {
          if (ids.size === 0) continue;
          const localId = ids.values().next().value;
          if (typeof localId === "number") hits.push({ modelId, localId });
        }
        const resolved = resolveNearestHit(hits);
        if (!resolved) return;
        // Wave 76: a hit on a viewer-hidden element is not a pick.
        if (hiddenTrackerRef.current.isHidden(resolved.modelId, resolved.expressId)) return;
        const listener = pickCallbackRef.current;
        if (!listener) return;
        listener({
          modelId: resolved.modelId,
          expressId: resolved.expressId,
          // Highlighter doesn't expose the world point.
          point: new THREE.Vector3(),
        });
      };
      const onClear = (): void => {
        if (disposedRef.current) return;
        // Forward empty-space clears as `null` to the pick
        // callback so the consumer's store stays in sync with
        // the visual highlight.
        const listener = pickCallbackRef.current;
        if (!listener) return;
        listener(null);
      };
      h.events.select.onHighlight.add(onHighlight);
      h.events.select.onClear.add(onClear);
      pickCleanupRef.current = () => {
        h.events.select.onHighlight.remove(onHighlight);
        h.events.select.onClear.remove(onClear);
        pickInstalledRef.current = false;
      };
    }

    // ─── Wave 12: 3D measurement helpers ──────────────────────────
    // Shared by the imperative handle methods below and the unmount
    // cleanup branch. All state lives in refs, so these helpers see
    // the latest values without needing to be re-created per render.

    /**
     * Wave 63: cancel in-flight creation and clear the completed list of
     * EVERY measurement type used this mount (length / area / angle /
     * volume). `list` is a FRAGS DataSet and `list.clear()` cascades to
     * the visual sub-collections via the engine's own `onCleared`.
     */
    function clearAllMeasure3D(): void {
      for (const component of measure3DUsedRef.current) {
        try {
          component.cancelCreation?.();
          component.list?.clear();
        } catch (err) {
          // eslint-disable-next-line no-console
          console.warn("[IfcViewer] clearMeasurements failed:", err);
        }
      }
    }

    // ─── Wave 67: 2D level-plan measure tool ─────────────────────
    // The plan's MeasurementLineSystem draws its distance labels / dots
    // as CSS2D marks created here (it cannot import OBCF itself).

    function planSystem(): {
      sys: ReturnType<NonNullable<typeof levelPlanRef.current>["getMeasureSystem"]>;
      drawing: NonNullable<
        ReturnType<NonNullable<typeof levelPlanRef.current>["getDrawing"]>
      >;
    } | null {
      const ctrl = levelPlanRef.current;
      const sys = ctrl?.getMeasureSystem?.();
      const drawing = ctrl?.getDrawing?.();
      return sys && drawing ? { sys, drawing } : null;
    }

    /** CSS2D layer needed for the plan tool (armed, or marks still shown). */
    function planMeasureLayerNeeded(): boolean {
      const sys = levelPlanRef.current?.getMeasureSystem?.();
      if (!sys) return false;
      return (
        (activeToolRef.current === "measure" && !measure3DRef.current) ||
        (sys.labelCount ?? 0) > 0
      );
    }

    function createPlanLabelFactory(world: OBC.World): MeasureLabelFactory {
      return {
        create(drawing, kind, position, text) {
          const parent = (drawing as { three?: THREE.Object3D }).three;
          if (!parent) return null;
          const el = document.createElement("div");
          el.className = kind === "dot" ? "ff-m2d-dot" : "ff-m2d-label";
          if (text !== undefined) el.textContent = text;
          const mark = new OBCF.Mark(world, el, parent);
          mark.three.position.set(position.x, position.y, position.z);
          return {
            setText: (t: string) => {
              el.textContent = t;
            },
            setPosition: (p) => {
              mark.three.position.set(p.x, p.y, p.z);
            },
            dispose: () => mark.dispose(),
          };
        },
      };
    }

    function install2DMeasureWiring(): void {
      const world = worldRef.current;
      const sys = levelPlanRef.current?.getMeasureSystem?.();
      if (!world || !sys) return;
      sys.labelFactory = createPlanLabelFactory(world);
      const onListChange = (): void => emitMeasurements();
      sys.onCommit.add((committed) => {
        const last = committed[committed.length - 1];
        if (last) {
          pushMeasureReadout({
            value: planDisplayValue(sys, last.item.pointA, last.item.pointB),
            unit: sys.units.unit,
          });
        }
        onListChange();
      });
      sys.onDelete.add(onListChange);
      sys.onMachineStateChanged.add((state: MeasureLineState) => {
        if (state.kind !== "awaitingSecondPoint" || !state.cursor) return;
        pushMeasureReadout({
          value: planDisplayValue(sys, state.pointA, state.cursor),
          unit: sys.units.unit,
        });
      });
    }

    function planDisplayValue(
      sys: NonNullable<ReturnType<typeof planSystem>>["sys"],
      a: { x: number; y: number; z: number },
      b: { x: number; y: number; z: number },
    ): number {
      const u = sys.units;
      const metres = sys.distanceOf(a, b) / (u.localPerMetre > 0 ? u.localPerMetre : 1);
      return metres * (u.unit === "cm" ? 100 : u.unit === "mm" ? 1000 : 1);
    }

    /** Plan-mode lines as list entries ("plan:<uuid>" ids). */
    function planEntries(): MeasurementEntry[] {
      const p = planSystem();
      if (!p) return [];
      return p.sys.listItems(p.drawing).map((it, i) => {
        const value = planDisplayValue(p.sys, it.pointA, it.pointB);
        return {
          id: `plan:${it.uuid}`,
          variant: "length" as const,
          label: `Plan length ${i + 1}`,
          value,
          unit: p.sys.units.unit,
          text: p.sys.formatDistance(it.pointA, it.pointB),
        };
      });
    }

    /** 3D measurements followed by the open plan's lines. */
    function allMeasurementEntries(): MeasurementEntry[] {
      return [
        ...measureBookRef.current.snapshot(measureSources()),
        ...planEntries(),
      ];
    }

    /** Every armed-so-far component with its variant (BookSource shape). */
    function measureSources(): Array<{
      variant: MeasureVariant;
      component: MeasureComponentLike;
    }> {
      return [...measureVariantsRef.current].map(([component, variant]) => ({
        variant,
        component,
      }));
    }

    /** Re-read the list, notify the subscriber, make sure a frame is drawn. */
    function emitMeasurements(): void {
      requestRender("measure-list");
      // Always snapshot: it also starts the async volume values.
      const entries = allMeasurementEntries();
      const cb = measureListCbRef.current;
      if (!cb) return;
      try {
        cb(entries);
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn("[IfcViewer] onMeasurementsChange failed:", err);
      }
    }

    /** Drop every measurement (model unload / building switch). */
    function clearMeasurementsOnUnload(): void {
      if (measureVariantsRef.current.size === 0) return;
      clearAllMeasure3D();
      measureActiveIdRef.current = null;
      emitMeasurements();
    }

    /** Mark exactly one measurement's label(s) active (or none). */
    function setActiveMeasureMark(id: string | null): void {
      const book = measureBookRef.current;
      const mark = (entryId: string | null, on: boolean): void => {
        if (!entryId) return;
        const hit = book.find(measureSources(), entryId);
        if (!hit) return;
        for (const el of labelElementsOf(
          hit.variant,
          hit.component as BookComponent,
          hit.item as object,
        )) {
          el.classList.toggle(MEASURE_ACTIVE_CLASS, on);
        }
      };
      mark(measureActiveIdRef.current, false);
      measureActiveIdRef.current = id;
      mark(id, true);
      requestRender("measure-mark");
    }

    /**
     * AngleMeasurement builds its arc from `getArcPoints`, which is empty
     * for a degenerate angle (zero-length ray, e.g. two clicks on the same
     * snap point). With fat lines `LineGeometry.setPositions([])` throws
     * `Invalid typed array length` from inside the pointer-move handler.
     * Pad / hide instead of throwing.
     */
    function guardDegenerateAngleLines(m: MeasureComponentLike): void {
      const host = m as unknown as {
        makeLine?: (pts: Vec3Like[]) => unknown;
        setLinePoints?: (line: { visible?: boolean }, pts: Vec3Like[]) => void;
      };
      type Vec3Like = { x: number; y: number; z: number };
      const makeLine = host.makeLine?.bind(m);
      const setLinePoints = host.setLinePoints?.bind(m);
      if (makeLine) {
        host.makeLine = (pts) =>
          makeLine(pts.length >= 2 ? pts : [pts[0] ?? { x: 0, y: 0, z: 0 }, pts[0] ?? { x: 0, y: 0, z: 0 }]);
      }
      if (setLinePoints) {
        host.setLinePoints = (line, pts) => {
          if (pts.length < 2) {
            line.visible = false;
            return;
          }
          line.visible = true;
          setLinePoints(line, pts);
        };
      }
    }

    /**
     * One-time styling + list subscription for a measurement component:
     * fat on-top lines in a per-variant colour, and list events feeding
     * the measurements list.
     */
    function configureMeasureComponent(
      variant: MeasureVariant,
      m: MeasureComponentLike,
    ): void {
      measureVariantsRef.current.set(m, variant);
      if (!measureListUnsubsRef.current.has(m) && m.list) {
        const onChange = (): void => emitMeasurements();
        const list = m.list;
        list.onItemAdded?.add(onChange);
        list.onItemDeleted?.add(onChange);
        list.onCleared?.add(onChange);
        measureListUnsubsRef.current.set(m, () => {
          list.onItemAdded?.remove(onChange);
          list.onItemDeleted?.remove(onChange);
          list.onCleared?.remove(onChange);
        });
      }
      if (measureConfiguredRef.current.has(m)) return;
      measureConfiguredRef.current.add(m);
      try {
        // Fat (screen-pixel width) lines that ignore depth, so the
        // dimension is never hidden by the geometry it measures.
        const fat = (OBCF as unknown as {
          MeasurementLineType?: { Fat?: unknown };
        }).MeasurementLineType?.Fat;
        if (fat !== undefined) m.lineType = fat;
        m.lineWidth = MEASURE_LINE_WIDTH;
        if (m.linesMaterial) {
          m.linesMaterial.depthTest = false;
          m.linesMaterial.transparent = true;
          m.linesMaterial.needsUpdate = true;
        }
        if (variant === "angle") {
          m.rounding = 1;
          guardDegenerateAngleLines(m);
        }
        m.color = new THREE.Color(MEASURE_COLORS[variant]);
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn("[IfcViewer] measurement styling failed:", err);
      }
    }

    /** Emit a readout (or clear it with null) to the single subscriber. */
    function pushMeasureReadout(readout: MeasureReadout | null): void {
      const cb = measureReadoutCbRef.current;
      if (cb) cb(readout);
    }

    /**
     * Tear down the active 3D measurement session: detach the canvas
     * `click` listener + readout event subscriptions, disable the
     * component, and restore the selection/navigation surface.
     */
    function deactivateMeasure3D(): void {
      if (measure3DCleanupRef.current) {
        measure3DCleanupRef.current();
        measure3DCleanupRef.current = null;
      }
      const active = measure3DRef.current;
      if (active) {
        try {
          active.component.enabled = false;
        } catch {
          // A partial/stub component may not have a settable `enabled`;
          // the mode switch is still complete from our state's POV.
        }
        measure3DRef.current = null;
      }
      // Restore the pointer/selection surface: orbit left-click, default
      // cursor, and re-arm the Highlighter's auto-highlight.
      const container = containerRef.current;
      if (container) container.style.cursor = "";
      const world = worldRef.current;
      const ctl = world?.camera?.controls as unknown as {
        mouseButtons?: { left: number };
      } | undefined;
      if (ctl?.mouseButtons) ctl.mouseButtons.left = 1; // ROTATE
      const h = highlighterRef.current as unknown as
        | { enabled: boolean }
        | null;
      if (h) h.enabled = true;
      activeToolRef.current = "navigation";
    }

    /**
     * Arm the TOE measurement component for `variant`. Resolves the
     * singleton from the components registry, configures snapping via
     * the shared SnapResolver, enables the component, and wires the
     * canvas click → `create()` pump plus the readout feed.
     */
    function activateMeasure3D(variant: MeasureVariant): void {
      const components = componentsRef.current;
      const world = worldRef.current;
      if (!components || !world) return;

      // Configure the shared SnapResolver tolerance (vertex/edge/face
      // snapping is already the default `snappings` on every measurer).
      try {
        const resolvers = components.get(OBC.SnapResolvers);
        const resolver = resolvers.get();
        resolver.maxDistance = MEASURE_SNAP_MAX_DISTANCE;
      } catch {
        // SnapResolvers is a stock core component; a partial registry
        // (tests) simply skips the tolerance write.
      }

      const measurement = components.get(
        MEASURE_COMPONENT_CLASSES[
          variant
        ] as unknown as new (
          components: OBC.Components,
        ) => OBC.Component,
      ) as unknown as MeasureComponentLike;
      measurement.world = world;
      configureMeasureComponent(variant, measurement);
      measurement.enabled = true;
      measure3DRef.current = { variant, component: measurement };
      measure3DUsedRef.current.add(measurement);

      // Suppress selection so a measuring click doesn't also tint an
      // element and fire the pick pipeline.
      activeToolRef.current = "measure";
      const highlight = highlighterRef.current as unknown as
        | { enabled: boolean }
        | null;
      if (highlight) highlight.enabled = false;

      // Crosshair + left-click orbit disabled (a plain click passes
      // through to our create handler; drag still trucks/dollies).
      const container = containerRef.current;
      if (container) container.style.cursor = "crosshair";
      const ctl = world.camera?.controls as unknown as
        | { mouseButtons?: { left: number } }
        | undefined;
      if (ctl?.mouseButtons) ctl.mouseButtons.left = 0; // NONE

      // Click → create. The TOE measurer's `create()` walks its own
      // state machine (first click starts a preview, subsequent clicks
      // finalise) — we only pump it.
      const canvas = world.renderer?.three?.domElement as
        | HTMLElement
        | undefined;
      // Wave 23: same drag-vs-click guard as the pick pipeline —
      // releasing a truck/dolly/orbit gesture over the canvas must
      // not create a measure point.
      const measureDragGuard = canvas ? attachDragGuard(canvas) : null;
      // Area (free mode) and Volume are open-ended: the engine never
      // commits them on its own (Length / Angle do). A double-click (the
      // second click of the pair has `detail >= 2`) or Enter commits.
      // `pendingCreate` lets a commit wait for the pick the click before
      // it started (picks resolve asynchronously on a worker).
      let pendingCreate: Promise<unknown> = Promise.resolve();
      const commit = (): void => {
        const active = measure3DRef.current;
        if (!active || !active.component.enabled) return;
        void pendingCreate.then(() => {
          const cur = measure3DRef.current;
          if (!cur || cur.component !== active.component) return;
          try {
            cur.component.endCreation?.();
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn("[IfcViewer] measure endCreation failed:", err);
          }
          pushMeasureReadout(null);
          requestRender("measure-commit");
        });
      };
      finishMeasure3DRef.current = commit;
      const onClick = (ev: MouseEvent): void => {
        if (measureDragGuard?.wasDrag()) return;
        const active = measure3DRef.current;
        if (!active || !active.component.enabled) return;
        if (
          (active.variant === "area" || active.variant === "volume") &&
          ev.detail >= 2
        ) {
          commit();
          return;
        }
        try {
          pendingCreate = Promise.resolve(active.component.create?.()).catch(
            () => undefined,
          );
        } catch (err) {
          // eslint-disable-next-line no-console
          console.warn("[IfcViewer] measure create failed:", err);
        }
      };
      const onKeyDown = (ev: KeyboardEvent): void => {
        if (ev.key !== "Enter") return;
        const target = ev.target as HTMLElement | null;
        if (target && /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName)) return;
        commit();
      };

      // Readout feed: re-emit on pointer move (live preview) and on
      // pointer stop (settled) — both fire without a payload, so we
      // read the value back off the component.
      const emit = (): void => {
        const active = measure3DRef.current;
        if (!active) return;
        const value = readMeasureValue(active.component, active.variant);
        if (typeof value === "number" && Number.isFinite(value)) {
          pushMeasureReadout({
            value,
            unit:
              active.component.units ??
              MEASURE_UNITS[active.variant],
          });
        }
      };

      measurement.onPointerMove?.add(emit);
      measurement.onPointerStop?.add(emit);
      if (canvas) {
        canvas.addEventListener("click", onClick);
      }
      window.addEventListener("keydown", onKeyDown);

      measure3DCleanupRef.current = () => {
        if (canvas) canvas.removeEventListener("click", onClick);
        window.removeEventListener("keydown", onKeyDown);
        finishMeasure3DRef.current = null;
        measureDragGuard?.dispose();
        measurement.onPointerMove?.remove(emit);
        measurement.onPointerStop?.remove(emit);
      };
    }

    // ─── Wave 13: 3D section plane helpers ─────────────────────
    // Shared by the imperative handle methods below (add/flip/clear)
    // and the unmount cleanup above. All state lives in refs.

    /**
     * Lazily resolve + style the components-front ClipStyler. The
     * default style is registered once (`SECTION_STYLE_NAME`) with a
     * translucent section FILL (`MeshBasicMaterial`). The cut-edge
     * outline (`linesMaterial`) is intentionally NOT set: supplying it
     * requires a `LineMaterial` from `three/examples/jsm/lines/...`,
     * whose `three/*` subpath import trips the settings vitest `three`
     * alias (architect-owned `vite.config.ts`). The Clipper's own
     * SimplePlane mesh plus the ClipStyler fill still make every cut
     * read clearly. (Documented Wave-13 deviation.)
     */
    function ensureSectionStyle(): OBCF.ClipStyler | null {
      const components = componentsRef.current;
      const world = worldRef.current;
      if (!components || !world) return null;

      let styler = clipStylerRef.current;
      if (!styler) {
        styler = components.get(OBCF.ClipStyler) as OBCF.ClipStyler;
        styler.world = world;
        clipStylerRef.current = styler;
      }
      if (!styler.styles.get(SECTION_STYLE_NAME)) {
        styler.styles.set(SECTION_STYLE_NAME, {
          fillsMaterial: new SectionFillMaterial({
            color: 0x9aa4ae,
            side: 2, // DoubleSide — see the fill from either side of the cut.
            transparent: true,
            opacity: 0.3,
            depthWrite: false,
          }),
        });
      }
      return styler;
    }

    /**
     * Canonical Clipper removal by engine id.
     *
     * `Clipper.deleteAll(types)` filters the Clipper's `list` by
     * `plane.type` (a custom usage tag), NOT by plane id. But
     * `createFromNormalAndCoplanarPoint` (the path we use for both
     * section planes and the floor clip) never assigns `plane.type`,
     * so passing our plane ids to `deleteAll` is a silent no-op — the
     * planes keep clipping and every material keeps recompiling as the
     * clipping set accumulates. `list.delete(id)` is the engine's real
     * removal path: its `onBeforeDelete` handler unlinks the plane from
     * the renderer (`renderer.setPlane(false, plane.three)`), disposes
     * the plane (which disposes any ClipStyler fill linked via
     * `plane.onDisposed`), then calls `updateMaterialsAndPlanes()` to
     * drop the plane from all fragment materials.
     */
    function removeClippingPlanesById(
      clipper: OBC.Clipper,
      ids: Iterable<string>,
    ): void {
      for (const id of ids) {
        if (id) clipper.list.delete(id);
      }
    }

    /**
     * Belt-and-suspenders: restore Orbit + Perspective after any
     * clipping-plane creation path. The engine's ClipStyler/Clipper
     * surfaces can leave the camera in PlanMode (orthographic, locked
     * dolly). Reuses the exact same reset as the floor-clip path.
     */
    function resetCameraProjectionAfterClip(): void {
      const world = worldRef.current;
      if (!world) return;
      const cam = world.camera as unknown & {
        projection?: { set(value: string): void };
        set?(mode: string): void;
      };
      cam.projection?.set("Perspective");
      (cam as unknown as { set(mode: string): void }).set?.("Orbit");
    }

    /**
     * Render on demand: ClipStyler fills/edges are computed by a worker
     * section query and land asynchronously — `ClipEdges.create/update`
     * fire `updateMeshes()` per model without awaiting it, on creation
     * and after every plane drag. Wrap the instance's `updateMeshes` so
     * each settled geometry update asks for a frame.
     */
    function watchSectionEdges(edges: unknown): void {
      const e = edges as {
        updateMeshes?: (...a: unknown[]) => unknown;
        three?: {
          addEventListener?: (type: string, cb: () => void) => void;
        };
      } | null;
      if (!e) return;
      // The FIRST fill is already in flight when createFromClipping
      // returns (the edges update in their constructor, before we can
      // wrap anything). Its meshes are added to the edges group right
      // before their geometry is set, so a childadded on the group
      // covers it (the render runs on the next animation frame, after
      // the geometry assignment's microtask).
      try {
        e.three?.addEventListener?.("childadded", () => requestRender("section-fill"));
      } catch {
        // not a three Object3D: the wrap below still covers updates
      }
      if (typeof e.updateMeshes !== "function") return;
      const orig = e.updateMeshes;
      e.updateMeshes = function (this: unknown, ...a: unknown[]): unknown {
        const r = orig.apply(this, a);
        requestRender("section-fill");
        if (r && typeof (r as Promise<unknown>).then === "function") {
          (r as Promise<unknown>).then(
            () => requestRender("section-fill"),
            () => requestRender("section-fill"),
          );
        }
        return r;
      };
    }

    /** Add a section plane; returns false (no-op + warn) at the cap. */
    function addSectionPlaneImpl(
      point: { x: number; y: number; z: number },
      normal: { x: number; y: number; z: number },
      options?: SectionPlaneOptions,
    ): boolean {
      const world = worldRef.current;
      const comps = componentsRef.current;
      if (!world || !comps) return false;
      if (sectionPlanesRef.current.length >= MAX_SECTION_PLANES) {
        // eslint-disable-next-line no-console
        console.warn(
          `[IfcViewer] max section planes reached (${MAX_SECTION_PLANES}).`,
        );
        return false;
      }

      try {
        const clipper = comps.get(OBC.Clipper);
        clipper.enabled = true;
        clipper.config.color = new THREE.Color("#181c22");
        clipper.config.opacity = 0.15;
        const id = clipper.createFromNormalAndCoplanarPoint(
          world,
          new THREE.Vector3(normal.x, normal.y, normal.z),
          new THREE.Vector3(point.x, point.y, point.z),
        );
        sectionPlanesRef.current.push({
          id,
          point: { ...point },
          normal: { ...normal },
        });

        // Wave 82: a client with its own controls hides the engine's
        // helper (quad + transform arrow); `visible` is independent of
        // `enabled`, so the plane keeps clipping.
        if (options?.helper === false) {
          const plane = clipper.list.get(id) as { visible?: boolean } | undefined;
          if (plane) plane.visible = false;
        }

        // Style the cut edges/fill. Guard against partial registries
        // (tests) — the plane is still valid without the styler.
        const styler = options?.styled === false ? null : ensureSectionStyle();
        if (styler) {
          const edges = styler.createFromClipping(id, {
            world,
            items: { [SECTION_STYLE_NAME]: { style: SECTION_STYLE_NAME } },
          });
          watchSectionEdges(edges);
        }
        resetCameraProjectionAfterClip();
        tel.breadcrumb("section", "plane-add", { count: sectionPlanesRef.current.length });
        return true;
      } catch (err) {
        // eslint-disable-next-line no-console
        console.warn("[IfcViewer] addSectionPlane failed:", err);
        return false;
      }
    }

    // ─── Wave 14: bench recorder (dev-only) ─────────────────────
    // Record a single resolution-sample (ms) and, at most once per
    // second, log p50/p95 + sample count. `?bench=1` gating lives in
    // `benchEnabledRef` (read once at mount) so there is no
    // `performance.now()` or console cost on the production path.
    function recordPickBench(ms: number): void {
      benchSamplesRef.current.push(ms);
      const now = Date.now();
      if (now - benchLastLogRef.current < 1000) return;
      benchLastLogRef.current = now;
      const stats = computePickStats(
        benchSamplesRef.current,
        pickBackendRef.current,
      );
      // eslint-disable-next-line no-console
      console.info(`[IfcViewer:bench] ${formatPickStats(stats)}`);
    }

    useImperativeHandle(
      ref,
      // Render on demand: every method that can change the picture
      // invalidates the view when called and again when it returns /
      // settles (see wrapHandleForInvalidation; read-only methods —
      // get*/is*/on*/projections/picks — are left untouched).
      (): IfcViewerHandle => {
      const handle = wrapHandleForInvalidation<IfcViewerHandle>({
        get loadedModelIds() {
          return loadedModelIdsRef.current;
        },
        getModelVersionKey: (modelId: string): string | null =>
          loadedVersionRef.current.get(modelId) ?? null,
        update: async () => {
          const fragments = fragmentsRef.current;
          if (fragments) await fragments.core.update();
        },
        openLevel: async (name: string): Promise<boolean> => {
          const ctrl = levelPlanRef.current;
          if (!ctrl) return false;
          const ok = await ctrl.open(name);
          if (ok) {
            viewerSliceRef.current?.setActiveStoreyName(name);
            // Task 18: auto-arm the measure tool when a level plan
            // opens. The spec calls for "simplest UX for MVP":
            // a level plan IS the measurement view, so we don't
            // require a separate toggle. Closing the level plan
            // (or switching buildings) tears the tool down.
            if (containerRef.current) {
              setActiveTool("measure");
            }
          }
          return ok;
        },
        closeLevel: (): void => {
          const ctrl = levelPlanRef.current;
          if (!ctrl) return;
          // Reset tool FIRST so the click/mousemove listeners are
          // detached before the drawing.dispose() inside close()
          // tears down the scene graph the listeners might still
          // be reading from.
          setActiveTool("navigation");
          ctrl.close();
          viewerSliceRef.current?.setActiveStoreyName(null);
        },
        fitLevelPlan: async (): Promise<boolean> => {
          const world = worldRef.current;
          const ctrl = levelPlanRef.current;
          if (!world || !ctrl) return false;
          const drawing = ctrl.getDrawing();
          if (!drawing) return false;
          // drawing.three.position is (cx, slabTop, cz) — set by
          // LevelPlanController.open(). Replay open()'s step-9
          // framing: top-down lookAt from LEVEL_PLAN_FRAME_DISTANCE m, then ortho fit.
          const pos = drawing.three.position;
          const controls = world.camera.controls as unknown as {
            setLookAt?: (
              ex: number,
              ey: number,
              ez: number,
              tx: number,
              ty: number,
              tz: number,
              transition?: boolean,
            ) => void;
          };
          controls?.setLookAt?.(
            pos.x,
            pos.y + LEVEL_PLAN_FRAME_DISTANCE,
            pos.z,
            pos.x,
            pos.y,
            pos.z,
            false,
          );
          const cam = world.camera as unknown as {
            projection?: { current?: string };
            fit?: (meshes: Iterable<unknown>, offset?: number) => Promise<void>;
          };
          if (cam.projection && cam.fit) {
            const meshes: unknown[] = [];
            world.scene.three.traverse((obj: unknown) => {
              if (
                obj &&
                typeof obj === "object" &&
                (obj as { isMesh?: boolean }).isMesh
              ) {
                meshes.push(obj);
              }
            });
            if (meshes.length > 0) {
              try {
                await cam.fit(meshes as never, 1.2);
              } catch (err) {
                // eslint-disable-next-line no-console
                console.warn(
                  "[IfcViewer] fitLevelPlan: camera.fit failed, keeping lookAt frame:",
                  err,
                );
              }
            }
          }
          return true;
        },
        pickWorldPoint: async (
          clientX?: number,
          clientY?: number,
        ): Promise<{ x: number; y: number; z: number } | null> => {
          // Resolve the engine's fragment-aware raycaster. The
          // `OBC.Raycasters` component is registered on the
          // components instance at mount time (it's part of the
          // stock engine — no extra setup needed), and
          // `casters.get(world)` returns (lazily creating) a
          // `SimpleRaycaster` bound to the given world.
          const casters = componentsRef.current?.get(OBC.Raycasters);
          if (!casters || !worldRef.current) return null;
          const caster = casters.get(worldRef.current) as unknown as WorldPointCaster;
          // If the caller provided a click position, convert
          // it to NDC and pass it explicitly to the backend.
          // The default (`this.mouse.position`) is the last
          // pointer event the canvas received — and during the
          // calibration wizard the canvas is shadowed by the
          // 3D pane (`pointer-events: auto`), so the Mouse
          // class never updates. Without this override, every
          // pick would be at whatever stale screen point the
          // mouse last crossed the canvas, not the actual click.
          let ndc: { x: number; y: number } | undefined;
          if (clientX !== undefined && clientY !== undefined) {
            const canvas = worldRef.current.renderer?.three
              ?.domElement as HTMLElement | undefined;
            if (canvas) {
              const rect = canvas.getBoundingClientRect();
              if (rect.width > 0 && rect.height > 0) {
                // CSS pixels → NDC. NDC y-up (top=+1) but
                // `getBoundingClientRect` is y-down, so flip.
                const ndcX =
                  ((clientX - rect.left) / rect.width) * 2 - 1;
                const ndcY =
                  -(((clientY - rect.top) / rect.height) * 2 - 1);
                ndc = { x: ndcX, y: ndcY };
              }
            }
          }
          // Wave 14: resolve through the live backend. FastModelPicker
          // (GPU depth readback) when it initialized cleanly, otherwise
          // the Raycasters sweep. Same `{x, y, z} | null` result either
          // way — the wizard never knows which path ran.
          const t0 = benchEnabledRef.current ? performance.now() : 0;
          let point: { x: number; y: number; z: number } | null;
          if (pickBackendRef.current === "fast" && fastPickerRef.current) {
            point = await pickWorldPointFast(fastPickerRef.current, ndc);
          } else {
            point = await pickWorldPointRaycast(caster, ndc);
          }
          if (benchEnabledRef.current) {
            recordPickBench(performance.now() - t0);
          }
          // `point` is a `THREE.Vector3` inside the engine's picker,
          // but we copy its .x/.y/.z into a plain object so the
          // wizard never has to import Three. Drift-clean boundary.
          return point;
        },
        getViewportRevision: (): number => {
          const world = worldRef.current;
          // Drift-clean reads of the engine's runtime matrices, the
          // same shape `worldToScreen` uses: no `import` of three
          // members, only structural access through `unknown`.
          const camThree = (world as { camera?: { three?: unknown } } | null)
            ?.camera?.three as
            | {
                matrixWorldInverse?: { elements?: ArrayLike<number> };
                projectionMatrix?: { elements?: ArrayLike<number> };
              }
            | undefined;
          const rendererThree = (world as { renderer?: { three?: unknown } } | null)
            ?.renderer?.three as
            | {
                getSize?: (t: { set(x: number, y: number): unknown }) => unknown;
                domElement?: { clientWidth?: number; clientHeight?: number };
              }
            | undefined;
          const view = camThree?.matrixWorldInverse?.elements;
          const proj = camThree?.projectionMatrix?.elements;
          if (!view || !proj || view.length < 16 || proj.length < 16) {
            // Nothing to hash. Be conservative — every frame is
            // dirty, exactly as before this method existed.
            viewportRevFallbackRef.current =
              (viewportRevFallbackRef.current + 1) | 0;
            return viewportRevFallbackRef.current;
          }
          // Viewport box: three's stored drawing-buffer CSS size when
          // the renderer exposes it (no layout read), falling back to
          // the canvas's own client box. Both are the same numbers in
          // production — `SimpleRenderer` sizes three from the
          // container — and the fallback keeps the token working on a
          // renderer that lacks `getSize`.
          if (typeof rendererThree?.getSize === "function") {
            rendererThree.getSize(VIEWPORT_SIZE_SCRATCH);
          } else {
            const dom = rendererThree?.domElement;
            if (!dom || typeof dom.clientWidth !== "number") {
              viewportRevFallbackRef.current =
                (viewportRevFallbackRef.current + 1) | 0;
              return viewportRevFallbackRef.current;
            }
            VIEWPORT_SIZE_SCRATCH.set(dom.clientWidth ?? 0, dom.clientHeight ?? 0);
          }
          // FNV-1a over the 32 matrix elements + the canvas CSS size.
          // `matrixWorldInverse` is refreshed by three on every render
          // and `projectionMatrix` on every `updateProjectionMatrix()`
          // (fov / zoom / near-far / resize), so this pair plus the
          // drawing-buffer size fully determines where a world point
          // lands on screen — which is all an overlay needs.
          let hash = VIEWPORT_REV_OFFSET;
          for (let i = 0; i < 16; i += 1) {
            hash = mixViewportRevision(hash, view[i] as number);
          }
          for (let i = 0; i < 16; i += 1) {
            hash = mixViewportRevision(hash, proj[i] as number);
          }
          hash = mixViewportRevision(hash, VIEWPORT_SIZE_SCRATCH.x);
          hash = mixViewportRevision(hash, VIEWPORT_SIZE_SCRATCH.y);
          return hash >>> 0;
        },
        worldToScreen: (
          point: { x: number; y: number; z: number },
        ): { x: number; y: number } | null => {
          // Guard: world not ready yet (mount in flight, disposed,
          // etc.). Same defensive pattern as the rest of the handle.
          const world = worldRef.current;
          if (!world) return null;
          const camera = world.camera as OBC.OrthoPerspectiveCamera;
          const renderer = world.renderer as OBC.SimpleRenderer;
          // Cast through `unknown` because THREE's
            // `position.constructor` has the loose type
            // `Function` (not a constructor signature), and the
            // hand-written shape here is intentionally permissive
            // (we only read `.x`/`.y`/`.project`). The drift
            // linter is about IMPORTS, not runtime access.
          const camThree = camera?.three as unknown as
            | {
                position?: { constructor: new (x: number, y: number, z: number) => { x: number; y: number; z: number; project: (cam: unknown) => void } };
                projectionMatrix?: { elements: number[] | Float32Array };
                matrixWorldInverse?: { elements: number[] | Float32Array };
              }
            | undefined;
          const domEl = renderer?.three?.domElement as
            | HTMLElement
            | undefined;
          if (!camThree || !domEl) return null;

          // Prefer the engine's runtime Vector3 (avoids a
          // top-of-file `import "three"` that the drift linter
          // rejects). If the engine exposes a different
          // vector-like class (a future TOE bump), the
          // `.constructor` lookup still finds it. Fall back to
          // manual matrix math if the constructor is missing —
          // this is a defensive guard, not a hot path.
          let projectedX = 0;
          let projectedY = 0;
          const Ctor = camThree.position?.constructor;
          if (Ctor) {
            // Cast through `unknown`: we know the runtime class
            // exposes `.project(camera)` and `.x`/`.y`. The
            // drift linter is about IMPORTS, not runtime
            // construction through the engine's own classes.
            const v = new Ctor(point.x, point.y, point.z) as {
              x: number;
              y: number;
              project: (cam: unknown) => void;
            };
            v.project(camera.three);
            projectedX = v.x;
            projectedY = v.y;
          } else {
            // Manual projection via the camera's matrices. We
            // compute `proj * view * (x, y, z, 1)` in column-major
            // form (the layout THREE uses), then map NDC to CSS
            // pixels. Pure math, no THREE dependency.
            const proj = camThree.projectionMatrix?.elements;
            const view = camThree.matrixWorldInverse?.elements;
            if (!proj || !view) return null;
            const x = point.x, y = point.y, z = point.z;
            // view * p
            const v0 = (view[0] as number) * x + (view[4] as number) * y + (view[8] as number) * z + (view[12] as number);
            const v1 = (view[1] as number) * x + (view[5] as number) * y + (view[9] as number) * z + (view[13] as number);
            const v2 = (view[2] as number) * x + (view[6] as number) * y + (view[10] as number) * z + (view[14] as number);
            const v3 = (view[3] as number) * x + (view[7] as number) * y + (view[11] as number) * z + (view[15] as number);
            // proj * (v0, v1, v2, v3)
            const c0 = (proj[0] as number) * v0 + (proj[4] as number) * v1 + (proj[8] as number) * v2 + (proj[12] as number) * v3;
            const c1 = (proj[1] as number) * v0 + (proj[5] as number) * v1 + (proj[9] as number) * v2 + (proj[13] as number) * v3;
            const c3 = (proj[3] as number) * v0 + (proj[7] as number) * v1 + (proj[11] as number) * v2 + (proj[15] as number) * v3;
            if (c3 === 0) return null;
            const ndcX = c0 / c3;
            const ndcY = c1 / c3;
            // NDC → CSS pixels. NDC y-up → CSS y-down (flip).
            // Use the canvas's bounding rect so the mapping is
            // independent of the renderer's internal canvas
            // resolution (the renderer sets the canvas pixel
            // buffer to the CSS size, but we read the CSS size
            // to stay robust against future DPI handling).
            // Wave 30: `getSize` (no layout flush) instead of a
            // `getBoundingClientRect` per projected point.
            const box = canvasCssBox(renderer?.three, domEl);
            return {
              x: ((ndcX + 1) / 2) * box.width,
              y: ((-ndcY + 1) / 2) * box.height,
            };
          }

          // `projectedX` / `projectedY` are now in NDC
          // ([-1, 1]). Map to CSS pixels in the canvas's local
          // coord system. The rect.width / rect.height is the
          // canvas's CSS box (the renderer resizes the
          // <canvas> to match its container on resize).
          // Wave 30: same no-layout path as the manual branch above.
          const box = canvasCssBox(renderer?.three, domEl);
          return {
            x: ((projectedX + 1) / 2) * box.width,
            y: ((-projectedY + 1) / 2) * box.height,
          };
        },
        unprojectToFloorPlane: (
          clientX: number,
          clientY: number,
          floorZ: number,
        ): { x: number; z: number } | null => {
          const world = worldRef.current;
          if (!world) return null;
          const camera = world.camera as OBC.OrthoPerspectiveCamera;
          const renderer = world.renderer as OBC.SimpleRenderer;
          const camThree = camera?.three as unknown as
            | {
                position?: {
                  constructor: new (
                    x: number,
                    y: number,
                    z: number,
                  ) => {
                    x: number;
                    y: number;
                    z: number;
                    unproject: (cam: unknown) => void;
                  };
                };
                projectionMatrixInverse?: {
                  elements: number[] | Float32Array;
                };
                matrixWorld?: { elements: number[] | Float32Array };
              }
            | undefined;
          const domEl = renderer?.three?.domElement as
            | HTMLElement
            | undefined;
          if (!camThree || !domEl) return null;

          // CSS pixels → NDC (same conversion as pickWorldPoint)
          const rect = domEl.getBoundingClientRect();
          if (rect.width <= 0 || rect.height <= 0) return null;
          const ndcX = ((clientX - rect.left) / rect.width) * 2 - 1;
          const ndcY = -(((clientY - rect.top) / rect.height) * 2 - 1);

          // Unproject near-plane and far-plane NDC points through
          // the camera to get a world-space ray. Same drift-clean
          // pattern as worldToScreen: construct via the camera's
          // own THREE.Vector3 constructor.
          const Ctor = camThree.position?.constructor;
          if (!Ctor) {
            // Manual inverse-projection fallback (defensive).
            const invProj = camThree.projectionMatrixInverse?.elements;
            const mw = camThree.matrixWorld?.elements;
            if (!invProj || !mw) return null;
            // NDC (ndcX, ndcY, z) → clip space → eye space → world
            // For an orthographic camera this is a straight affine
            // transform, not a perspective divide.
            const unproj = (z: number) => {
              // clip = invProj * (ndcX, ndcY, z, 1)
              const cx =
                (invProj[0] as number) * ndcX +
                (invProj[4] as number) * ndcY +
                (invProj[8] as number) * z +
                (invProj[12] as number);
              const cy =
                (invProj[1] as number) * ndcX +
                (invProj[5] as number) * ndcY +
                (invProj[9] as number) * z +
                (invProj[13] as number);
              const cz =
                (invProj[2] as number) * ndcX +
                (invProj[6] as number) * ndcY +
                (invProj[10] as number) * z +
                (invProj[14] as number);
              const cw =
                (invProj[3] as number) * ndcX +
                (invProj[7] as number) * ndcY +
                (invProj[11] as number) * z +
                (invProj[15] as number);
              // eye = clip / cw, then world = mw * eye
              const ex = cx / cw, ey = cy / cw, ez = cz / cw;
              const wx =
                (mw[0] as number) * ex +
                (mw[4] as number) * ey +
                (mw[8] as number) * ez +
                (mw[12] as number);
              const wy =
                (mw[1] as number) * ex +
                (mw[5] as number) * ey +
                (mw[9] as number) * ez +
                (mw[13] as number);
              const wz =
                (mw[2] as number) * ex +
                (mw[6] as number) * ey +
                (mw[10] as number) * ez +
                (mw[14] as number);
              return { wx, wy, wz };
            };
            const near = unproj(-1);
            const far = unproj(1);
            const dirX = far.wx - near.wx;
            const dirY = far.wy - near.wy;
            const dirZ = far.wz - near.wz;
            if (Math.abs(dirY) < 1e-10) return null;
            const t = (floorZ - near.wy) / dirY;
            return {
              x: near.wx + t * dirX,
              z: near.wz + t * dirZ,
            };
          }

          // Primary path: THREE.Vector3.unproject via the
          // camera's own constructor (no import). This is the
          // same pattern worldToScreen uses for .project().
          const near = new Ctor(ndcX, ndcY, -1) as {
            x: number;
            y: number;
            z: number;
            unproject: (cam: unknown) => void;
          };
          const far = new Ctor(ndcX, ndcY, 1) as {
            x: number;
            y: number;
            z: number;
            unproject: (cam: unknown) => void;
          };
          near.unproject(camera.three);
          far.unproject(camera.three);

          const dirX = far.x - near.x;
          const dirY = far.y - near.y;
          const dirZ = far.z - near.z;
          // Ray: near + t * dir. Intersect with y = floorZ.
          if (Math.abs(dirY) < 1e-10) return null;
          const t = (floorZ - near.y) / dirY;
          return { x: near.x + t * dirX, z: near.z + t * dirZ };
        },
        // Task 15: used by the calibration wizard's 3D line
        // SVG to portal into the IfcViewer's DOM. See
        // docs/TASK-15-LEVEL-PRESERVATION.md for the full
        // rationale.
        getContainer: (): HTMLDivElement | null => containerRef.current,
        zoom: (deltaY, clientX, clientY, deltaMode = 0): void => {
          const world = worldRef.current;
          if (!world) return;
          const ctl = world.camera.controls as unknown as {
            _dollyInternal?: (delta: number, x: number, y: number) => void;
            _isUserControllingDolly?: boolean;
            _zoomInternal?: (delta: number, x: number, y: number) => void;
            _isUserControllingZoom?: boolean;
            dollyToCursor?: boolean;
            dollySpeed?: number;
            _elementRect?: { x: number; y: number; width: number; height: number };
            domElement?: HTMLElement;
            mouseButtons?: { wheel: number };
          } | undefined;
          if (!ctl) return;
          // Mirror camera-controls' own wheel-handler math so a
          // forwarded event feels identical to a native one.
          // Source: camera-controls v3.1.2, `onMouseWheel`:
          //   deltaYFactor = isMac ? -1 : -3
          //   delta = deltaMode===1 && !ctrlKey
          //     ? deltaY / deltaYFactor
          //     : deltaY / (deltaYFactor * 10)
          //   _dollyInternal(-delta, ndcX, ndcY)
          // Without this normalization the raw `deltaY` is 10-30×
          // too sensitive, and passing clientX/Y in pixel space
          // (instead of normalized device coordinates) breaks the
          // cursor-pivot dolly that OBC.SimpleCamera enables by
          // default.
          const isMac =
            typeof navigator !== "undefined" &&
            navigator.platform.toUpperCase().indexOf("MAC") >= 0;
          const deltaYFactor = isMac ? -1 : -3;
          const delta =
            deltaMode === 1
              ? deltaY / deltaYFactor
              : deltaY / (deltaYFactor * 10);
          // NDC: -1 to +1, Y flipped to match camera-controls.
          let x = 0;
          let y = 0;
          if (ctl.dollyToCursor) {
            // Prefer _elementRect (camera-controls caches it on
            // each scroll); fall back to a live getBoundingClientRect
            // if the cache is missing (first event before any
            // scroll, or post-reattach).
            const rect =
              ctl._elementRect ?? ctl.domElement?.getBoundingClientRect();
            if (rect && rect.width > 0 && rect.height > 0) {
              x = ((clientX - rect.x) / rect.width) * 2 - 1;
              y = ((clientY - rect.y) / rect.height) * -2 + 1;
            }
          }
          // CRITICAL: flag camera-controls that the dolly is
          // driven by a user gesture. Without this flag the
          // update loop uses the slow `smoothTime` (OBC sets
          // 0.2) for the radius interpolation, and a single
          // wheel notch only nudges the camera by ~8% per
          // frame — so under rapid scrolling the camera lags
          // so far behind the target it appears to be not
          // zooming at all. With the flag, the update uses
          // the snappier `draggingSmoothTime` (default 0.125)
          // and the dolly tracks the cursor in real time.
          // This is what the camera-controls' own `onMouseWheel`
          // does (line 854 in 3.1.2) — we have to replicate it
          // because the pane is intercepting the wheel event
          // before it ever reaches the canvas.
          // Mirror camera-controls' own onMouseWheel dispatch:
          // when the camera is orthographic, `mouseButtons.wheel` is
          // set to CameraControls.ACTION.ZOOM (32) and we must call
          // `_zoomInternal` to change `camera.zoom` (the frustum
          // scale). For perspective cameras, `mouseButtons.wheel` is
          // ACTION.DOLLY (16) and `_dollyInternal` changes the camera
          // distance. Calling dolly in ortho mode is a no-op visually,
          // which is why the calibration wizard (which forces ortho
          // for level plans) could not zoom.
          const wheelAction = ctl.mouseButtons?.wheel ?? 16; // 16 = ACTION.DOLLY
          if (wheelAction === 32) {
            // ACTION.ZOOM — orthographic camera, scale the frustum
            if (ctl._zoomInternal) {
              ctl._isUserControllingZoom = true;
              ctl._zoomInternal(-delta, x, y);
            }
          } else {
            // ACTION.DOLLY — perspective camera, adjust distance
            if (ctl._dollyInternal) {
              ctl._isUserControllingDolly = true;
              ctl._dollyInternal(-delta, x, y);
            }
          }
        },
        // Task 18: tool switching. The handle exposes the
        // imperative API to the outside world (e.g. future
        // sidebar buttons). The current implementation also
        // calls setActiveTool internally from openLevel /
        // closeLevel — both paths funnel through the same
        // function so the wiring is consistent.
        setActiveTool: (tool: "navigation" | "measure"): void => {
          setActiveTool(tool);
        },
        get activeTool(): "navigation" | "measure" | null {
          return activeToolRef.current;
        },
        // ─── Task 19: visibility batching ──────────────────────────────
        // Queue a visibility change and schedule a single
        // requestAnimationFrame flush. Multiple calls within the
        // same frame coalesce — the flush collapses all queued
        // entries into one OBC.Hider.set call per model.
        //
        // We do NOT try to merge multiple entries for the same
        // model here: the simplest correct coalescing is "one
        // Hider.set per (modelId, visible) pair", and OBC.Hider
        // already handles the case where expressIds overlap
        // (last write wins at the express ID level).
        setElementVisibility: (
          modelId: string,
          expressIds: ReadonlySet<number>,
          visible: boolean,
        ): void => {
          if (!componentsRef.current) return;
          // Defensive copy — callers may mutate their input Set
          // after this call returns, but the queued entry should
          // own its own copy so the flush sees the values at
          // queue time.
          pendingVisibilityRef.current.push({
            modelId,
            expressIds: new Set(expressIds),
            visible,
          });
          if (rafHandleRef.current !== null) return;
          rafHandleRef.current = requestAnimationFrame(() => {
            rafHandleRef.current = null;
            const queue = pendingVisibilityRef.current;
            pendingVisibilityRef.current = [];
            if (queue.length === 0) return;
            if (disposedRef.current) return;
            const components = componentsRef.current;
            if (!components) return;
            // Lazy-resolve Hider (it lives on the components
            // instance from mount time; safe to call .get again
            // — OBC caches by class uuid).
            if (!hiderRef.current) {
              const hider = components.get(OBC.Hider) as unknown as {
                set: (
                  visible: boolean,
                  modelIdMap: Record<string, Set<number>>,
                ) => Promise<void>;
              };
              hiderRef.current = hider;
            }
            const hider = hiderRef.current;
            if (!hider) return;
            // Per-model merge: the same modelId might appear
            // multiple times in the queue (e.g. caller toggled
            // visibility for several express ID subsets in one
            // tick). We use separate true/false buckets per
            // model so the auto filter pass can safely send both
            // `visible=true` and `visible=false` in the same
            // frame without one overriding the other.
            //
            // Wave 63: an id queued BOTH hidden and shown in one frame
            // ends in the bucket of its LAST call (queue order). The
            // two buckets used to be flushed true-then-false, so a
            // hide-then-show of the same id stayed hidden.
            const byModel = new Map<
              string,
              { trueIds: Set<number>; falseIds: Set<number> }
            >();
            for (const entry of queue) {
              let existing = byModel.get(entry.modelId);
              if (!existing) {
                existing = { trueIds: new Set(), falseIds: new Set() };
                byModel.set(entry.modelId, existing);
              }
              const target = entry.visible ? existing.trueIds : existing.falseIds;
              const other = entry.visible ? existing.falseIds : existing.trueIds;
              for (const id of entry.expressIds) {
                target.add(id);
                other.delete(id);
              }
            }
            requestRender("visibility");
            for (const [modelId, { trueIds, falseIds }] of byModel) {
              hiddenTrackerRef.current.apply(modelId, trueIds, true);
              hiddenTrackerRef.current.apply(modelId, falseIds, false);
              if (trueIds.size > 0) {
                void Promise.resolve(hider.set(true, { [modelId]: trueIds })).then(
                  () => requestRender("visibility"),
                  (err: unknown) => {
                    // eslint-disable-next-line no-console
                    console.warn(
                      "[IfcViewer] OBC.Hider.set failed:",
                      err,
                    );
                  },
                );
              }
              if (falseIds.size > 0) {
                void Promise.resolve(hider.set(false, { [modelId]: falseIds })).then(
                  () => requestRender("visibility"),
                  (err: unknown) => {
                    // eslint-disable-next-line no-console
                    console.warn(
                      "[IfcViewer] OBC.Hider.set failed:",
                      err,
                    );
                  },
                );
              }
            }
          });
        },
        // ─── Task 19: element pick subscription ─────────────────────────
        // Install/clear a canvas click listener that raycasts and
        // forwards the hit to the listener. The listener is only
        // fired when `activeTool === "navigation"` — the measure
        // tool suppresses picks so clicks there don't double-fire
        // (once for the line measurement, once for the drawer).
        setOnElementPick: (cb): void => {
          // When `disableSelection` is on, the selection surface is
          // closed — `pickWorldPoint` (a pure raycast against the
          // world geometry) is the canonical pick path, and any
          // element-pick subscription would either never fire or
          // fight the consumer's pointer flow. Refuse the call so
          // the consumer learns early instead of silently never
          // receiving events.
          if (disableSelectionRef.current) {
            // eslint-disable-next-line no-console
            console.warn(
              "[IfcViewer] setOnElementPick is a no-op when disableSelectionRef.current is true. Use pickWorldPoint instead.",
            );
            return;
          }
          // Task 21 rewrite: the Highlighter does the picking
          // AND the highlighting automatically (its
          // `autoHighlightOnClick` defaults to TRUE). We subscribe
          // to its events instead of installing our own click
          // listener, which means we no longer fight
          // camera-controls for the `click` event (the Highlighter
          // handles its own pointer event routing).
          //
          // The Highlighter fires `events.select.onHighlight` with
          // a `modelIdMap` (record of modelId → Set<localId>).
          // We translate that into our flat
          // `ElementPickEvent { modelId, expressId, point }` shape.
          // The first set in the map is what the user picked
          // (single-select MVP).
          //
          // Race fix: the Highlighter is created inside the async
          // mount IIFE, but the imperative handle is set during
          // useImperativeHandle (synchronously). A consumer that
          // calls setOnElementPick right after the handle appears
          // (e.g. PropertiesDrawer's useEffect, which fires after
          // the handle is mounted) will hit the early-return
          // guard below. We queue the cb in
          // pendingPickCallbackRef; the mount IIFE installs it
          // after highlighterRef.current is set.
          //
          // Clear propagation: the Highlighter fires
          // `events.select.onClear` when the user clicks empty
          // space (with `multiple: "none"`). We forward that as
          // `null` to the pick callback so the consumer's store
          // can sync with the visual state. Without this, the
          // drawer continues to show the previous element while
          // the visual highlight is gone — out of sync.
          //
          // Detach any previous wiring first so we never stack
          // two listeners on the Highlighter.
          if (pickCleanupRef.current) {
            pickCleanupRef.current();
            pickCleanupRef.current = null;
          }
          pickCallbackRef.current = cb;
          if (cb === null) {
            pendingPickCallbackRef.current = null;
            return;
          }
          pendingPickCallbackRef.current = cb;
          const h = highlighterRef.current;
          if (!h) {
            // Highlighter not yet ready. The mount IIFE will pick
            // up pendingPickCallbackRef after setup completes
            // and install the subscription at that point. No
            // // eslint-disable-next-line no-console needed — this
            // is the expected path during cold mount.
            return;
          }
          // Highlighter is ready — install immediately.
          installPickSubscription(h, cb);
        },
        // ─── Task 21: selection / highlight API ─────────────────
        // Replace the current selection with one element (or clear
        // it). Pass null for both args to clear. The call is async
        // (highlightByID returns a Promise) but we don't await it
        // internally — the next caller can fire while the previous
        // highlight is still painting. The map snapshot returned
        // by `getSelection()` reflects the requested state, not the
        // painted state — that's deliberate, matches Zustand
        // semantics where the store is the source of truth.
        selectElement: (modelId, expressId): void => {
          // When `disableSelection` is on, the selection surface is
          // closed — `selectElement` is expected to be dead-code on
          // consumers in this mode (e.g. LinkView's spawn-point and
          // third-person-look flows only use `pickWorldPoint` +
          // `setRestrictedThirdPerson`). Warn so the misuse is loud
          // during dev instead of silently no-oping on a closed API.
          if (disableSelectionRef.current) {
            // eslint-disable-next-line no-console
            console.warn(
              "[IfcViewer] selectElement is a no-op when disableSelectionRef.current is true.",
            );
            return;
          }
          // Update internal state REGARDLESS of highlighter
          // availability — `getSelection()` should reflect the
          // requested state even if the visual feedback hasn't
          // been painted yet (highlighter init is async; this
          // matters for tests AND for early-mount callers).
          if (modelId === null || expressId === null) {
            // Clear path. Update internal state FIRST so a
            // listener that fires synchronously (e.g. via the
            // highlighter's own onClear event) sees the
            // post-clear state.
            lastPickPointRef.current = null;
            lastPickNormalRef.current = null;
            pendingPickKeyRef.current = null;
            selectionRef.current = new Map();
            queueHighlight(null);
            for (const cb of selectionListenersRef.current) {
              cb(selectionRef.current);
            }
            return;
          }
          // Set path. Single-element selection (MVP scope).
          // Build a fresh Map so the existing reference is not
          // mutated — `getSelection()` returns a copy via `new
          // Map(selectionRef.current)` so external callers can
          // mutate their copy safely.
          const next = new Map<string, Set<number>>();
          next.set(modelId, new Set([expressId]));
          // Programmatic selection — there is no click point, so the
          // stash is cleared and tap-to-create falls back to the
          // bbox centre (wave-20 contract of getSelectionWorldPoint).
          lastPickPointRef.current = null;
          lastPickNormalRef.current = null;
          pendingPickKeyRef.current = null;
          selectionRef.current = next;
          queueHighlight({ modelId, expressId });
          for (const cb of selectionListenersRef.current) {
            cb(selectionRef.current);
          }
        },
        setMemoryPressure: (level: MemoryPressure): void => {
          if (memoryPressureRef.current === level) return;
          memoryPressureRef.current = level;
          const eff = effectiveMemory(memoryTuningRef.current ?? {}, level);
          publishEngineBudget(eff);
          const frags = fragmentsRef.current;
          if (!frags) return;
          const st = (
            frags.core as unknown as { settings?: { graphicsQuality?: number } }
          )?.settings;
          if (st) st.graphicsQuality = eff.graphicsQuality;
          for (const [, m] of frags.core.models.list) {
            (m as unknown as { graphicsQuality: number }).graphicsQuality =
              eff.graphicsQuality;
          }
          // The view signature includes the quality, so the next update
          // re-culls and the workers drop what is now over budget.
          void frags.core.update(true);
          requestRender("memory-pressure");
        },
        clearSelection: (): void => {
          // When `disableSelection` is on, the selection surface is
          // closed — there is no highlighter wiring and no listeners
          // to notify. Warn so the misuse surfaces in dev instead of
          // silently no-oping.
          if (disableSelectionRef.current) {
            // eslint-disable-next-line no-console
            console.warn(
              "[IfcViewer] clearSelection is a no-op when disableSelectionRef.current is true.",
            );
            return;
          }
          lastPickPointRef.current = null;
          lastPickNormalRef.current = null;
          pendingPickKeyRef.current = null;
          selectionRef.current = new Map();
          queueHighlight(null);
          for (const cb of selectionListenersRef.current) {
            cb(selectionRef.current);
          }
        },
        // Snapshot — `new Map(selectionRef.current)` copies the
        // outer Map but the inner Sets are shared. That's fine for
        // read-only inspection (size checks, iteration). Callers
        // who need to mutate should `new Set(snapshot.get(modelId))`.
        getSelection: (): ReadonlyMap<string, ReadonlySet<number>> => {
          // When `disableSelection` is on, the selection surface is
          // closed — return an empty snapshot so consumers can still
          // defensively read without crashing. We intentionally do
          // NOT warn here: `getSelection` is the observational path
          // and may be called repeatedly from a render loop or a
          // defensive consumer; a warn would flood the console
          // without adding signal. The mutation paths warn instead.
          if (disableSelectionRef.current) {
            return new Map();
          }
          return new Map(selectionRef.current);
        },
        // Wave 5B: tap-to-create anchor. Drift-clean BoundingBoxer
        // path — the SAME component LevelPlanController uses, read
        // through componentsRef.get() (never `new`). `getCenter`
        // computes the union-box centre directly from a ModelIdMap.
        getSelectionWorldCenter: async (): Promise<{ x: number; y: number; z: number } | null> => {
          if (disableSelectionRef.current) return null;
          const components = componentsRef.current;
          const selection = selectionRef.current;
          if (!components || selection.size === 0) return null;
          const modelIdMap: Record<string, Set<number>> = {};
          for (const [modelId, ids] of selection) {
            modelIdMap[modelId] = new Set(ids);
          }
          try {
            const boxer = components.get(OBC.BoundingBoxer);
            const center = await boxer.getCenter(modelIdMap);
            if (
              !center ||
              !Number.isFinite(center.x) ||
              !Number.isFinite(center.y) ||
              !Number.isFinite(center.z)
            ) {
              return null;
            }
            return { x: center.x, y: center.y, z: center.z };
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn("[IfcViewer] getSelectionWorldCenter failed:", err);
            return null;
          }
        },
        // Wave 20: real click point of the current selection, when
        // the selection came from a canvas pick. The fingerprint
        // guard means a stash can never outlive the selection it was
        // taken from — a stale point reads as null and the caller
        // falls back to the bbox centre.
        getSelectionWorldPoint: (): { x: number; y: number; z: number } | null => {
          if (disableSelectionRef.current) return null;
          const stash = lastPickPointRef.current;
          if (!stash || selectionRef.current.size === 0) return null;
          if (selectionFingerprint(selectionRef.current) !== stash.key) return null;
          return stash.point;
        },
        // Wave 48: the world-space FACE normal of the pick that
        // produced the current selection. Same fingerprint guard as the
        // point stash — a stale normal reads as null and the caller
        // falls back to bbox-face-snap → camera direction.
        getSelectionWorldNormal: (): { x: number; y: number; z: number } | null => {
          if (disableSelectionRef.current) return null;
          const stash = lastPickNormalRef.current;
          if (!stash || selectionRef.current.size === 0) return null;
          if (selectionFingerprint(selectionRef.current) !== stash.key) return null;
          return stash.normal;
        },
        // Wave 21: the deferred-anchor flag. Keyed by fingerprint so
        // a pending point can only ever belong to the CURRENT
        // selection — a superseded click (single-flight chain) never
        // reports pending over a newer selection.
        isSelectionPointPending: (): boolean => {
          if (disableSelectionRef.current) return false;
          const pending = pendingPickKeyRef.current;
          if (!pending || selectionRef.current.size === 0) return false;
          return selectionFingerprint(selectionRef.current) === pending;
        },
        // Set-based subscription list. Returns a per-callback
        // unsubscribe (wave 63); the legacy `null` clears all.
        onSelectionChange: (cb): (() => void) => {
          // When `disableSelection` is on, the selection surface is
          // closed — no listeners will ever fire because the
          // Highlighter events are not wired in `highlighter.setup`
          // (see the `if (!disableSelection)` branch in the mount
          // IIFE). Warn so the subscriber knows its callback is
          // dead-code in this mode rather than silently never firing.
          if (disableSelectionRef.current) {
            // eslint-disable-next-line no-console
            console.warn(
              "[IfcViewer] onSelectionChange is a no-op when disableSelectionRef.current is true (callback will never fire).",
            );
            return () => undefined;
          }
          if (cb === null) {
            selectionListenersRef.current.clear();
            return () => undefined;
          }
          const listeners = selectionListenersRef.current;
          listeners.add(cb);
          return () => {
            listeners.delete(cb);
          };
        },
        // Task 22-amendment: subscription for model-load events.
        // Called by hooks that live ABOVE <IfcViewer> in the render
        // tree and need to re-run when the loaded-model set changes.
        // See loadedModelsListenersRef for the rationale.
        onLoadedModelsChange: (cb): (() => void) => {
          if (cb === null) {
            loadedModelsListenersRef.current.clear();
            return () => undefined;
          }
          const listeners = loadedModelsListenersRef.current;
          listeners.add(cb);
          return () => {
            listeners.delete(cb);
          };
        },
        // Task 21-next + Task 22: per-element property values from
        // the loaded fragments model. Uses the canonical TOE API
        // `FragmentsModel.getItemsData([ids], config)` which returns
        // `ItemData[]`.
        //
        // Task 22 fix: pass `relations: { IsDefinedBy: { attributes:
        // true, relations: false } }` so the property sets
        // (`IfcRelDefinesByProperties` results) surface alongside
        // the entity-level attributes. Without this config, TOE
        // returns only built-in attributes (Name, GlobalId, Tag,
        // etc.) and psets like `Pset_Foundation.01-nivel
        // constructivo` never appear.
        //
        // The returned ItemData has a nested IsDefinedBy array; we
        // flatten to `Record<string, string>` via the shared
        // `flattenItemData` helper so the existing PropertiesDrawer
        // parser (`key.indexOf(".")`) keeps working.
        getElementData: async (
          modelId: string,
          expressId: number,
        ): Promise<Record<string, string> | null> => {
          const fragments = fragmentsRef.current;
          if (!fragments) return null;
          const model = fragments.core.models.list.get(modelId);
          if (!model) return null;
          try {
            const data = await (
              model as {
                getItemsData: (
                  ids: number[],
                  config?: {
                    attributesDefault?: boolean;
                    relations?: Record<
                      string,
                      { attributes: boolean; relations: boolean }
                    >;
                  },
                ) => Promise<
                  Array<{
                    [name: string]:
                      | { value: unknown; type?: string }
                      | Array<Record<string, unknown>>
                      | undefined;
                  }>
                >;
              }
            ).getItemsData([expressId], {
              attributesDefault: true,
              relations: {
                IsDefinedBy: { attributes: true, relations: true },
              },
            });
            if (!data || data.length === 0) return null;
            return flattenItemData(data[0] as IfcItemData);
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn(
              "[IfcViewer] getElementData failed",
              modelId,
              expressId,
              err,
            );
            return null;
          }
        },
        getGlobalIds: async (
          modelId: string,
          expressIds: number[],
        ): Promise<Array<string | null> | null> => {
          const model = fragmentsRef.current?.core.models.list.get(modelId) as
            | { getGuidsByLocalIds?: (ids: number[]) => Promise<Array<string | null>> }
            | undefined;
          if (!model || typeof model.getGuidsByLocalIds !== "function") return null;
          try {
            return await model.getGuidsByLocalIds(expressIds);
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn("[IfcViewer] getGlobalIds failed", modelId, err);
            return null;
          }
        },
        getElementDataWithGuid: async (
          modelId: string,
          expressId: number,
        ): Promise<{ attributes: Record<string, string>; globalId: string | null } | null> => {
          const handle = handleSelfRef.current;
          if (!handle?.getGlobalIds) return null;
          const [data, guids] = await Promise.all([
            handle.getElementData(modelId, expressId),
            handle.getGlobalIds(modelId, [expressId]),
          ]);
          if (!data) return null;
          return mergeGuidIntoAttributes(data, guids?.[0] ?? null);
        },
        // Task 21-next + Task 22: per-model local-ID enumeration
        // for filter resolution.
        //
        // Task 22 fix: `FragmentsModel.items` is the internal
        // `ItemConfigController` (a wrapper around highlight/
        // visibility state with `size`, `setVisible`, etc.) —
        // NOT a Record of item IDs. Reading `Object.keys(items)`
        // returns the controller's own enumerable properties,
        // none of which are item IDs, so the old code returned an
        // empty Map and the filter pipeline never emitted
        // `Hider.set` calls.
        //
        // Switch to `model.getItemsIdsWithGeometry(): Promise<number[]>`
        // which returns all local IDs of items with geometry. The
        // values are TOE local IDs (not IFC express IDs in the
        // strict sense) — but downstream hider calls accept any
        // `Identifier` and TOE translates internally, so callers
        // can keep passing IFC express IDs without breakage.
        //
        // Returns a Promise — the parent hook (`useViewerExpressIdMaps`)
        // awaits this and updates local state, which triggers the
        // filter pipeline to re-evaluate.
        getAllModelExpressIds: async (): Promise<Map<string, number[]>> => {
          const out = new Map<string, number[]>();
          const fragments = fragmentsRef.current;
          if (!fragments) return out;
          for (const [modelId, model] of fragments.core.models.list) {
            try {
              const ids = await (
                model as unknown as {
                  getItemsIdsWithGeometry: () => Promise<number[]>;
                }
              ).getItemsIdsWithGeometry();
              if (Array.isArray(ids)) out.set(modelId, ids);
            } catch (err) {
              // eslint-disable-next-line no-console
              console.warn(
                "[IfcViewer] getItemsIdsWithGeometry failed for",
                modelId,
                err,
              );
            }
          }
          return out;
        },
        // Task 23 (Critic Option C): batched `getItemsData` extraction
        // for the in-memory inverted index used by custom filters.
        //
        // For each local ID in the model, fetch property data via
        // `model.getItemsData([id], { relations: { IsDefinedBy: ...
        // } })` (the same IsDefinedBy config as `getElementData`),
        // then flatten to `(localId, properties)`. The hook caller
        // (`useModelPropertyIndex`) feeds the result into
        // `buildInvertedIndex` for O(rules) filter evaluation.
        //
        // For large models the worker postMessage payload is the
        // bottleneck — chunking into batches (default 5000 IDs)
        // and yielding to the event loop between batches keeps the
        // UI responsive during index build. The build is async and
        // non-blocking; the model is visible immediately, the
        // index is filled in as each batch lands.
        getPropertyDataForModel: async (
          modelId: string,
          options?: { batchSize?: number },
        ): Promise<
          | Array<{ localId: number; properties: Record<string, string> }>
          | null
        > => {
          const fragments = fragmentsRef.current;
          if (!fragments) return null;
          const model = fragments.core.models.list.get(modelId);
          if (!model) return null;
          // Per-model policy: `_options?.batchSize` is the public chunk
          // size (wave 29: it now actually controls the chunk size — before
          // this wave the parameter was accepted and ignored while the loop
          // ran one RPC per element). Defaults to PROPERTY_CHUNK below;
          // `0`/`undefined` keeps the default.
          let localIds: number[] = [];
          try {
            localIds = await (
              model as unknown as {
                getItemsIdsWithGeometry: () => Promise<number[]>;
              }
            ).getItemsIdsWithGeometry();
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn(
              "[IfcViewer] getPropertyDataForModel: getItemsIdsWithGeometry failed",
              modelId,
              err,
            );
            return null;
          }
          if (!Array.isArray(localIds) || localIds.length === 0) return [];
          // The model can be disposed while this (long, chunked) walk is
          // in flight: a building switch, a version swap, or a viewer
          // remount re-registers it under the same id. Every remaining
          // getItemsData call then fails ("Model not found"), which used
          // to fall back to one RPC per element — thousands of failed
          // round-trips and an index built from empty rows. Detect it
          // and abort; the re-load notifies `onLoadedModelsChange`, and
          // `useModelPropertyIndex` rebuilds from the live instance.
          const stillLoaded = (): boolean =>
            fragmentsRef.current === fragments &&
            fragments.core.models.list.get(modelId) === model;
          const assertLoaded = (): void => {
            if (!stillLoaded()) throw new ModelUnloadedError(modelId);
          };
          const out: Array<{
            localId: number;
            properties: Record<string, string>;
          }> = [];
          const getItemsData = (
            model as unknown as {
              getItemsData: (
                ids: number[],
                config?: {
                  attributesDefault?: boolean;
                  relations?: Record<
                    string,
                    { attributes: boolean; relations: boolean }
                  >;
                },
              ) => Promise<
                Array<{
                  [name: string]:
                    | { value: unknown; type?: string }
                    | Array<Record<string, unknown>>
                    | undefined;
                }>
              >;
            }
          ).getItemsData.bind(model);
          // `.bind(model)` is load-bearing and stays: without it the TOE
          // source's `this._itemsManager` access throws in strict-mode ESM.
          //
          // Wave 29: batched. This used to be ONE worker round-trip PER
          // ELEMENT (`getItemsData([localId], …)` in a loop), self-documented
          // as "~5-10 s of background work" for a 5k-element model — and
          // every one of those RPCs queues on the same fragments worker that
          // answers the pick's `itemId → localId` translate and the two
          // highlight RPCs, so the first clicks after opening a building
          // were paying a queue behind 5,000 property lookups. The old
          // "NOT batched" note justified itself with the `.bind`/`this` race
          // above, which batching does not touch.
          //
          // Order is guaranteed by the engine: `getItemsData` is
          // `for (const id of _ids) result.push(this.getItemData(id))`
          // (`@thatopen/fragments/dist/index.mjs`, VirtualPropertiesController)
          // — one result slot per input id, in input order, with its
          // per-call cache cleared at both ends. Two belt braces, because
          // mis-associating properties with the wrong element would poison
          // every filter that reads this index:
          //   • an EMPTY id array means "every item in the model" to this
          //     API, so an empty chunk is never sent;
          //   • a batch whose result length disagrees with its input is
          //     discarded and that chunk alone is re-walked per element.
          const PROPERTY_CHUNK =
            options?.batchSize && options.batchSize > 0 ? options.batchSize : 256;
          const config = {
            attributesDefault: true,
            relations: { IsDefinedBy: { attributes: true, relations: true } },
          };
          const pushOne = (localId: number, item: unknown): void => {
            out.push({
              localId,
              properties: item
                ? flattenItemData(item as IfcItemData)
                : {},
            });
          };
          const fetchOne = async (localId: number): Promise<void> => {
            try {
              const data = await getItemsData([localId], config);
              pushOne(localId, data?.[0]);
            } catch (err) {
              assertLoaded();
              // eslint-disable-next-line no-console
              console.warn(
                "[IfcViewer] getPropertyDataForModel: getItemsData failed for localId",
                localId,
                err,
              );
              pushOne(localId, null);
            }
          };
          for (let i = 0; i < localIds.length; i += PROPERTY_CHUNK) {
            const chunk = localIds.slice(i, i + PROPERTY_CHUNK);
            if (chunk.length === 0) continue; // never ask for "all items"
            assertLoaded();
            let data: Awaited<ReturnType<typeof getItemsData>> | null = null;
            try {
              data = await getItemsData(chunk, config);
            } catch (err) {
              assertLoaded();
              // eslint-disable-next-line no-console
              console.warn(
                `[IfcViewer] getPropertyDataForModel: batched getItemsData failed for ${chunk.length} ids; falling back to per-element`,
                err,
              );
              data = null;
            }
            if (data && data.length === chunk.length) {
              for (let j = 0; j < chunk.length; j += 1) {
                pushOne(chunk[j]!, data[j]);
              }
            } else {
              // Mismatched/failed batch: isolate it, one element at a time,
              // so one bad id costs one row and never reorders the rest.
              for (const localId of chunk) {
                assertLoaded();
                await fetchOne(localId);
              }
            }
            // Yield between chunks so the UI thread stays responsive.
            await new Promise<void>((resolve) => setTimeout(resolve, 0));
          }
          return out;
        },
        // ─── search-set-style spatial structure query ───────────
        // Walks the IFC spatial tree, finds storey nodes, queries
        // their names via getItemsData (batched), and collects
        // descendant element TOE local IDs. Returns a map keyed by
        // storey name — the hook matches these to Dexie storey
        // records by name+modelId. All IDs are in TOE local space,
        // consistent with modelToExpressIds.
        getModelLevelLocalIds: async (modelId) => {
          const fragments = fragmentsRef.current;
          if (!fragments) return null;
          const model = fragments.core.models.list.get(modelId);
          if (!model) return null;
          try {
            // 1. Get spatial structure.
            const root = await (
              model as unknown as {
                getSpatialStructure: () => Promise<import("@thatopen/fragments").SpatialTreeItem>;
              }
            ).getSpatialStructure();

            // 2. Walk tree: collect storey nodes + their descendant element local IDs.
            // The spatial tree structure for container IFC entities:
            //   IFCBUILDINGSTOREY (category set, localId=null)
            //     → null (category=null, localId=<storey entity>, has Name property)
            //       → [element nodes with geometry]
            // So: match on category, then descend to the null child for the
            // storey entity's localId (used to query the Name), and collect
            // element localIds from grandchildren.
            interface StoreyNode {
              storeyLocalId: number;
              elementLocalIds: number[];
            }
            const storeyNodes: StoreyNode[] = [];

            const isSpatialContainer = (cat: string | null): boolean => {
              if (!cat) return false;
              const u = cat.toUpperCase();
              return (
                u.startsWith("IFCBUILDING") ||
                u.startsWith("IFCSITE") ||
                u.startsWith("IFCPROJECT")
              );
            };

            // eslint-disable-next-line no-inner-declarations -- recursive walk scoped here on purpose
            function walkTree(
              node: import("@thatopen/fragments").SpatialTreeItem,
            ): void {
              const isStorey =
                node.category?.toUpperCase() === "IFCBUILDINGSTOREY";
              if (isStorey) {
                // Storey node has localId=null — find the null-category
                // child that holds the actual storey entity's localId.
                if (node.children) {
                  for (const child of node.children) {
                    // The null-category child IS the storey entity.
                    if (child.category === null && child.localId !== null) {
                      storeyNodes.push({
                        storeyLocalId: child.localId,
                        elementLocalIds: [],
                      });
                      // Its children are elements.
                      if (child.children) {
                        for (const grandchild of child.children) {
                          collectElements(
                            grandchild,
                            storeyNodes[storeyNodes.length - 1]!
                              .elementLocalIds,
                          );
                        }
                      }
                    } else if (child.children) {
                      // Non-null children: continue walking.
                      for (const sub of child.children) {
                        walkTree(sub);
                      }
                    }
                  }
                }
              } else if (node.children) {
                for (const child of node.children) {
                  walkTree(child);
                }
              }
            }
            // eslint-disable-next-line no-inner-declarations -- recursive walk scoped here on purpose
            function collectElements(
              node: import("@thatopen/fragments").SpatialTreeItem,
              out: number[],
            ): void {
              // Skip spatial container categories and storeys.
              // Include nodes with real localIds (category may be an
              // element type like IFCWALL or null).
              if (
                !isSpatialContainer(node.category) &&
                node.localId !== null
              ) {
                out.push(node.localId);
              }
              if (node.children) {
                for (const child of node.children) {
                  collectElements(child, out);
                }
              }
            }
            walkTree(root);

            if (storeyNodes.length === 0) {
              return new Map();
            }

            // 3. Query storey names one-by-one (NOT batched).
            // `.bind(model)` preserves `this` — without it, TOE's
            // `this._itemsManager` throws "Cannot read properties of
            // undefined" in strict-mode ESM.
            const getItemsData = (
              model as unknown as {
                getItemsData: (
                  ids: number[],
                  config?: { attributesDefault?: boolean },
                ) => Promise<
                  Array<{
                    [name: string]: { value: unknown; type?: string } | undefined;
                  }>
                >;
              }
            ).getItemsData.bind(model);
            const storeyData: (Record<string, { value: unknown; type?: string } | undefined> | null)[] = [];
            for (const localId of storeyNodes.map((s) => s.storeyLocalId)) {
              try {
                const [data] = await getItemsData([localId], {
                  attributesDefault: true,
                });
                storeyData.push(data ?? null);
              } catch {
                storeyData.push(null);
              }
            }

            // 4. Build result: storey name → Set of element local IDs.
            const out = new Map<string, Set<number>>();
            for (let i = 0; i < storeyNodes.length; i++) {
              const data = storeyData[i];
              const rawName = data?.Name;
              const storeyName =
                rawName && typeof rawName === "object" && "value" in rawName
                  ? String(rawName.value ?? "")
                  : "";
              if (!storeyName) continue;
              const existing = out.get(storeyName);
              if (existing) {
                for (const id of storeyNodes[i]!.elementLocalIds) {
                  existing.add(id);
                }
              } else {
                out.set(
                  storeyName,
                  new Set(storeyNodes[i]!.elementLocalIds),
                );
              }
            }
            return out;
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn(
              "[IfcViewer] getModelLevelLocalIds failed",
              modelId,
              err,
            );
            return null;
          }
        },
        // ─── Task 21: spawn-point camera + storey/centroid accessors ───
        // These methods power LinkView's Stage 1 spawn-point UX:
        // the user clicks the LEFT (level-plan) pane to place a
        // navigation symbol, and the RIGHT (3D context) pane
        // switches to a restricted third-person camera locked at
        // 1.8m above the active storey. The two accessors below
        // (`getActiveStoreyFloorZ` / `getModelCentroid`) read
        // existing refs (levelPlanRef / fragmentsRef) so we don't
        // add new state.
        getActiveStoreyFloorZ: (): number | null => {
          // `levelPlanRef.current?.getActiveStoreyMeta()` returns
          // the full meta tuple or null; we project to just the
          // elevation. The optional chain handles the viewer
          // being mounted but the LevelPlanController not yet
          // created (the IIFE in mount assigns it asynchronously).
          return (
            levelPlanRef.current?.getActiveStoreyMeta()?.elevation ?? null
          );
        },
        getBaseCoordinates: (): [number, number, number] | null => {
          const core = fragmentsRef.current?.core as unknown as
            | CoordinatedCore
            | undefined;
          return core?.baseCoordinates ?? null;
        },
        getModelCentroid: (): { x: number; y: number; z: number } | null => {
          // Walk every loaded FragmentsModel and average their
          // `box` (THREE.Box3) midpoints. Return null if there
          // are no models OR every model's box is uninitialised
          // (the `box` getter returns a Box3 with Infinity
          // sentinels until `fragments.core.update()` resolves
          // the instances). Skip models with no usable box.
          const fragments = fragmentsRef.current;
          if (!fragments) return null;
          const models = fragments.core.models.list;
          if (!models || models.size === 0) return null;
          let sumX = 0;
          let sumY = 0;
          let sumZ = 0;
          let count = 0;
          for (const model of models.values()) {
            // FragmentsModel exposes a `box` getter that returns
            // a THREE.Box3 (same shape IfcViewer.tsx uses
            // elsewhere — e.g. the worldToScreen fallback path
            // and the LevelPlanController's boxer).
            const m = model as unknown as { box?: THREE.Box3 };
            const b = m.box;
            if (!b) continue;
            // Three.Box3 may have Infinity sentinels if the model
            // hasn't been initialised. The `isFinite()` check
            // rejects those (any single Infinity → false).
            if (
              !Number.isFinite(b.min.x) ||
              !Number.isFinite(b.min.y) ||
              !Number.isFinite(b.min.z) ||
              !Number.isFinite(b.max.x) ||
              !Number.isFinite(b.max.y) ||
              !Number.isFinite(b.max.z)
            ) {
              continue;
            }
            sumX += (b.min.x + b.max.x) / 2;
            sumY += (b.min.y + b.max.y) / 2;
            sumZ += (b.min.z + b.max.z) / 2;
            count += 1;
          }
          if (count === 0) return null;
          return { x: sumX / count, y: sumY / count, z: sumZ / count };
        },
        getLevelPlanDistance: (): number => {
          // Wave 58: the shared straight-down framing height. Reused
          // verbatim from @ff/viewer so the nav view's camera matches
          // the level-plan framing exactly.
          return LEVEL_PLAN_FRAME_DISTANCE;
        },
        setRestrictedThirdPerson: (
          eye: { x: number; y: number; z: number },
          target: { x: number; y: number; z: number },
          options?: { animate?: boolean },
        ): void => {
          // Bail out silently if the world isn't mounted yet
          // (the mount IIFE may not have completed).
          const world = worldRef.current;
          if (!world) return;
          // Cast through `unknown` because OBC.World's camera
          // is `OBC.OrthoPerspectiveCamera` whose `controls`
          // surface is `camera-controls` — same drift-clean
          // pattern used by zoom() / worldToScreen() / pickWorldPoint().
          const ctl = world.camera.controls as unknown as {
            setLookAt?: (
              ex: number,
              ey: number,
              ez: number,
              tx: number,
              ty: number,
              tz: number,
              transition?: boolean,
            ) => void;
            mouseButtons?: {
              left: number;
              middle: number;
              right: number;
              wheel: number;
            };
          };
          // Initial click: `animate: true` → camera-controls uses
          // its 0.2s smoothTime tween. The user sees the 3D view
          // glide to the spawn point and understands that the
          // third-person mode just engaged.
          // Drag updates: default (no flag) → instant setLookAt.
          // A tween would chase a target that's already moved,
          // producing a 0.2s lag between cursor and camera that
          // feels broken.
          const enableTransition = options?.animate === true;
          ctl?.setLookAt?.(
            eye.x,
            eye.y,
            eye.z,
            target.x,
            target.y,
            target.z,
            enableTransition,
          );
          // Surgical button disabling instead of
          // ctl.enabled=false. Setting enabled=false calls
          // ctl.cancel()→endDragging() which removes
          // document-level pointer listeners AND resets
          // canvas touchAction to "", causing the browser
          // to reinterpret pointer events as scroll gestures
          // and steal them from the wrapper div's
          // onPointerMove handler. Zeroing buttons keeps
          // ctl.enabled=true, preserving touchAction="none"
          // and the pointer pipeline, while producing no
          // user-visible camera motion.
          if (ctl?.mouseButtons) {
            ctl.mouseButtons.left = 0;
            ctl.mouseButtons.right = 0;
            ctl.mouseButtons.middle = 0;
            ctl.mouseButtons.wheel = 0;
          }
        },
        navigateTo: (
          eye: { x: number; y: number; z: number },
          target: { x: number; y: number; z: number },
        ): void => {
          const world = worldRef.current;
          if (!world) return;
          const ctl = world.camera.controls as unknown as {
            setLookAt?: (
              ex: number,
              ey: number,
              ez: number,
              tx: number,
              ty: number,
              tz: number,
              enableTransition?: boolean,
            ) => void;
          };
          ctl?.setLookAt?.(
            eye.x,
            eye.y,
            eye.z,
            target.x,
            target.y,
            target.z,
            false,
          );
        },

        // ── Task 23: floor-plan plane ───────────────────────────
        addFloorPlanPlane: (
          canvas: HTMLCanvasElement,
          worldBounds: {
            minX: number;
            minZ: number;
            maxX: number;
            maxZ: number;
          },
          elevation: number,
          options?: { opacity?: number; rotation?: number },
        ): string => {
          const w = worldRef.current;
          if (!w) {
            console.warn(
              "[IfcViewer] addFloorPlanPlane: world not ready",
            );
            return "";
          }
          // The clip plane sits at floorZ + 0.05 (see setFloorClipPlane).
          // The PDF plane must be BELOW the clip boundary so it's never
          // clipped by the renderer. 0.04 puts it 1 cm below the clip
          // plane — enough to avoid z-fighting but invisible to the eye.
          const PDF_OFFSET = 0.04;
          const placement = computeFloorPlanPlacement(
            worldBounds,
            elevation + PDF_OFFSET,
            options?.rotation,
          );
          const { width, depth } = placement;
          if (width <= 0 || depth <= 0) {
            console.warn(
              "[IfcViewer] addFloorPlanPlane: degenerate bounds",
              { width, depth },
            );
            return "";
          }
          const geom = new THREE.PlaneGeometry(width, depth); // toe-drift:allow -- PDF floor-plan overlay is a textured canvas quad; no TOE equivalent (reviewed 2026-11-04).
          // The PlaneGeometry lies in the XY plane by default.
          // Rotate -90° around X to lay it flat in the XZ plane.
          geom.rotateX(-Math.PI / 2);
          // The mesh is centred on the world bounds and turned about
          // its own centre by the calibration rotation.
          // Wave 63: the overlay used to look dim (hard-coded opacity
          // 0.40). Material now lives in floorPlanPlaneMaterial.ts:
          // caller-chosen opacity, unlit, not tone-mapped, sRGB,
          // anisotropic filtering for grazing views.
          const gl = (w.renderer as OBC.SimpleRenderer | undefined)?.three;
          const { texture, material } = createFloorPlanPlaneMaterial(canvas, {
            opacity: options?.opacity,
            maxAnisotropy: gl?.capabilities.getMaxAnisotropy(),
          });
          const mesh = new THREE.Mesh(geom, material); // toe-drift:allow -- PDF floor-plan overlay quad (see PlaneGeometry note).
          // The PDF plane is a large flat quad — its bounding
          // sphere is enormous. At grazing camera angles Three.js
          // frustum culling can falsely reject the mesh even though
          // parts of it are still in view, producing rectangular
          // cutouts. Frustum culling is disabled here — the GPU
          // handles per-fragment clipping, and this is a single
          // textured quad so the performance cost is negligible.
          mesh.position.set(
            placement.position.x,
            placement.position.y,
            placement.position.z,
          );
          mesh.rotation.y = placement.rotationY;
          mesh.frustumCulled = false;
          // Render the PDF after other scene geometry so it draws
          // on top of the floor-level model and the clipper visual
          // plane. Combined with depthWrite: false, this keeps the
          // overlay visible without z-fighting at grazing angles.
          mesh.renderOrder = 999;
          w.scene.three.add(mesh);
          const id = `floor-plan-plane-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
          floorPlanPlanesRef.current.set(id, {
            mesh,
            material,
            texture,
          });
          return id;
        },

        setFloorPlanPlaneOpacity: (id: string, opacity: number): void => {
          const entry = floorPlanPlanesRef.current.get(id);
          if (!entry) return;
          entry.material.opacity = clampFloorPlanOpacity(opacity);
        },

        removeFloorPlanPlane: (id: string): void => {
          const entry = floorPlanPlanesRef.current.get(id);
          if (!entry) return;
          entry.mesh.removeFromParent();
          entry.material.dispose();
          entry.texture.dispose();
          floorPlanPlanesRef.current.delete(id);
        },

        // ── Task 23.1: floor clip plane ──────────────────────────
        setFloorClipPlane: (enabled: boolean, floorZ: number): void => {
          const world = worldRef.current;
          const comps = componentsRef.current;
          if (!world || !comps) return;

          const clipper = comps.get(OBC.Clipper);

          // Remove any existing floor clip plane first.
          if (floorClipPlaneIdRef.current) {
            removeClippingPlanesById(clipper, [floorClipPlaneIdRef.current]);
            floorClipPlaneIdRef.current = null;
          }

          if (!enabled) return;

          clipper.enabled = true;

          // Match the scene background (#f2f3f4) at 10% opacity
          // so the plane is a subtle overlay rather than a
          // distracting purple slab.
          clipper.config.color = new THREE.Color("#f2f3f4");
          clipper.config.opacity = 0.1;

          const Z_FIGHT_OFFSET = 0.05;
          const normal = new THREE.Vector3(0, -1, 0);
          const point = new THREE.Vector3(0, floorZ + Z_FIGHT_OFFSET, 0);

          const planeId = clipper.createFromNormalAndCoplanarPoint(
            world,
            normal,
            point,
          );
          floorClipPlaneIdRef.current = planeId;

          // Keep the TransformControls (draggable arrow) that OBC
          // attaches by default — the user can grab the arrow to
          // adjust the clipping height interactively. The original
          // "controls steal pointer events" issue was actually the
          // ClipStyler PlanMode bug (fixed below), not the controls
          // themselves.

          // Belt-and-suspenders: OBC's ClipStyler component sets the
          // camera to PlanMode (Orthographic projection, minDistance=1,
          // maxDistance=1) when a clipping plane is created via its
          // `world` setter. PlanMode locks distance → DOLLY is dead,
          // scroll pans sideways. Reset to Orbit + Perspective.
          {
            const cam = world.camera as unknown & {
              projection?: { set(value: string): void };
              set?(mode: string): void;
            };
            cam.projection?.set("Perspective");
            (cam as unknown as { set(mode: string): void }).set?.("Orbit");
          }
        },

        releaseRestrictedCamera: (): void => {
          // Counterpart to setRestrictedThirdPerson. We only
          // re-enable Orbit nav and wheel zoom — the camera
          // itself stays where it was last placed (the user
          // continues from the spawn-point view, not a
          // hard reset to the default 3D pose).
          const world = worldRef.current;
          if (!world) return;
          restoreOrbitMouseButtons(world);
        },

        // ── Task 24: default camera reset ─────────────────────────
        resetCameraToDefault: (): void => {
          const world = worldRef.current;
          // Safe to call before the world is mounted — bail out
          // silently (same contract as setRestrictedThirdPerson).
          if (!world) return;

          // ── 1. Merged bounding box of every loaded model ──────
          // FragmentsModel exposes a `box` getter (THREE.Box3) that
          // recomputes from the model's current instance transforms.
          // Models whose box isn't initialised yet carry Infinity
          // sentinels — those are skipped.
          let minX = Infinity;
          let minY = Infinity;
          let minZ = Infinity;
          let maxX = -Infinity;
          let maxY = -Infinity;
          let maxZ = -Infinity;
          let hasBounds = false;
          const fragments = fragmentsRef.current;
          if (fragments) {
            const models = fragments.core.models.list;
            if (models && models.size > 0) {
              for (const model of models.values()) {
                const m = model as unknown as { box?: THREE.Box3 };
                const b = m.box;
                if (!b) continue;
                if (
                  !Number.isFinite(b.min.x) ||
                  !Number.isFinite(b.min.y) ||
                  !Number.isFinite(b.min.z) ||
                  !Number.isFinite(b.max.x) ||
                  !Number.isFinite(b.max.y) ||
                  !Number.isFinite(b.max.z)
                ) {
                  continue;
                }
                minX = Math.min(minX, b.min.x);
                minY = Math.min(minY, b.min.y);
                minZ = Math.min(minZ, b.min.z);
                maxX = Math.max(maxX, b.max.x);
                maxY = Math.max(maxY, b.max.y);
                maxZ = Math.max(maxZ, b.max.z);
                hasBounds = true;
              }
            }
          }

          // ── 2. Frame the model ─────────────────────────────────
          // Target = the centre of the merged box; distance = the
          // bounding-sphere radius × the fit factor (so a 5 cm model
          // and a 500 m model are both framed). No model → a safe
          // default pose around the world origin.
          const center = hasBounds
            ? {
                x: (minX + maxX) / 2,
                y: (minY + maxY) / 2,
                z: (minZ + maxZ) / 2,
              }
            : { x: 0, y: 0, z: 0 };
          const radius = hasBounds
            ? 0.5 *
              Math.hypot(maxX - minX, maxY - minY, maxZ - minZ)
            : 0;
          const distance =
            radius > 0 ? radius * VIEW_DISTANCE_FIT_FACTOR : DEFAULT_VIEW_DISTANCE;

          // Unit vector from the target towards the camera: above,
          // in front and to the right of the model.
          const dirX =
            Math.cos(DEFAULT_VIEW_PITCH) * Math.cos(DEFAULT_VIEW_YAW);
          const dirY = Math.sin(DEFAULT_VIEW_PITCH);
          const dirZ =
            Math.cos(DEFAULT_VIEW_PITCH) * Math.sin(DEFAULT_VIEW_YAW);

          const eye = {
            x: center.x + dirX * distance,
            y: center.y + dirY * distance,
            z: center.z + dirZ * distance,
          };

          // ── 3. Fully re-enable the orbit navigation ────────────
          // Same mouse-button restore as releaseRestrictedCamera,
          // plus the camera-controls `enabled` flag (the restricted
          // third-person mode leaves the controls switched off).
          restoreOrbitMouseButtons(world);
          const ctl = world.camera.controls as unknown as {
            enabled?: boolean;
            setLookAt?: (
              ex: number,
              ey: number,
              ez: number,
              tx: number,
              ty: number,
              tz: number,
              enableTransition?: boolean,
            ) => void;
          };
          if (ctl) ctl.enabled = true;

          // The floor-plan / clipper path can leave the camera in
          // the orthographic plan projection. Reset to the default
          // perspective + orbit nav before framing the model.
          const cam = world.camera as unknown & {
            projection?: { set(value: string): void };
            set?(mode: string): void;
          };
          cam.projection?.set("Perspective");
          cam.set?.("Orbit");

          // ── 4. Move the camera ─────────────────────────────────
          // `enableTransition = true` → camera-controls tweens the
          // move over ~0.2s, so the switch back to Navigate reads
          // as a deliberate glide instead of a jump cut.
          ctl?.setLookAt?.(
            eye.x,
            eye.y,
            eye.z,
            center.x,
            center.y,
            center.z,
            true,
          );
        },

        // ── Tasks module (Day 2): pose capture / restore ────────
        getPose: (options?: { silent?: boolean }): ViewerPose | null => {
          const world = worldRef.current;
          // Same bail-out contract as the camera methods above.
          if (!world) return null;
          // Drift-clean cast through `unknown` (camera-controls
          // surface), matching zoom() / worldToScreen() / the
          // Task 30 restricted-person code.
          const cam = world.camera as unknown as {
            three?: {
              position?: { x: number; y: number; z: number };
              fov?: number;
              type?: string;
            };
            controls?: {
              getTarget?: (out: THREE.Vector3) => unknown;
            };
          };
          const three = cam.three;
          const ctl = cam.controls;
          if (!three?.position || !ctl?.getTarget) return null;
          // camera-controls only writes into a real `THREE.Vector3`
          // (`out.isVector3`); a plain object is silently ignored and
          // the target read back as the origin.
          const out = new THREE.Vector3();
          ctl.getTarget(out);
          // Per-frame readers (LinkView's camera follow) pass
          // `silent` so the breadcrumb ring only records real saves.
          if (!options?.silent) tel.breadcrumb("viewpoint", "save");
          return {
            pos: [three.position.x, three.position.y, three.position.z],
            target: [out.x, out.y, out.z],
            // Orthographic cameras have no fov; the fallback keeps
            // the record shape total (persp default is 45 in OBC).
            fov:
              typeof three.fov === "number" ? three.fov : 45,
            isOrtho: three.type === "OrthographicCamera",
          };
        },
        setViewPose: (
          pose: ViewerPose,
          options?: { animate?: boolean },
        ): void => {
          const world = worldRef.current;
          if (!world) return;
          // Wave 73: a host-restored pose wins over fit-on-first-load.
          cameraMovedByHostRef.current = true;
          const cam = world.camera as unknown as {
            three?: {
              fov?: number;
              updateProjectionMatrix?: () => void;
            };
            controls?: {
              setLookAt?: (
                px: number,
                py: number,
                pz: number,
                tx: number,
                ty: number,
                tz: number,
                transition?: boolean,
              ) => unknown;
            };
            projection?: { set(value: string): void };
          };
          // Projection first. Same access pattern as the
          // ClipStyler belt-and-suspenders reset above.
          cam.projection?.set(pose.isOrtho ? "Orthographic" : "Perspective");
          // fov only exists on the perspective camera; guard on the
          // actual property so an in-flight projection swap can't
          // write onto the ortho camera.
          if (!pose.isOrtho && typeof cam.three?.fov === "number") {
            cam.three.fov = pose.fov;
            cam.three.updateProjectionMatrix?.();
          }
          cam.controls?.setLookAt?.(
            pose.pos[0],
            pose.pos[1],
            pose.pos[2],
            pose.target[0],
            pose.target[1],
            pose.target[2],
            options?.animate === true,
          );
          tel.breadcrumb("viewpoint", "restore");
        },
        // ── Day-3 location snapshot (3D) ─────────────────────
        // Same-frame capture: force a render(), then read the canvas
        // toDataURL before the WebGL drawing buffer clears. Drift-clean
        // (no raw three import). Any failure → null (placeholder).
        getSnapshot: (maxWidthPx = 400): string | null => {
          const world = worldRef.current;
          if (!world) return null;
          const renderer = world.renderer as OBC.SimpleRenderer | undefined;
          if (!renderer) return null;
          const three = renderer.three as unknown as
            | {
                render?: (scene: unknown, camera: unknown) => void;
                domElement?: HTMLCanvasElement;
              }
            | undefined;
          const scene = (world.scene as { three?: unknown } | undefined)?.three;
          const camera = (world.camera as { three?: unknown } | undefined)?.three;
          const dom = three?.domElement;
          if (!three?.render || !dom || !scene || !camera) return null;
          try {
            // Leave motion mode first: full pixel ratio, every tile drawn.
            navSpeedupsRef.current?.forceRest();
            three.render(scene, camera);
            return canvasToJpeg(dom, maxWidthPx);
          } catch {
            return null;
          }
        },
        // ── Wave 12: 3D measurement tool mode ────────────────────
        setMeasureMode: (
          mode: MeasureMode,
          variant?: MeasureVariant,
        ): void => {
          // Always disarm the current session first so switching
          // variants cancels the previous component's in-flight state.
          deactivateMeasure3D();

          // Wave 67: with a level plan open, the plan's own line tool is
          // THE length measurer (it snaps to the projected drawing lines
          // and labels them). Before this, arming the 3D components on top
          // of the armed plan tool made every click create both a plan line
          // and a hidden-under-the-plan 3D line, and disarming left the plan
          // tool listening. Plan open: select / length => (re)arm the plan
          // tool exclusively; any other variant => plan tool off, 3D on.
          if (levelPlanRef.current?.activeStoreyName) {
            if (mode === "select" || variant === "length") {
              setActiveTool("measure");
              pushMeasureReadout(null);
              return;
            }
            setActiveTool("navigation");
          }

          if (mode === "select") {
            pushMeasureReadout(null);
            return;
          }

          if (!variant) {
            // eslint-disable-next-line no-console
            console.warn(
              "[IfcViewer] setMeasureMode('measure') requires a variant.",
            );
            return;
          }
          if (!(variant in MEASURE_COMPONENT_CLASSES)) {
            // eslint-disable-next-line no-console
            console.warn(
              `[IfcViewer] unsupported measurement variant: ${String(variant)}`,
            );
            return;
          }
          const world = worldRef.current;
          const components = componentsRef.current;
          if (!world || !components) return;
          activateMeasure3D(variant);
          // Reset the chip until the first pointer move reports a value.
          pushMeasureReadout(null);
        },
        clearMeasurements: (): void => {
          // Wave 63: clear every type, not only the active one (and
          // also when no type is armed — deselecting the tool only
          // disables it, its measurements stay on screen).
          clearAllMeasure3D();
          const p = planSystem();
          if (p) p.sys.clearDrawing(p.drawing);
          emitMeasurements();
          pushMeasureReadout(null);
        },
        onMeasureReadout: (cb): void => {
          measureReadoutCbRef.current = cb;
        },
        isMeasureInProgress: (): boolean => {
          const active = measure3DRef.current;
          if (!active || !active.component.enabled) return false;
          return isMeasureInProgress(active.component, active.variant);
        },
        finishMeasureCreation: (): void => {
          finishMeasure3DRef.current?.();
        },
        getMeasurements: (): MeasurementEntry[] => allMeasurementEntries(),
        onMeasurementsChange: (cb): void => {
          measureListCbRef.current = cb;
          measureBookRef.current.onValueResolved = cb ? emitMeasurements : null;
        },
        deleteMeasurement: (id: string): void => {
          if (id.startsWith("plan:")) {
            const p = planSystem();
            if (p) p.sys.deleteItems(p.drawing, [id.slice(5)]);
            emitMeasurements();
            return;
          }
          const hit = measureBookRef.current.find(measureSources(), id);
          if (!hit) return;
          if (measureActiveIdRef.current === id) measureActiveIdRef.current = null;
          try {
            (hit.component as MeasureComponentLike).list?.delete(hit.item);
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn("[IfcViewer] deleteMeasurement failed:", err);
          }
          emitMeasurements();
        },
        focusMeasurement: async (
          id: string | null,
          opts?: { focus?: boolean },
        ): Promise<boolean> => {
          if (id === null) {
            setActiveMeasureMark(null);
            return true;
          }
          let bounds: Awaited<ReturnType<typeof focusBoundsAsync>> = null;
          if (id.startsWith("plan:")) {
            const p = planSystem();
            const item = p?.sys
              .listItems(p.drawing)
              .find((i) => i.uuid === id.slice(5));
            if (!p || !item) return false;
            if (opts?.focus === false) return true;
            const a = p.drawing.three.localToWorld(
              new THREE.Vector3(item.pointA.x, 0, item.pointA.z),
            );
            const b = p.drawing.three.localToWorld(
              new THREE.Vector3(item.pointB.x, 0, item.pointB.z),
            );
            bounds = await focusBoundsAsync("length", { start: a, end: b });
          } else {
            const hit = measureBookRef.current.find(measureSources(), id);
            if (!hit) return false;
            setActiveMeasureMark(id);
            if (opts?.focus === false) return true;
            bounds = await focusBoundsAsync(hit.variant, hit.item);
          }
          const world = worldRef.current;
          const cam = world?.camera;
          if (!bounds || !cam?.controls || !cam.three) return true;
          const target = new THREE.Vector3();
          cam.controls.getTarget(target);
          const dir = cam.three.position.clone().sub(target);
          if (dir.lengthSq() < 1e-6) dir.set(1, 1, 1);
          dir.normalize();
          const c = bounds.center;
          const dist = Math.max(bounds.radius * 3, 3);
          void cam.controls.setLookAt(
            c.x + dir.x * dist,
            c.y + dir.y * dist,
            c.z + dir.z * dist,
            c.x,
            c.y,
            c.z,
            true,
          );
          requestRender("measure-focus");
          return true;
        },
        cancelMeasureCreation: (): void => {
          const active = measure3DRef.current;
          if (!active) return;
          try {
            active.component.cancelCreation?.();
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn("[IfcViewer] measure cancelCreation failed:", err);
          }
          pushMeasureReadout(null);
        },
        // ── Wave 13: 3D section planes ─────────────────────────
        addSectionPlane: (point, normal, options): boolean =>
          addSectionPlaneImpl(point, normal, options),
        updateSectionPlane: (index, data): boolean => {
          const comps = componentsRef.current;
          const entry = sectionPlanesRef.current[index];
          if (!comps || !entry) return false;
          try {
            const clipper = comps.get(OBC.Clipper);
            const plane = clipper.list.get(entry.id) as
              | {
                  setFromNormalAndCoplanarPoint?: (n: THREE.Vector3, p: THREE.Vector3) => void;
                  onDraggingEnded?: { trigger: () => void };
                }
              | undefined;
            if (!plane?.setFromNormalAndCoplanarPoint) return false;
            plane.setFromNormalAndCoplanarPoint(
              new THREE.Vector3(data.normal.x, data.normal.y, data.normal.z),
              new THREE.Vector3(data.point.x, data.point.y, data.point.z),
            );
            // A styled plane redraws its cut outline on this event (the same one a drag ends with).
            plane.onDraggingEnded?.trigger();
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn("[IfcViewer] updateSectionPlane failed:", err);
            return false;
          }
          entry.point = { ...data.point };
          entry.normal = { ...data.normal };
          requestRender("section-update");
          return true;
        },
        removeSectionPlane: (index): void => {
          const comps = componentsRef.current;
          const entry = sectionPlanesRef.current[index];
          if (!comps || !entry) return;
          try {
            removeClippingPlanesById(comps.get(OBC.Clipper), [entry.id]);
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn("[IfcViewer] removeSectionPlane failed:", err);
            return;
          }
          sectionPlanesRef.current.splice(index, 1);
          requestRender("section-remove");
          tel.breadcrumb("section", "plane-remove", { count: sectionPlanesRef.current.length });
        },
        flipLastSectionPlane: (): void => {
          const world = worldRef.current;
          const comps = componentsRef.current;
          const planes = sectionPlanesRef.current;
          const last = planes[planes.length - 1];
          if (!world || !comps || !last) return;
          // Delete the most recent plane (its ClipStyler edges
          // auto-dispose via the plane's onDisposed link).
          try {
            const clipper = comps.get(OBC.Clipper);
            removeClippingPlanesById(clipper, [last.id]);
          } catch (err) {
            // eslint-disable-next-line no-console
            console.warn("[IfcViewer] flipLastSectionPlane failed:", err);
            return;
          }
          sectionPlanesRef.current.pop();
          // Recreate at the same point with the negated normal.
          addSectionPlaneImpl(last.point, {
            x: -last.normal.x,
            y: -last.normal.y,
            z: -last.normal.z,
          });
          tel.breadcrumb("section", "plane-flip", { count: sectionPlanesRef.current.length });
        },
        clearSectionPlanes: (): void => {
          const comps = componentsRef.current;
          const ids = sectionPlanesRef.current.map((p) => p.id);
          if (comps && ids.length) {
            try {
              const clipper = comps.get(OBC.Clipper);
              removeClippingPlanesById(clipper, ids);
            } catch (err) {
              // eslint-disable-next-line no-console
              console.warn("[IfcViewer] clearSectionPlanes failed:", err);
            }
          }
          sectionPlanesRef.current = [];
          tel.breadcrumb("section", "planes-clear", { count: sectionPlanesRef.current.length });
        },
        getSectionPlaneCount: (): number =>
          sectionPlanesRef.current.length,
        getSectionPlanes: (): SectionPlaneData[] =>
          sectionPlanesRef.current.map((p) => ({
            point: { ...p.point },
            normal: { ...p.normal },
          })),
        requestRender: (reason?: string): void =>
          requestRender(reason ? `external:${reason}` : "external"),
        getRenderStats: (): RenderSchedulerStats | null =>
          rodRef.current?.stats() ?? null,
      }, (reason) => requestRender(reason));
      handleSelfRef.current = handle;
      return handle;
      },
      [],
    );

    // ---------- render ----------

    const style = useMemo(
      () => ({
        position: "relative" as const,
        width: "100%",
        height: "100%",
        minHeight: 240,
        background: "#f2f3f4",
        overflow: "hidden",
      }),
      [],
    );

    return (
      <div
        ref={containerRef}
        className={className ?? "ifc-viewer"}
        style={style}
        data-project-id={_projectId}
        data-active-building-id={activeBuildingId ?? ""}
      >
        {/* Stats overlay removed 2026-06-23 (Maintainer directive).
            The previous panel showed models / storeys / building id +
            a Stats.js FPS/MS/MB tile. A follow-up can reintroduce
            them behind a `showStats` prop if a developer needs them
            for profiling. */}
        {loadingOverlay && !ffViewerSessionLoadedOnce && (!isReady || isStreaming) && (
          <div
            style={{
              // Wave 42: FULL-SCREEN. The overlay used to be absolute
              // inside the viewer container, so the toolbar, task pins
              // and rail stayed visible mid-load ("I can see the tasks
              // while the model loads — not useful"). Fixed + inset 0
              // escapes the viewer box and covers the whole viewport;
              // z 9999 clears every chrome layer (toolbar z22, panels,
              // pins, rail). No ancestor applies transform/filter, so
              // fixed resolves against the viewport.
              // Wave 56-demo: the overlay is the ONLY thing on screen
              // while models load — opaque, full viewport, above every
              // floating toolbar/panel (z 9999 > toolbar z 22), so the
              // user sees a clean loading screen instead of a dimmed
              // toolbar bleeding through. Light theme to match the app
              // (maintainer: "make it white to be similar to the rest of
              // the app"), and it shows ONCE per session (module flag
              // above) so module switches never re-trigger it.
              position: "fixed",
              inset: 0,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              gap: 12,
              // Wave 56-demo: opaque light background matching the
              // app's light chrome (was the dark rgba(10,13,18)).
              background: "#f2f3f4",
              color: "#1f2329",
              fontFamily: "system-ui, sans-serif",
              fontSize: 14,
              zIndex: 9999,
            }}
            data-testid="viewer-loading-overlay"
          >
            {/* Wave 33: the spinner keyframe lives here so the overlay is
                self-contained (no dependency on a host app's stylesheet). */}
            <style>{`@keyframes ff-viewer-spin { to { transform: rotate(360deg); } }`}</style>
            <div
              style={{
                width: 28,
                height: 28,
                borderRadius: "50%",
                border: "3px solid rgba(31, 35, 41, 0.18)",
                borderTopColor: "#1f2329",
                animation: "ff-viewer-spin 0.8s linear infinite",
              }}
              aria-hidden
            />
            {isStreaming
              ? loadProgress && loadProgress.total > 1
                ? `Loading model ${Math.min(loadProgress.done + 1, loadProgress.total)} of ${loadProgress.total}…`
                : "Loading model geometry…"
              : "Initializing 3D viewer…"}
          </div>
        )}
        {loadingOverlay &&
          ((backgroundStreaming && !isStreaming) ||
            // Wave 63: later loads in a session (the full-screen overlay
            // shows once per session) got no feedback at all — show the
            // chip whenever a load streams and the overlay is hidden.
            (isStreaming && isReady && ffViewerSessionLoadedOnce)) && (
          // Wave 61: non-blocking "still loading" chip — the viewer is
          // usable (clicks are answered) while the rest of the view fills in.
          <div
            style={{
              position: "absolute",
              left: "50%",
              bottom: 16,
              transform: "translateX(-50%)",
              display: "flex",
              alignItems: "center",
              gap: 8,
              padding: "6px 12px",
              background: "rgba(255, 255, 255, 0.92)",
              color: "#1f2329",
              border: "1px solid rgba(31, 35, 41, 0.12)",
              borderRadius: 999,
              boxShadow: "0 1px 4px rgba(0, 0, 0, 0.12)",
              fontFamily: "system-ui, sans-serif",
              fontSize: 12,
              pointerEvents: "none",
              zIndex: 21,
            }}
            role="status"
            aria-live="polite"
            data-testid="viewer-streaming-chip"
          >
            <style>{`@keyframes ff-viewer-spin { to { transform: rotate(360deg); } }`}</style>
            <div
              style={{
                width: 12,
                height: 12,
                borderRadius: "50%",
                border: "2px solid rgba(31, 35, 41, 0.18)",
                borderTopColor: "#1f2329",
                animation: "ff-viewer-spin 0.8s linear infinite",
              }}
              aria-hidden
            />
            {isStreaming && loadProgress && loadProgress.total > 1
              ? `Loading model ${Math.min(loadProgress.done + 1, loadProgress.total)} of ${loadProgress.total}…`
              : "Loading model…"}
          </div>
        )}
        {loadError && (
          <div
            style={{
              position: "absolute",
              top: 8,
              left: 8,
              display: "flex",
              alignItems: "center",
              gap: 8,
              padding: "6px 6px 6px 10px",
              background: "rgba(180, 60, 60, 0.85)",
              color: "#fff",
              fontFamily: "system-ui, sans-serif",
              fontSize: 12,
              borderRadius: 4,
              zIndex: 21,
            }}
            role="alert"
            data-testid="viewer-load-error"
          >
            <span>Viewer: {loadError.message}</span>
            {/* Wave 63: dismissable — it also resets on the next load pass. */}
            <button
              type="button"
              aria-label="Dismiss error"
              data-testid="viewer-load-error-dismiss"
              onClick={() => setLoadError(null)}
              style={{
                border: "none",
                background: "transparent",
                color: "#fff",
                fontSize: 14,
                lineHeight: 1,
                cursor: "pointer",
                padding: "0 4px",
              }}
            >
              ×
            </button>
          </div>
        )}
      </div>
    );
  },
);

export default IfcViewer;

export { IfcViewer };
